    <Variable name="title.font" description="Title Font" type="font" family="Instrument Sans" default="normal 400 14px $(family)" value="normal 700 16px Instrument Sans"/>
    <Variable name="text.font" description="Text Font" type="font" family="Instrument Sans" default="normal 400 14px $(family)" value="normal 400 18px Instrument Sans"/>
</Group>
