</Group>
<Group description="Post Page Options" select="#main">
    <Variable name="breadcrumb" description="Post Breadcrumbs" type="length" default="1px" min="0px" max="1px" value="0px"/>
    <Variable name="cmm.count" description="Comments Count" type="length" default="1px" min="0px" max="1px" value="0px"/>
    <Variable name="postnav" description="Post Navigation" type="length" default="1px" min="0px" max="1px" value="0px"/>
</Group>
<Group description="Footer ADS" selector="#footer-ads-wrap">
    <Variable name="footerad.onpost" description="Show on Post Page" type="length" default="1px" min="0px" max="1px" value="1px"/>
</Group>
<Group description="Theme Footer" selector="#footer-wrapper">
    <Variable name="footer.bg" description="Footer Background" type="color" default="#15171A" value="#000000"/>
    <Variable name="footer.color" description="Footer Color" type="color" default="#FFFFFF" value="#4285F4"/>
    <Variable name="footer.text.color" description="Footer Text Color" type="color" default="#BABABA" value="#d52c1f"/>
    <Variable name="footer.hover.color" description="Footer Hover Color" type="color" default="$(main.color)" value="#BA67C8"/>
</Group>
<Group description="Footer Bar" selector=".footerbar">
    <Variable name="footerbar.bg" description="Footer Bar Background" type="color" default="#0f1012" value="#000000"/>
    <Variable name="footerbar.color" description="Footer Bar Color" type="color" default="#FCFCFC" value="#fafafa"/>
    <Variable name="footerbar.hover.color" description="Footer Bar Hover Color" type="color" default="$(main.color)" value="#BA67C8"/>
</Group>
<Group description="Theme Buttons">
    <Variable name="button.bg" description="Button Background" type="color" default="$(main.color)" value="#0036b5"/>
    <Variable name="button.color" description="Button Color" type="color" default="#FFFFFF" value="#ffffff"/>
    <Variable name="button.hover.bg" description="Button Hover Background" type="color" default="#0036b5" value="#866100"/>
    <Variable name="button.hover.color" description="Button Hover Color" type="color" default="#FFFFFF" value="#ffffff"/>
</Group>
<Group description="Theme Fonts (Reset)">
    <!-- Site Font -->
    <Variable name="mainfont.italic" description="Main Font Italic" type="font" default="italic 400 14px $(main.font.family)" value="italic 400 14px Instrument Sans"/>
    <Variable name="mainfont.medium" description="Main Font Medium" type="font" default="normal 500 14px $(main.font.family)" value="normal 500 14px Instrument Sans"/>
    <Variable name="mainfont.mediumitalic" description="Main Font Medium Italic" type="font" default="italic 500 14px $(main.font.family)" value="italic 500 14px Instrument Sans"/>
    <Variable name="mainfont.bold" description="Main Font Bold" type="font" default="normal 700 14px $(main.font.family)" value="normal bold 14px Instrument Sans"/>
    <Variable name="mainfont.bolditalic" description="Main Font Bold Italic" type="font" default="italic 700 14px $(main.font.family)" value="italic bold 14px Instrument Sans"/>
    <!-- Menu Font -->
    <Variable name="menufont.italic" description="Menu Font Italic" type="font" default="italic 400 14px $(menu.font.family)" value="italic 400 14px Instrument Sans"/>
    <Variable name="menufont.bold" description="Menu Font Bold" type="font" default="normal 700 14px $(menu.font.family)" value="normal bold 14px Instrument Sans"/>
    <Variable name="menufont.bolditalic" description="Menu Font Bold Italic" type="font" default="italic 700 14px $(menu.font.family)" value="italic bold 14px Instrument Sans"/>
    <!-- Title Font -->
    <Variable name="titlefont.italic" description="Title Font Italic" type="font" default="italic 400 14px $(title.font.family)" value="italic 400 14px Instrument Sans"/>
    <Variable name="titlefont.bold" description="Title Font Bold" type="font" default="normal 700 14px $(title.font.family)" value="normal bold 14px Instrument Sans"/>
    <Variable name="titlefont.bolditalic" description="Title Font Bold Italic" type="font" default="italic 700 14px $(title.font.family)" value="italic bold 14px Instrument Sans"/>
    <!-- Text Font -->
    <Variable name="textfont.italic" description="Text Font Italic" type="font" default="italic 400 14px $(text.font.family)" value="italic 400 14px Instrument Sans"/>
    <Variable name="textfont.medium" description="Text Font Medium" type="font" default="normal 500 14px $(text.font.family)" value="normal 500 14px Instrument Sans"/>
    <Variable name="textfont.mediumitalic" description="Text Font Medium Italic" type="font" default="italic 500 14px $(text.font.family)" value="italic 500 14px Instrument Sans"/>
    <Variable name="textfont.bold" description="Text Font Bold" type="font" default="normal 700 14px $(text.font.family)" value="normal bold 14px Instrument Sans"/>
    <Variable name="textfont.bolditalic" description="Text Font Bold Italic" type="font" default="italic 700 14px $(text.font.family)" value="italic bold 14px Instrument Sans"/>
</Group>
<!-- Hidden Variables -->
<Variable name="body.background.color" description="Comments Background" hideEditor="true" type="color" default="rgba(255,255,255,0)"  value="#fdfdfd"/>
<Variable name="body.title.color" description="Comments Color" hideEditor="true" type="color" default="$(title.color)" value="#15161a"/>
<Variable name="body.text.color" description="Comments Text Color" hideEditor="true" type="color" default="$(text.color)"  value="#47474a"/>
<Variable name="body.link.color" description="Comments Link Color" hideEditor="true" type="color" default="$(main.color)"  value="#ff9800"/>
<Variable name="body.text.font" description="Comments Font 1" hideEditor="true" type="font" default="normal 400 14px Instrument Sans, Arial, sans-serif !important"  value="normal 400 14px Instrument Sans, Arial, sans-serif !important"/>
<Variable name="body.action.font.large" description="Comments Font 2" hideEditor="true" type="font" default="normal 700 14px Instrument Sans, Arial, sans-serif !important"  value="normal 700 14px Instrument Sans, Arial, sans-serif !important"/>
*/

/*-- Instrument Sans is loaded in the document head --*/
/*-- Font Awesome Free 5.15.1 (WOFF2) --*/
@font-face{font-family:"Font Awesome 5 Brands";font-display:swap;font-style:normal;font-weight:400;src:url(https://cdnjs.cloudflare.com/ajax/libs/font-awesome/5.15.1/webfonts/fa-brands-400.woff2) format("woff2")}.fab{font-family:"Font Awesome 5 Brands";font-weight:400}
@font-face{font-family:"Font Awesome 5 Free";font-display:swap;font-style:normal;font-weight:400;src:url(https://cdnjs.cloudflare.com/ajax/libs/font-awesome/5.15.1/webfonts/fa-regular-400.woff2) format("woff2")}.far{font-family:"Font Awesome 5 Free";font-weight:400}
@font-face{font-family:"Font Awesome 5 Free";font-display:swap;font-style:normal;font-weight:900;src:url(https://cdnjs.cloudflare.com/ajax/libs/font-awesome/5.15.1/webfonts/fa-solid-900.woff2) format("woff2")}.fa, .far, .fas{font-family:"Font Awesome 5 Free"}.fa, .fas{font-weight:900}

/*-- CSS Variables --*/
:root{
--body-font:'$(main.font.family)', Arial, sans-serif;
--menu-font:'$(menu.font.family)', Arial, sans-serif;
--title-font:'$(title.font.family)', Arial, sans-serif;
--meta-font:'$(main.font.family)', Arial, sans-serif;
--text-font:'$(text.font.family)', Arial, sans-serif;
--body-bg-color:$(background.color);
--body-bg:$(body.background);
--outer-bg:$(outer.bg);
--main-color:$(main.color);
--title-color:$(title.color);
--title-hover-color:$(title.hover.color);
--meta-color:$(meta.color);
--text-color:$(text.color);
--tag-bg:$(main.color)aa;
--topbar-bg:$(topbar.bg);
--topbar-color:$(topbar.color);
--topbar-hover-color:$(topbar.hover.color);
--header-bg:$(header.bg);
--header-color:$(header.color);
--header-hover-color:$(header.hover.color);
--submenu-bg:$(submenu.bg);
--submenu-color:$(submenu.color);
--submenu-hover-color:$(submenu.hover.color);
--megamenu-bg:$(megamenu.bg);
--megamenu-color:$(megamenu.color);
--megamenu-hover-color:$(megamenu.hover.color);
--mobilemenu-bg:$(mmenu.bg);
--mobilemenu-color:$(mmenu.color);
--mobilemenu-hover-color:$(mmenu.hover.color);
--widget-bg:$(widget.bg);
--widget-title-color:$(wtitle.color);
--feat-title-bg:$(feat.title.bg);
--feat-title-color:$(feat.title.color);
--feat-more-bg:$(feat.more.bg);
--feat-more-color:$(feat.more.color);
--post-title-color:$(post.title.color);
--post-title-hover-color:$(post.title.hover.color);
--post-text-color:$(post.text.color);
--footer-bg:$(footer.bg);
--footer-color:$(footer.color);
--footer-hover-color:$(footer.hover.color);
--footer-text-color:$(footer.text.color);
--footerbar-bg:$(footerbar.bg);
--footerbar-color:$(footerbar.color);
--footerbar-hover-color:$(footerbar.hover.color);
--button-bg:$(button.bg);
--button-lite-bg:$(button.bg)10;
--button-color:$(button.color);
--button-hover-bg:$(button.hover.bg);
--button-hover-color:$(button.hover.color);
--border-color:rgba(155,155,155,0.1);
--border-radius:3px;
--widget-shadow:0 1px 2px rgba(0,0,0,0.025);
--avatar-shadow:0px 1px 4px rgba(0,0,0,0.05);
}
html.is-dark{
--body-bg-color:#2b2b2b;
--body-bg:$(body.background);
--outer-bg:#181818;
--title-color:#f6f7f8;
--title-hover-color:$(main.color);
--meta-color:#aaaaaa;
--text-color:#b4b6ba;
--topbar-bg:#181818;
--topbar-color:#c2c2c3;
--topbar-hover-color:$(main.color);
--header-bg:#202020;
--header-color:#f6f7f8;
--header-hover-color:$(main.color);
--submenu-bg:#242424;
--submenu-color:#f6f7f8;
--submenu-hover-color:$(main.color);
--megamenu-bg:#242424;
--megamenu-color:#f6f7f8;
--megamenu-hover-color:$(main.color);
--mobilemenu-bg:#181818;
--mobilemenu-color:#f6f7f8;
--mobilemenu-hover-color:$(main.color);
--widget-bg:#202020;
--widget-title-color:#f6f7f8;
--feat-title-bg:#202020;
--post-title-color:#f6f7f8;
--feat-more-bg:#393939;
--feat-more-color:#f6f7f8;
--post-title-hover-color:$(main.color);
--post-text-color:b4b6ba;
--footer-bg:#202020;
--footer-color:#f6f7f8;
--footer-hover-color:$(main.color);
--footer-text-color:#b4b6ba;
--footerbar-bg:#181818;
--footerbar-color:#f6f7f8;
--footerbar-hover-color:$(main.color);
--button-bg:$(main.color);
--button-color:#ffffff;
--button-hover-bg:$(button.hover.bg);
--button-hover-color:$(button.hover.color);
--border-color:rgba(155,155,155,0.05);
}
html.rtl{
--body-font:'Tajawal',Arial,sans-serif;
--title-font:'Tajawal',Arial,sans-serif;
--meta-font:'Tajawal',Arial,sans-serif;
--text-font:'Tajawal',Arial,sans-serif;
}

/*-- Reset CSS --*/


a, abbr, acronym, address, applet, b, big, blockquote, body, caption, center, cite, code, dd, del, dfn, div, dl, dt, em, fieldset, font, form, h1, h2, h3, h4, h5, h6, html, i, iframe, img, ins, kbd, label, legend, li, object, p, pre, q, s, samp, small, span, strike, strong, sub, sup, table, tbody, td, tfoot, th, thead, tr, tt, u, ul, var{
    padding:0;
    margin:0;
    border:0;
    outline:none;
    vertical-align:baseline;
    background:0 0;
    text-decoration:none
}
dl, ul{
    list-style-position:inside;
    list-style:none
}
ul li{
    list-style:none
}
caption{
    text-align:center
}
img{
    border:none;
    position:relative
}
a, a:visited{
    text-decoration:none
}
.clearfix{
    clear:both
}
.section, .widget, .widget ul{
    margin:0;
    padding:0
}
a{
    color:var(--main-color)
}
a img{
    border:0
}
abbr{
    text-decoration:none
}
.CSS_LIGHTBOX{
    z-index:999999!important
}
.CSS_LIGHTBOX_ATTRIBUTION_INDEX_CONTAINER .CSS_HCONT_CHILDREN_HOLDER > .CSS_LAYOUT_COMPONENT.CSS_HCONT_CHILD:first-child > .CSS_LAYOUT_COMPONENT{
    opacity:0
}
.separator a{
    text-decoration:none!important;
    clear:none!important;
    float:none!important;
    margin-left:0!important;
    margin-right:0!important
}
#Navbar1, #navbar-iframe, .widget-item-control, a.quickedit, .home-link, .feed-links{
    display:none!important
}
.center{
    display:table;
    margin:0 auto;
    position:relative
}
.widget > h2, .widget > h3{
    display:none
}
.widget iframe, .widget img{
    max-width:100%
}
button, input, select, textarea{
    font-family:var(--body-font);
    -webkit-appearance:none;
    -moz-appearance:none;
    appearance:none;
    outline:none;
    border-radius:0
}
/*-- Style CSS --*/
 *{
    box-sizing:border-box
}
 html{
    position:relative;
    word-break:break-word;
    word-wrap:break-word;
    text-rendering:optimizeLegibility;
    -webkit-font-smoothing:antialiased;
    -webkit-text-size-adjust:100%
}
 body{
    position:relative;
    background:var(--body-bg);
    background-color:var(--body-bg-color);
    font-family:var(--body-font);
    font-size:14px;
    color:var(--text-color);
    font-weight:400;
    font-style:normal;
    line-height:1.4em
}
 .rtl{
    direction:rtl
}
 h1, h2, h3, h4, h5, h6{
    font-family:var(--title-font);
    font-weight:700
}
 a, input, button{
    transition:all .0s ease
}
 #outer-wrapper{
    position:relative;
    overflow:hidden;
    width:100%;
    max-width:100%;
    background-color:var(--outer-bg);
    margin:0 auto;
    padding:0
}
 .is-boxed #outer-wrapper{
    width:$(row.width + 50px);
    max-width:100%;
    box-shadow:0 0 20px rgba(0,0,0,0.1)
}
 .is-dark .is-boxed #outer-wrapper{
    box-shadow:0 0 20px rgba(0,0,0,0.3)
}
 .container{
    position:relative
}
 .row-x1{
    width:$(row.width)
}
 .row-x2{
    width:100%
}
 .flex-center{
    display:flex;
    justify-content:center
}
 #content-wrapper{
    position:relative;
    float:left;
    width:100%;
    overflow:hidden;
    padding:25px 0;
    margin:0
}
 #content-wrapper > .container{
    display:flex;
    justify-content:space-between
}
 .is-left #content-wrapper > .container, .rtl .is-right #content-wrapper > .container{
    flex-direction:row-reverse
}
 .rtl .is-left #content-wrapper > .container{
    flex-direction:row
}
 .theiaStickySidebar:before, .theiaStickySidebar:after{
    content:'';
    display:table;
    clear:both
}
 #main-wrapper{
    position:relative;
    flex:1 1 auto;
    width:auto;
    min-width:0
}
 .no-sidebar #main-wrapper{
    width:100%
}
 #sidebar-wrapper{
    position:relative;
    flex:0 0 300px;
    width:300px;
    min-width:0;
    box-sizing:border-box
}
 .no-sidebar #sidebar-wrapper{
    display:none
}
 .btn{
    position:relative;
    border:0;
    border-radius:var(--border-radius)
}
 .entry-image-wrap, .author-avatar-wrap, .comments .avatar-image-container{
    display:block;
    position:relative;
    overflow:hidden;
    background-color:rgba(155,155,155,0.05);
    z-index:5;
    color:transparent!important
}
 .entry-thumb, .author-avatar{
    display:block;
    position:relative;
    width:100%;
    height:100%;
    background-size:cover;
    background-position:center center;
    background-repeat:no-repeat;
    z-index:1;
    opacity:0;
    transition:opacity .35s ease,filter 0s ease
}
 .author-avatar{
    background-size:100%;
    background-position:0 0
}
 .entry-thumb.lazy-ify, .author-avatar.lazy-ify{
    opacity:1
}
 .entry-image-wrap:hover .entry-thumb, .card-style:hover .entry-image-wrap .entry-thumb{
    filter:brightness(1.03)
}
 .entry-image-wrap.is-video:after{
    position:absolute;
    content:'\f04b';
    top:50%;
    right:50%;
    background-color:rgba(0,0,0,0.5);
    width:34px;
    height:34px;
    font-family:'Font Awesome 5 Free';
    font-size:11px;
    color:#fff;
    font-weight:900;
    display:flex;
    align-items:center;
    justify-content:center;
    z-index:5;
    transform:translate(50%,-50%);
    box-sizing:border-box;
    padding:0 0 0 1px;
    margin:0;
    border:2px solid #fff;
    border-radius:50%;
    opacity:.9;
    transition:opacity .17s ease
}
 .entry-image-wrap.is-video:hover:after, .card-style:hover .entry-image-wrap.is-video:after{
    opacity:1
}
 .card-style .entry-image-wrap.is-video:after{
    top:15px;
    right:15px;
    transform:translate(0)
}
 .rtl .card-style .entry-image-wrap.is-video:after{
    left:15px;
    right:unset
}
 .entry-category{
    display:block;
    font-size:13px;
    color:var(--main-color);
    font-weight:500;
    text-transform:uppercase;
    margin:0 0 5px
}
 .entry-title{
    display:block;
    color:var(--post-title-color);
    font-weight:700;
    line-height:1.3em
}
 .entry-title a{
    display:block;
    color:var(--post-title-color)
}
 .entry-title a:hover{
    color:var(--post-title-hover-color)
}
 .entry-meta{
    display:flex;
    font-family:var(--meta-font);
    font-size:12px;
    color:var(--meta-color);
    font-weight:400;
    margin:4px 0 0
}
 .entry-meta .mi{
    display:flex
}
 .entry-meta .mi, .entry-meta .sp{
    margin:0 4px 0 0
}
 .rtl .entry-meta .mi, .rtl .entry-meta .sp{
    margin:0 0 0 4px
}
 .entry-meta .author-name{
    color:var(--main-color);
    font-weight:500
}
 .excerpt{
    font-family:var(--text-font);
    line-height:1.5em
}
.entry-excerpt{
    display: block;
    font-size: 14px;
    color: #b5b5ba;
    margin: 5px 0 0;
}
 .before-mask:before{
    content:'';
    position:absolute;
    left:0;
    right:0;
    bottom:0;
    height:70%;
    background-image:linear-gradient(to bottom,rgba(0,0,0,0),rgba(0,0,0,0.7));
    -webkit-backface-visibility:hidden;
    backface-visibility:hidden;
    z-index:2;
    opacity:1;
    margin:0;
    transition:opacity .25s ease
}
 .card-style{
    overflow:hidden
}
 .entry-info{
    position:absolute;
    left:0;
    bottom:0;
    width:100%;
    background:linear-gradient(to bottom,rgba(0,0,0,0) 10%,rgba(0,0,0,0.5));
    overflow:hidden;
    z-index:10;
    display:flex;
    flex-direction:column;
    padding:15px
}
 .entry-info .entry-category{
    display:flex;
    width:-moz-fit-content;
    width:fit-content;
    height:18px;
    background-color:var(--tag-bg);
    font-size:11px;
    color:#fff;
    font-weight:400;
    align-items:center;
    padding:0 5px;
    margin:0 0 10px;
    border-radius:2px
}
 .entry-info .entry-title a{
    color:#fff;
    text-shadow:0 1px 2px rgba(0,0,0,0.1)
}
 .entry-info .entry-meta{
    color:#c5c5c5;
    text-shadow:0 1px 2px rgba(0,0,0,0.1)
}
 .entry-info .entry-meta .author-name{
    color:#e5e5e5
}
 .error-msg{
    display:flex;
    align-items:center;
    font-size:14px;
    color:var(--meta-color);
    padding:20px 0;
    font-weight:400
}
 .error-msg b{
    font-weight:600
}
 .loader{
    position:relative;
    width:100%;
    height:100%;
    overflow:hidden;
    display:flex;
    align-items:center;
    justify-content:center;
    margin:0
}
 .loader:after{
    content:'';
    display:block;
    width:30px;
    height:30px;
    box-sizing:border-box;
    margin:0;
    border:2px solid var(--border-color);
    border-left-color:var(--main-color);
    border-radius:100%;
    animation:spinner .65s infinite linear;
    transform-origin:center
}
 @-webkit-keyframes spinner {
     0%{
        -webkit-transform:rotate(0deg);
        transform:rotate(0deg)
    }
     to{
        -webkit-transform:rotate(1turn);
        transform:rotate(1turn)
    }
}
 @keyframes spinner {
     0%{
        -webkit-transform:rotate(0deg);
        transform:rotate(0deg)
    }
     to{
        -webkit-transform:rotate(1turn);
        transform:rotate(1turn)
    }
}
