 #header-wrapper{
    position:relative;
    float:left;
    width:100%;
    z-index:50;
    margin:0
}
 .topbar-wrap{
    position:relative;
    float:left;
    width:100%;
    height:175px;
    align-items: center;
    background-color:var(--topbar-bg);
    background-image: url(https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEibPxoLayjUc1fz4srbhiEK7pHdxEDu7kC9tdXPbUZ99FA8eW-mUJ6dhi9vfNTRuu2BY2HKENP5ghLKuR0SX7DBTQ5uaWPJs8qKff1GSUI1kzqQ-MWnNMPNuL5EMVCGjEUlyGNAiH1WasgwBlp9QvcCpzBhK4bHVTDZiKAQDgrmbwE0g2rk8TW5Wjwq92I/s16000/ElecEyeNewLog.1.jpeg);
    background-position: center left;
    background-size: cover;
    z-index:1;
    padding:0;
    margin:0
}
 .topbar-wrap:before{
content: '';
    position: absolute;
    left: 0;
    right: 0;
    bottom: 0;
    height: 100%;
   background: radial-gradient(circle, rgba(0,0,0,0) 0%, rgb(0 0 0 / 54%) 10%, rgb(24 24 24 / 86%) 100%);
    -webkit-backface-visibility: hidden;
    backface-visibility: hidden;
    z-index: 2;
    opacity: 1;
    margin: 0;
}
 :not(.is-dark) .topbar-wrap.has-border{
    border-bottom:1px solid var(--border-color)
}
 .topbar-items{
    position:relative;
    float:left;
    width:100%;
    display:flex;
    flex-wrap:wrap;
    justify-content:center;
    margin:0
}
.topbar-items .flex-left, .rtl .topbar-items .flex-right{
    position: absolute;
    top: 50%;
    transform: translateY(-50%);
    -webkit-transform: translateY(-50%);
    -moz-transform: translateY(-50%);
    left: 0;
    z-index: 10;
}
.topbar-items .flex-right{
    z-index: 10;
}
.topbar-items .flex-center{
    justify-content: center;
    position:relative;
    z-index: 10;
}
.topbar-items .flex-right, .rtl .topbar-items .flex-left{
    position: absolute;
    top: 50%;
    transform: translateY(-50%);
    -webkit-transform: translateY(-50%);
    -moz-transform: translateY(-50%);
    right: 0;
    background: transparent;
}
 .topbar-items .section{
    position:relative;
    height:28px;
    margin:0
}
 .topbar-items .topbar-ul{
    display:flex;
    flex-wrap:wrap
}
 .topbar-items .topbar-ul li{
    display:inline-block;
    margin:0 20px 0 0
}
 .rtl .topbar-items .topbar-ul li{
    margin:0 0 0 20px
}
 .topbar-items .topbar-ul li a{
    display:block;
    font-size:12px;
    color:var(--topbar-color);
    line-height:28px
}
 .topbar-items .topbar-ul li a:hover{
    color:var(--topbar-hover-color)
}
 .topbar-items .topbar-social .topbar-ul li{
    margin:0 0 0 16px
}
 .rtl .topbar-items .topbar-social .topbar-ul li{
    margin:0 16px 0 0
}
 .topbar-items .topbar-social .topbar-ul li a{
    font-size:13px
}
 .main-header, .header-inner{
    position:relative;
    float:left;
    width:100%;
    height:52px;
    background-color:var(--header-bg);
    margin:0
}
 .header-inner{
    background-color:rgba(0,0,0,0)
}
 .header-header{
    position:relative;
    float:left;
    width:100%;
    height:52px;
    background-color:var(--header-bg);
    margin:0;
}
 .is-boxed .header-header{
    float:none;
    width:$(row.width + 50px);
    max-width:100%;
    margin:0 auto;
    padding:0
}
 .header-items{
    position:relative;
    float:left;
    width:100%;
    display:flex;
    flex-wrap:wrap;
    justify-content:space-between;
    margin:0
}
 .flex-left{
    position:static;
    display:flex;
    margin:0
}
 .flex-right{
    position:absolute;
    top:0;
    right:0;
    background-color:var(--header-bg);
    margin:0
}
 .rtl .flex-right{
    left:0;
    right:unset;
    margin:0
}
 .topbar-items .main-logo{
    position:relative;
    float:left;
    height:125px;
    overflow:hidden;
    padding:0;
    margin:0
}
 .rtl .main-logo{
    padding:0 0 0 14px
}
 .main-logo .widget{
    position:relative;
    height:100%;
    display:flex;
    align-items:center;
    margin:0
}
 .main-logo .logo-img{
    display:flex;
    align-items:center;
    height:115px;
    overflow:hidden;
    margin:0
}
 .main-logo img{
    display:block;
    max-width:100%;
    max-height:100%;
    margin:0
}
.is-dark #cryzen-mobile-logo-section img{
    -webkit-filter: invert(1);
    filter: invert(1);
}
 .main-logo .blog-title{
    display:block;
    font-size:23px;
    color:var(--topbar-color);
    font-weight:700;
    margin:0
}
 .main-logo .blog-title a{
    color:var(--topbar-color)
}
 .main-logo .blog-title a:hover{
    color:var(--topbar-hover-color)
}
 .main-logo #h1-off{
    position:absolute;
    top:-9000px;
    left:-9000px;
    display:none;
    visibility:hidden
}
#cryzen-mobile-logo-section{
display:none;
}
 #cryzen-pro-main-nav{
    position:static;
    height:52px;
    z-index:10
}
 #cryzen-pro-main-nav .widget, #cryzen-pro-main-nav .widget > .widget-title{
    display:none
}
 #cryzen-pro-main-nav .show-menu{
    display:flex
}
#cryzen-pro-main-nav ul#cryzen-pro-main-nav-menu{
    display:flex !important;
    flex-wrap:wrap;
    justify-content:center !important;
    align-items:center;
}

 #cryzen-pro-main-nav ul > li{
    position:relative;
    padding:0;
    margin:0
}
 #cryzen-pro-main-nav-menu > li > a{
    position:relative;
    display:block;
    height:52px;
    font-family:var(--menu-font);
    font-size:14px;
    color:var(--header-color);
    font-weight:700;
    text-transform:uppercase;
    line-height:52px;
    padding:0 14px;
    margin:0
}
#cryzen-pro-main-nav-menu > li:first-child > a{
    padding:0 14px;
}
 #cryzen-pro-main-nav-menu > li:hover > a{
    color:var(--header-hover-color)
}
 #cryzen-pro-main-nav ul > li > ul, #cryzen-pro-main-nav ul > li > .ul{
    position:absolute;
    left:0;
    top:52px;
    width:180px;
    background-color:var(--submenu-bg);
    z-index:99999;
    padding:5px 0;
    backface-visibility:hidden;
    visibility:hidden;
    opacity:0;
    box-shadow:0 1px 2px rgba(0,0,0,0.1),0 5px 10px 0 rgba(0,0,0,0.1)
}
 .rtl #cryzen-pro-main-nav ul > li > ul, .rtl #cryzen-pro-main-nav ul > li > .ul{
    left:auto;
    right:0
}
 #cryzen-pro-main-nav ul > li > ul > li > ul{
    position:absolute;
    top:-5px;
    left:100%;
    margin:0
}
 .rtl #cryzen-pro-main-nav ul > li > ul > li > ul{
    left:unset;
    right:100%
}
 #cryzen-pro-main-nav ul > li > ul > li{
    display:block;
    float:none;
    position:relative
}
 .rtl #cryzen-pro-main-nav ul > li > ul > li{
    float:none
}
 #cryzen-pro-main-nav ul > li > ul > li a{
    position:relative;
    display:block;
    font-size:14px;
    color:var(--submenu-color);
    font-weight:400;
