    line-height:16px;
    display:block
}
 .Attribution a > svg{
    width:16px;
    height:16px;
    float:left;
    margin:0 4px 0 0
}
 .Attribution .copyright{
    font-size:12px;
    color:var(--meta-color);
    padding:0 20px;
    margin:3px 0 0
}
 .Stats .text-counter-wrapper{
    display:flex;
    font-size:20px;
    color:var(--meta-color);
