    font-weight:900;
    margin:0 4px 0 0
}
 .rtl .ReportAbuse > h3:before{
    margin:0 0 0 4px
}
 .ReportAbuse > h3 a:hover{
    text-decoration:underline
}
 #footer-ads-wrap{
    position:relative;
    float:left;
    width:100%;
    margin:0
}
 .footer-ads .widget{
    position:relative;
    float:left;
    width:100%;
