    color:var(--footerbar-hover-color)
}
 #footer-menu{
    position:relative;
    display:block;
    margin:0
}
 .footer-menu ul{
    display:flex;
    flex-wrap:wrap
}
 .footer-menu ul li a{
    font-size:14px;
    color:var(--footerbar-color);
    padding:0;
    margin:0 0 0 25px
}
 .rtl .footer-menu ul li a{
    margin:0 25px 0 0
}
 #footer-menu ul li a:hover{
    color:var(--footerbar-hover-color)
}
 #hidden-widgets-wrap, .hidden-widgets{
    display:none;
    visibility:hidden
}
 #back-top{
    display:none;
    position:fixed;
    bottom:20px;
    right:20px;
    width:34px;
    height:34px;
    background-color:var(--button-bg);
    cursor:pointer;
    overflow:hidden;
    font-size:15px;
    color:var(--button-color);
    text-align:center;
    line-height:34px;
    z-index:50;
    margin:0;
    transition:background .17s ease,color .17s ease
}
 .rtl #back-top{
    right:auto;
    left:20px
}
 #back-top:before{
    content:'\f077';
    position:relative;
    font-family:'Font Awesome 5 Free';
    font-weight:900
}
 #back-top:hover{
    background-color:var(--button-hover-bg);
    color:var(--button-hover-color)
}
 .is-error #main-wrapper{
    width:100%
}
 .is-error #sidebar-wrapper{
