.entry-title{
  text-align: center;
}

.popular-articles{
    display: flex;
    flex-direction: column;
    gap: 15px;
}

.popular-articles .article-list{
    list-style: none;
    margin: 0;
    padding: 0;
}

.popular-articles .article-item{
    display: flex;
    gap: 10px;
    border-bottom: 1px solid #ddd;
    padding-bottom: 10px;
}

.popular-articles .article-link{
    display: flex;
    text-decoration: none;
    color: inherit;
}

.popular-articles .article-image{
    width: 100px;
    height: 100px;
    object-fit: cover;
    border-radius: 5px;
}

.popular-articles .article-content{
    flex: 1;
}

.popular-articles .article-title{
    font-size: 1.2rem;
    margin: 0 0 5px;
    font-weight: bold;
}

.popular-articles .article-summary{
    font-size: 0.9rem;
    color: #555;
    margin: 0;
}img{
  transition: transform 0.3s ease;
}

img:hover{
  transform: scale(1.05); /* 5% expansion on hover */
}

.image-row{
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 20px;
}

.image-container{
  text-align: center;
  width: 320px;
}

/* Target the Header Logo image specifically */
#main-logo .logo-img img{
  transition: transform 0.3s ease;
}

#main-logo .logo-img img:hover{
  transform: scale(1.12); /* 10% expansion on hover */
}.link-container{
  position: relative;
}

.link-container img{
  display: none;
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 1;
}

.link-container:hover img{
  display: block;
}

.blog-post h3.title{
    display: none;
}

img{
  margin: 0.1em;
}

/* ========================================================================== 
   ELECTRIC EYE — TEST BUILD V1
   Architecture and visual-system override layer
   ========================================================================== */

:root{
  --ee-bg: #edf1f5;
  --ee-surface: #ffffff;
  --ee-dark: #101010;
  --ee-dark-soft: #171717;
  --ee-text: #171717;
  --ee-text-soft: #454b53;
  --ee-muted: #6f7782;
  --ee-border: #d5dbe2;
  --ee-accent: #d82323;
  --ee-accent-hover: #b51d1d;
  --ee-on-dark: #faf8f4;
  --ee-on-dark-muted: #c7c1b9;
  --ee-wide: 1500px;
  --ee-standard: 1420px;
  --ee-reading: 900px;
  --ee-sidebar: 250px;
  --ee-radius: 0px;
  --body-font: "Instrument Sans", Arial, sans-serif;
  --menu-font: "Instrument Sans", Arial, sans-serif;
  --title-font: "Instrument Sans", Arial, sans-serif;
  --meta-font: "Instrument Sans", Arial, sans-serif;
  --text-font: "Instrument Sans", Arial, sans-serif;
  --body-bg-color: var(--ee-bg);
  --outer-bg: var(--ee-bg);
  --main-color: var(--ee-accent);
  --title-color: var(--ee-text);
  --title-hover-color: var(--ee-accent-hover);
  --meta-color: var(--ee-muted);
  --text-color: var(--ee-text-soft);
  --header-bg: var(--ee-dark);
  --header-color: var(--ee-on-dark);
  --header-hover-color: var(--ee-accent);
  --post-title-color: var(--ee-text);
  --post-title-hover-color: var(--ee-accent-hover);
  --post-text-color: #282d33;
  --footer-bg: var(--ee-dark);
  --footer-color: var(--ee-on-dark);
  --footer-text-color: var(--ee-on-dark-muted);
  --footer-hover-color: var(--ee-accent);
  --border-color: var(--ee-border);
  --border-radius: var(--ee-radius);
  --widget-shadow: none;
}

html,
body{
  background: var(--ee-bg);
}

body{
  color: var(--ee-text-soft);
  font-family: var(--body-font);
  font-size: 16px;
  line-height: 1.6;
}

h1,
h2,
h3,
h4,
h5,
h6,
.entry-title,
.post-title{
  color: var(--ee-text);
  font-family: var(--title-font);
  font-weight: 700;
  letter-spacing: -0.025em;
}

a{ color: var(--ee-accent); }
a:hover{ color: var(--ee-accent-hover); }

#outer-wrapper,
.is-boxed #outer-wrapper{
  width: 100%;
  max-width: none;
  background: var(--ee-bg);
  box-shadow: none;
}

.row-x1{
  width: min(calc(100% - 48px), var(--ee-wide));
}

/* --- Header: brand row + compact sticky navigation --- */
#header-wrapper{
  position: relative;
  z-index: 100;
  background: var(--ee-dark);
  color: var(--ee-on-dark);
}

.topbar-wrap{
  display: flex;
  min-height: 128px;
  background: var(--ee-dark);
  border: 0;
}

.topbar-items{
  min-height: 128px;
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
}

.topbar-menu,
.topbar-social{
  visibility: hidden;
  pointer-events: none;
}

.main-logo .logo-img,
.main-logo .logo-img img{
  display: block;
}

.topbar-wrap .main-logo img{
  width: auto;
  max-width: min(480px, 65vw);
  max-height: 92px;
  object-fit: contain;
}

.main-header{
  position: sticky;
  top: 0;
  z-index: 110;
  background: var(--ee-dark);
  border-top: 1px solid rgba(255,255,255,.12);
  border-bottom: 1px solid rgba(255,255,255,.12);
  box-shadow: none;
}

.header-header,
.header-inner,
.header-items{
  min-height: 58px;
}

.header-items{
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.cryzen-mobile-logo-section{
  display: none;
}

#cryzen-pro-main-nav,
#cryzen-pro-main-nav .widget,
#cryzen-pro-main-nav .widget-content{
  width: 100%;
}

#cryzen-pro-main-nav ul#cryzen-pro-main-nav-menu{
  display: flex;
  align-items: center;
  gap: clamp(18px, 2.1vw, 34px);
}

#cryzen-pro-main-nav > .widget > .widget-content > ul > li > a,
#cryzen-pro-main-nav .main-nav > li > a{
  min-height: 58px;
  display: flex;
  align-items: center;
  color: var(--ee-on-dark);
  font-family: var(--menu-font);
  font-size: 14px;
  font-weight: 600;
  letter-spacing: .035em;
  text-transform: none;
}

#cryzen-pro-main-nav a:hover,
#cryzen-pro-main-nav li:hover > a{
  color: var(--ee-accent);
}

#cryzen-pro-main-nav ul ul{
  min-width: 230px;
  padding: 10px 0;
  background: var(--ee-surface);
  border: 1px solid var(--ee-border);
  box-shadow: 0 14px 38px rgba(0,0,0,.16);
}

#cryzen-pro-main-nav ul ul a{
  color: var(--ee-text);
  font-size: clamp(13px, 1.05vw, 14px);
  font-weight: 500;
  line-height: 1.35;
  padding: 11px 18px;
}

/* Keep every navigation entry intact and make each dropdown row one unified block. */
#cryzen-pro-main-nav,
#cryzen-pro-main-nav ul,
#cryzen-pro-main-nav li,
#cryzen-pro-main-nav a,
.cryzen-pro-mobile-menu,
.cryzen-pro-mobile-menu ul,
.cryzen-pro-mobile-menu li,
.cryzen-pro-mobile-menu a{
  word-break: normal;
  overflow-wrap: normal;
  hyphens: none;
}

#cryzen-pro-main-nav > .widget > .widget-content > ul > li > a,
#cryzen-pro-main-nav .main-nav > li > a{
  white-space: nowrap;
}

#cryzen-pro-main-nav ul ul,
#cryzen-pro-main-nav ul ul li{
  width: 100%;
}

#cryzen-pro-main-nav ul ul{
  width: clamp(230px, 22vw, 320px);
}

#cryzen-pro-main-nav ul ul li{
  display: block;
  float: none;
  margin: 0;
  padding: 0;
}

#cryzen-pro-main-nav ul ul li + li{
  border-top: 1px solid var(--ee-border);
}

#cryzen-pro-main-nav ul ul a{
  display: flex;
  width: 100%;
  min-height: 44px;
  align-items: center;
  justify-content: space-between;
  white-space: normal;
}

.cryzen-pro-mobile-menu ul li,
.cryzen-pro-mobile-menu ul li a{
  width: 100%;
}

.cryzen-pro-mobile-menu ul li a{
  display: flex;
  min-height: 48px;
  align-items: center;
  white-space: normal;
  line-height: 1.35;
}

.main-toggle-wrap{
  margin-left: 24px;
}

.main-toggle-style{
  color: var(--ee-on-dark);
}

#main-search-wrap{
  background: var(--ee-dark);
}

.search-input{
  color: var(--ee-on-dark);
  font-family: var(--body-font);
  font-size: 18px;
}

/* Retire commercial-theme homepage/header machinery. */
#featured-wrap,
#header-ads-wrap,
#content-section-1,
#content-section-2,
#main-ads,
#main-ads-2{
  display: none !important;
}

/* --- Global content architecture --- */
#content-wrapper{
  float: none;
  overflow: visible;
  padding: 48px 0 72px;
}

#content-wrapper > .container{
  display: grid;
  grid-template-columns: minmax(0, 1fr) var(--ee-sidebar);
  gap: 30px;
  align-items: start;
  width: min(calc(100% - 48px), var(--ee-standard));
}

#main-wrapper{
  width: 100%;
  min-width: 0;
}

#sidebar-wrapper{
  width: 100%;
  min-width: 0;
}

/* Sidebar is the default outside the designated full-width pages. */
.ee-full-width-page #content-wrapper > .container{
  grid-template-columns: minmax(0, 1fr);
  width: min(calc(100% - 48px), var(--ee-wide));
}

.ee-full-width-page #sidebar-wrapper{
  display: none !important;
}

/* Only the Welcome page receives an unboxed, full-width canvas. */
.ee-full-width-page #content-wrapper{
  padding-top: 0;
}

.ee-full-width-page #content-wrapper > .container,
.ee-full-width-page #main-wrapper,
.ee-full-width-page .item-post-wrap,
.ee-full-width-page .item-post,
.ee-full-width-page .post-body{
  width: 100%;
  max-width: none;
}

.ee-full-width-page .item-post{
  padding: 0;
  background: transparent;
  border: 0;
  box-shadow: none;
}

/* Ordinary static pages retain the editorial sidebar. */
.is-page:not(.ee-full-width-page) .item-post{
  background: transparent;
  border: 0;
  box-shadow: none;
  padding: 0;
}

/* Concert Reviews page: retain the normal light-theme page title. */
.ee-concert-reviews-page .item-post .post-title,
.ee-concert-reviews-page .item-post .post-title a,
.ee-concert-reviews-page .item-post .entry-title,
.ee-concert-reviews-page .item-post .entry-title a,
.ee-concert-reviews-page .item-post h1{
  color: #171717 !important;
  opacity: 1 !important;
}

/* The Concert Reviews static page declares its own archive colour variables
   at :root, including a light --ee-text. Those variables leak into the site
   header on this page, so pin submenu text to the intended light-menu colors. */
.ee-concert-reviews-page #cryzen-pro-main-nav ul > li > ul > li > a,
.ee-concert-reviews-page #cryzen-pro-main-nav ul > li > .ul > li > a,
.ee-concert-reviews-page #cryzen-pro-main-nav ul ul a{
  color: #15161a !important;
  -webkit-text-fill-color: #15161a !important;
}

.ee-concert-reviews-page #cryzen-pro-main-nav ul > li > ul > li:hover > a,
.ee-concert-reviews-page #cryzen-pro-main-nav ul > li > ul > li:focus-within > a,
.ee-concert-reviews-page #cryzen-pro-main-nav ul > li > .ul > li:hover > a,
.ee-concert-reviews-page #cryzen-pro-main-nav ul > li > .ul > li:focus-within > a,
.ee-concert-reviews-page #cryzen-pro-main-nav ul ul a:hover,
.ee-concert-reviews-page #cryzen-pro-main-nav ul ul a:focus-visible{
  color: #fff !important;
  -webkit-text-fill-color: #fff !important;
}

/* Concert Reviews archive media must fill its designed frames. The base
   Blogger rule `.post-body img { height:auto!important; }` is correct for
   ordinary article photographs but must not override these UI images. */
#ee-archive-app .ee-a-hero-image,
#ee-archive-app .ee-a-feature img,
#ee-archive-app .ee-a-card-media img,
#ee-archive-app .ee-a-card img{
  display: block !important;
  width: 100% !important;
  height: 100% !important;
  max-width: none !important;
  object-fit: cover !important;
}

/* --- Article page --- */
.is-post #main-wrapper{
  max-width: 100%;
}

.is-post .item-post{
  background: transparent;
  border: 0;
  box-shadow: none;
  padding: 0;
}

.is-post .post-header,
.is-post .entry-header,
.is-post .post-body,
.is-post .post-footer,
.is-post .post-labels,
.is-post .post-share,
.is-post .comments,
.is-post #comments{
  width: 100%;
  max-width: var(--ee-reading);
  margin-left: auto;
  margin-right: auto;
}

.is-post .entry-title,
.is-post .post-title,
.is-post h1.post-title{
  font-size: clamp(38px, 4.2vw, 58px);
  line-height: 1.04;
  letter-spacing: -0.04em;
  margin: 0 0 16px;
}

.is-post .entry-meta,
.is-post .post-meta{
  color: var(--ee-muted);
  font-size: 13px;
  font-weight: 500;
  letter-spacing: .02em;
  line-height: 1.45;
}

.is-post .post-body{
  color: #282d33;
  font-family: var(--text-font);
  font-size: 18px;
  line-height: 1.72;
}

.is-post .post-body p{
  margin: 0 0 1.45em;
}

.is-post .post-body h2{
  font-size: clamp(28px, 3.2vw, 40px);
  line-height: 1.1;
  margin: 1.8em 0 .65em;
}

.is-post .post-body h3{
  font-size: clamp(23px, 2.5vw, 31px);
  line-height: 1.15;
  margin: 1.65em 0 .6em;
}

.is-post .post-body a{
  color: inherit;
  text-decoration: underline;
  text-decoration-color: var(--ee-accent);
  text-decoration-thickness: 1.5px;
  text-underline-offset: .16em;
}

.is-post .post-body a:hover{
  color: var(--ee-accent-hover);
}

.is-post .post-body blockquote{
  margin: 2em 0;
  padding: .2em 0 .2em 1.25em;
  border-left: 4px solid var(--ee-accent);
  color: var(--ee-text);
  font-size: 1.12em;
  line-height: 1.55;
}

/* Responsive article media */
.is-post .post-body img,
.is-post .post-body video{
  max-width:100%;
  height:auto;
}

/* Do not override the native height of embedded services */
.is-post .post-body iframe{
  max-width:100%;
}

/* YouTube / Blogger video embeds: responsive 16:9 */
.is-post .post-body iframe.BLOG_video_class,
.is-post .post-body iframe[src*="youtube.com/embed"],
.is-post .post-body iframe[src*="youtube-nocookie.com/embed"]{
  display:block;
  width:100% !important;
  max-width:100% !important;
  aspect-ratio:16 / 9;
  height:auto !important;
  margin-left:auto;
  margin-right:auto;
}

/* Facebook posts and videos: retain Facebook's required height */
.is-post .post-body iframe[src*="facebook.com/plugins/"]{
  display:block;
  max-width:100% !important;
  margin-left:auto;
  margin-right:auto;
}

.is-post .post-body .separator,
.is-post .post-body figure,
.is-post .post-body table,
.is-post .post-body iframe{
  margin-top: 1.8em;
  margin-bottom: 1.8em;
}

.is-post .post-body figcaption,
.is-post .post-body .tr-caption,
.is-post .post-body .image-caption{
  color: var(--ee-muted);
  font-size: 13px;
  line-height: 1.45;
  margin-top: 8px;
}

/* --- Listing / label / search / archive pages --- */
.is-multiple .blog-posts,
.is-multiple .index-post-wrap{
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 52px 34px;
}

.is-multiple .index-post{
  width: 100%;
  margin: 0;
  padding: 0;
  background: transparent;
  border: 0;
  box-shadow: none;
}

.is-multiple .index-post .entry-image-wrap{
  aspect-ratio: 3 / 2;
  margin-bottom: 18px;
  background: #ddd8d1;
}

.is-multiple .index-post .entry-title{
  font-size: clamp(23px, 2.3vw, 31px);
  line-height: 1.12;
  letter-spacing: -0.03em;
}

.is-multiple .entry-excerpt,
.is-multiple .excerpt{
  color: var(--ee-text-soft);
  font-size: 15px;
  line-height: 1.58;
  margin-top: 10px;
}

.is-multiple .entry-meta{
  color: var(--ee-muted);
  font-size: 13px;
  margin-top: 10px;
}

/* --- Sidebar: restrained article utilities --- */
#sidebar-wrapper{
  color: var(--ee-text-soft);
}

#sidebar-wrapper .widget{
  margin: 0 0 22px;
  padding: 22px;
  background: var(--ee-surface);
  border: 1px solid var(--ee-border);
  box-shadow: none;
}

#sidebar-wrapper .widget:last-child{
  margin-bottom: 0;
}

#sidebar-wrapper .widget-title,
#sidebar-wrapper .title-wrap,
#sidebar-wrapper h2,
#sidebar-wrapper h3{
  color: #171b20 !important;
  font-size: 18px;
  line-height: 1.15;
  letter-spacing: -0.02em;
  margin: 0 0 18px !important;
  padding: 0 0 12px !important;
  background: transparent !important;
  border: 0 !important;
  border-bottom: 2px solid #171b20 !important;
  clip-path: none !important;
}

#sidebar-wrapper img{
  border-radius: 0;
}

/* Use native CSS sticky behavior on posts, ordinary pages and archive views. */
body:not(.ee-full-width-page) #sidebar-wrapper{
  position: sticky;
  top: 86px;
}

/* --- Sidebar module details --- */
#sidebar-wrapper .widget-content{
  color: var(--ee-text-soft);
  font-size: 14px;
  line-height: 1.45;
}

#sidebar-wrapper .default-item,
#sidebar-wrapper .featured-post{
  display: grid;
  grid-template-columns: 88px minmax(0, 1fr);
  gap: 14px;
  align-items: start;
  min-width: 0;
}

#sidebar-wrapper .default-item .entry-image-wrap,
#sidebar-wrapper .featured-post .entry-image-wrap{
  width: 88px;
  height: 72px;
  margin: 0;
}

#sidebar-wrapper .default-item .entry-header,
#sidebar-wrapper .featured-post .entry-header,
#sidebar-wrapper .featured-post .entry-info{
  position: static;
  width: auto;
  min-width: 0;
  padding: 0;
  background: none;
}

#sidebar-wrapper .default-item .entry-title,
#sidebar-wrapper .featured-post .entry-title{
  font-size: 15px;
  line-height: 1.3;
}

#sidebar-wrapper .default-item .entry-title a,
#sidebar-wrapper .featured-post .entry-title a,
#sidebar-wrapper .featured-post .entry-info .entry-title a{
  color: var(--ee-text);
  text-shadow: none;
}

#sidebar-wrapper .default-item .entry-title a:hover,
#sidebar-wrapper .featured-post .entry-title a:hover{
  color: var(--ee-accent);
}

#sidebar-wrapper .entry-meta,
#sidebar-wrapper .featured-post .entry-info .entry-meta{
  color: var(--ee-muted);
  text-shadow: none;
}

#sidebar-wrapper .social-icons{
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

#sidebar-wrapper .social-icons li{
  margin: 0;
}

#sidebar-wrapper .social-icons a{
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  border-radius: 0;
}

/* --- Footer --- */
#footer-wrapper,
.footerbar{
  background: var(--ee-dark);
  color: var(--ee-on-dark-muted);
}

#footer-wrapper{
  border: 0;
}

#footer-wrapper .container,
.footerbar .container{
  width: min(calc(100% - 48px), var(--ee-wide));
}

#footer-wrapper h2,
#footer-wrapper h3,
#footer-wrapper .title,
#footer-wrapper .footer-title{
  color: var(--ee-on-dark);
  font-family: var(--title-font);
}

#footer-wrapper a,
.footerbar a{
  color: var(--ee-on-dark);
}

#footer-wrapper a:hover,
.footerbar a:hover{
  color: var(--ee-accent);
}

#footer-ads-wrap{
  background: var(--ee-bg);
}

/* --- Translator normalization --- */
#google_translate_element,
.goog-te-gadget,
.goog-te-gadget select{
  font-family: var(--body-font) !important;
}

.goog-te-gadget::before{
  content: "Traduire l’article :";
  color: var(--ee-text);
  font-size: 14px;
}

/* --- Mobile --- */
@media (max-width: 980px) {
  .topbar-wrap,
.topbar-items{
    min-height: 96px;
  }

  .topbar-wrap .main-logo img{
    max-height: 68px;
    max-width: min(390px, 68vw);
  }

  .cryzen-mobile-logo-section{
    display: flex;
  }

  #cryzen-pro-main-nav > .widget > .widget-content > ul{
    display: none;
  }

  #content-wrapper > .container,
.is-post #content-wrapper > .container,
.is-page #content-wrapper > .container,
.is-multiple #content-wrapper > .container{
    grid-template-columns: minmax(0, 1fr);
    width: min(calc(100% - 40px), var(--ee-wide));
  }

  #sidebar-wrapper{
    display: none !important;
  }
}

@media (max-width: 680px) {
  .row-x1,
#content-wrapper > .container,
.is-post #content-wrapper > .container,
#footer-wrapper .container,
.footerbar .container{
    width: min(calc(100% - 30px), var(--ee-wide));
  }

  #content-wrapper{
    padding: 34px 0 54px;
  }

  .ee-full-width-page #content-wrapper{
    padding-top: 0;
  }

  .topbar-wrap,
.topbar-items{
    min-height: 82px;
  }

  .topbar-wrap .main-logo img{
    max-height: 56px;
    max-width: 72vw;
  }

  .is-post .entry-title,
.is-post .post-title,
.is-post h1.post-title{
    font-size: clamp(36px, 11vw, 50px);
  }

  .is-post .post-body{
    font-size: 17px;
    line-height: 1.68;
  }

  .is-multiple .blog-posts,
.is-multiple .index-post-wrap{
    grid-template-columns: minmax(0, 1fr);
    gap: 42px;
  }
}

/* Electric Eye v1.3 — solid multi-level desktop navigation
   Only the root menu is horizontal. Every branch is a complete vertical panel. */
@media (min-width: 981px) {
  /* Reset inherited layout rules on every dropdown level. */
  #cryzen-pro-main-nav ul#cryzen-pro-main-nav-menu ul,
#cryzen-pro-main-nav ul#cryzen-pro-main-nav-menu .ul,
#cryzen-pro-main-nav ul#cryzen-pro-main-nav-menu .m-sub{
    display: block !important;
    align-items: initial;
    gap: 0;
    list-style: none;
    margin: 0;
    padding: 6px 0;
    width: 300px;
    min-width: 300px;
    max-width: min(340px, calc(100vw - 32px));
    background: var(--ee-surface);
    border: 1px solid var(--ee-border);
    box-shadow: 0 16px 42px rgba(0,0,0,.20);
    overflow: visible;
  }

  /* First dropdown panel. */
  #cryzen-pro-main-nav ul#cryzen-pro-main-nav-menu > li > ul,
#cryzen-pro-main-nav ul#cryzen-pro-main-nav-menu > li > .ul{
    position: absolute;
    top: 100%;
    left: 0;
    right: auto;
    z-index: 100000;
    visibility: hidden;
    opacity: 0;
    pointer-events: none;
    transform: translateY(6px);
    transition: opacity .14s ease, transform .14s ease, visibility .14s ease;
  }

  /* Every further branch opens as one complete panel on the right. */
  #cryzen-pro-main-nav ul#cryzen-pro-main-nav-menu ul li > ul,
#cryzen-pro-main-nav ul#cryzen-pro-main-nav-menu ul li > .ul{
    position: absolute;
    top: -7px;
    left: calc(100% - 1px);
    right: auto;
    z-index: 100001;
    visibility: hidden;
    opacity: 0;
    pointer-events: none;
    transform: translateX(6px);
    transition: opacity .14s ease, transform .14s ease, visibility .14s ease;
  }

  #cryzen-pro-main-nav ul#cryzen-pro-main-nav-menu li:hover > ul,
#cryzen-pro-main-nav ul#cryzen-pro-main-nav-menu li:hover > .ul,
#cryzen-pro-main-nav ul#cryzen-pro-main-nav-menu li:focus-within > ul,
#cryzen-pro-main-nav ul#cryzen-pro-main-nav-menu li:focus-within > .ul{
    visibility: visible;
    opacity: 1;
    pointer-events: auto;
    transform: none;
  }

  /* A menu branch is a vertical list of full-width, unified rows. */
  #cryzen-pro-main-nav ul#cryzen-pro-main-nav-menu ul > li,
#cryzen-pro-main-nav ul#cryzen-pro-main-nav-menu .ul > li{
    position: relative;
    display: block !important;
    float: none !important;
    width: 100% !important;
    min-width: 0;
    margin: 0;
    padding: 0;
    border: 0;
  }

  #cryzen-pro-main-nav ul#cryzen-pro-main-nav-menu ul > li + li,
#cryzen-pro-main-nav ul#cryzen-pro-main-nav-menu .ul > li + li{
    border-top: 1px solid var(--ee-border);
  }

  #cryzen-pro-main-nav ul#cryzen-pro-main-nav-menu ul > li > a,
#cryzen-pro-main-nav ul#cryzen-pro-main-nav-menu .ul > li > a{
    box-sizing: border-box;
    display: flex !important;
    width: 100% !important;
    min-height: 48px;
    align-items: center;
    justify-content: space-between;
    gap: 18px;
    margin: 0;
    padding: 12px 17px;
    color: var(--ee-text);
    background: transparent;
    font-family: var(--menu-font);
    font-size: 14px;
    font-weight: 600;
    line-height: 1.25;
    letter-spacing: 0;
    text-transform: none;
    white-space: nowrap;
    word-break: keep-all;
    overflow-wrap: normal;
    text-decoration: none;
  }

  #cryzen-pro-main-nav ul#cryzen-pro-main-nav-menu ul > li:hover > a,
#cryzen-pro-main-nav ul#cryzen-pro-main-nav-menu ul > li:focus-within > a,
#cryzen-pro-main-nav ul#cryzen-pro-main-nav-menu .ul > li:hover > a,
#cryzen-pro-main-nav ul#cryzen-pro-main-nav-menu .ul > li:focus-within > a{
    color: #fff;
    background: var(--ee-accent);
  }

  #cryzen-pro-main-nav ul#cryzen-pro-main-nav-menu ul > li.has-sub > a::after,
#cryzen-pro-main-nav ul#cryzen-pro-main-nav-menu .ul > li.has-sub > a::after{
    content: '\f054';
    flex: 0 0 auto;
    float: none;
    margin: 0 0 0 auto;
    font-family: 'Font Awesome 5 Free';
    font-size: 9px;
    font-weight: 900;
  }

  #cryzen-pro-main-nav ul#cryzen-pro-main-nav-menu ul > li.has-sub:hover > a::after,
#cryzen-pro-main-nav ul#cryzen-pro-main-nav-menu ul > li.has-sub:focus-within > a::after{
    color: #fff;
  }

  /* JavaScript adds this class when a right-opening branch would leave the viewport. */
  #cryzen-pro-main-nav ul#cryzen-pro-main-nav-menu li.ee-open-left > ul,
#cryzen-pro-main-nav ul#cryzen-pro-main-nav-menu li.ee-open-left > .ul{
    left: auto;
    right: calc(100% - 1px);
    transform: translateX(-6px);
  }

  #cryzen-pro-main-nav ul#cryzen-pro-main-nav-menu li.ee-open-left:hover > ul,
#cryzen-pro-main-nav ul#cryzen-pro-main-nav-menu li.ee-open-left:hover > .ul,
#cryzen-pro-main-nav ul#cryzen-pro-main-nav-menu li.ee-open-left:focus-within > ul,
#cryzen-pro-main-nav ul#cryzen-pro-main-nav-menu li.ee-open-left:focus-within > .ul{
    transform: none;
  }

  .rtl #cryzen-pro-main-nav ul#cryzen-pro-main-nav-menu ul li > ul,
.rtl #cryzen-pro-main-nav ul#cryzen-pro-main-nav-menu ul li > .ul{
    left: auto;
    right: calc(100% - 1px);
  }
}

/* ========================================================================== 
   ELECTRIC EYE — TEST BUILD V1.4
   Refined identity masthead: wordmark backdrop + rolling-eye emblem
   ========================================================================== */

/* Desktop masthead: a single, deliberate brand composition. */
@media only screen and (min-width: 981px) {
  .topbar-wrap{
    position: relative;
    display: flex !important;
    min-height: 184px;
    height: 184px;
    overflow: hidden;
    isolation: isolate;
    background-color: #111;
    background-image: url(https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEibPxoLayjUc1fz4srbhiEK7pHdxEDu7kC9tdXPbUZ99FA8eW-mUJ6dhi9vfNTRuu2BY2HKENP5ghLKuR0SX7DBTQ5uaWPJs8qKff1GSUI1kzqQ-MWnNMPNuL5EMVCGjEUlyGNAiH1WasgwBlp9QvcCpzBhK4bHVTDZiKAQDgrmbwE0g2rk8TW5Wjwq92I/s16000/ElecEyeNewLog.1.jpeg);
    background-repeat: no-repeat;
    background-position: center;
    background-size: min(1180px, 92vw) auto;
  }

  /* Controlled overlay: keeps the original artwork visible without looking like a raw banner. */
  .topbar-wrap::before{
    content: "";
    position: absolute;
    inset: 0;
    z-index: -1;
    height: auto;
    background:
      linear-gradient(90deg, rgba(10,10,10,.78) 0%, rgba(10,10,10,.34) 24%, rgba(10,10,10,.18) 50%, rgba(10,10,10,.34) 76%, rgba(10,10,10,.78) 100%),
      linear-gradient(180deg, rgba(10,10,10,.22) 0%, rgba(10,10,10,.08) 54%, rgba(10,10,10,.58) 100%);
    pointer-events: none;
  }

  .topbar-wrap::after{
    content: "";
    position: absolute;
    left: 50%;
    bottom: 18px;
    width: 62px;
    height: 2px;
    transform: translateX(-50%);
    background: var(--ee-accent);
    opacity: .9;
    pointer-events: none;
  }

  .topbar-wrap > .container,
.topbar-items{
    width: 100%;
    min-height: 184px;
  }

  .topbar-items{
    display: flex;
    align-items: center;
    justify-content: center;
  }

  /* Remove the ghost columns that were nudging the emblem off-centre. */
  .topbar-items > .flex-left,
.topbar-items > .flex-right{
    display: none !important;
  }

  .topbar-items > .flex-center{
    position: relative;
    z-index: 2;
    display: flex;
    align-items: center;
    justify-content: center;
    width: auto;
    min-width: 0;
  }

  .topbar-items .main-logo{
    float: none;
    width: 122px;
    height: 122px;
    padding: 0;
    margin: 0;
    overflow: visible;
  }

  .topbar-items .main-logo .widget,
.topbar-items .main-logo .logo-img{
    width: 122px;
    height: 122px;
    overflow: visible;
  }

  .topbar-wrap .main-logo img{
    display: block;
    width: 122px;
    height: 122px;
    max-width: none;
    max-height: none;
    margin: 0;
    object-fit: contain;
    border-radius: 50%;
    background: rgba(255,255,255,.92);
    border: 3px solid rgba(255,255,255,.82);
    box-shadow:
      0 0 0 7px rgba(0,0,0,.28),
      0 14px 34px rgba(0,0,0,.48);
    transform: none;
    transition: transform .25s ease, box-shadow .25s ease;
  }

  .topbar-wrap .main-logo a:hover img,
.topbar-wrap .main-logo a:focus-visible img{
    transform: scale(1.035);
    box-shadow:
      0 0 0 7px rgba(216,35,35,.22),
      0 16px 38px rgba(0,0,0,.52);
  }
}

/* Welcome page: suppress Blogger page furniture only on the designated landing page. */
.ee-welcome-page .item-post .entry-header.blog-entry-header,
.ee-welcome-page .item-post .entry-meta,
.ee-welcome-page .item-post .post-meta,
.ee-welcome-page .item-post .entry-info,
.ee-welcome-page .item-post .post-footer{
  display: none !important;
}
.ee-welcome-page .item-post-inner,
.ee-welcome-page .entry-content-wrap,
.ee-welcome-page .post-body{
  margin-top: 0 !important;
  padding-top: 0 !important;
}

/* Dedicated responsive ad below the custom Welcome-page content. */
.ee-welcome-ad{
  width: min(100%, 1100px);
  margin: 36px auto 0;
  padding: 24px 0 0;
  border-top: 1px solid rgba(23,23,23,.12);
  clear: both;
}
.ee-welcome-ad .adsbygoogle{
  display: block;
