}
.ee-welcome-ad:has(.adsbygoogle[data-ad-status='unfilled']){
  display: none;
}
@media only screen and (max-width: 680px){
  .ee-welcome-ad{
    margin-top: 26px;
    padding-top: 18px;
  }
}


/* One controlled in-article ad after the opening text. Existing manual article ads take precedence. */
.ee-article-opening-ad{
  width: 100%;
  margin: 38px 0;
  clear: both;
  overflow: hidden;
  text-align: center;
}
.ee-article-opening-ad .adsbygoogle{
  display: block;
  width: 100%;
  text-align: center;
}
.ee-article-opening-ad:has(.adsbygoogle[data-ad-status='unfilled']){
