/* ========================================================================== 
   ELECTRIC EYE THEME 2.0 — FULL-WIDTH SIGNATURE MASTHEAD
   ========================================================================== */

@media only screen and (min-width: 981px) {
  #header-wrapper{
    --ee-masthead-height: clamp(220px, 19vw, 300px);
    --ee-masthead-compact-height: 0px;
    overflow: visible;
  }

  .topbar-wrap{
    position: relative;
    display: block !important;
    width: 100%;
    min-height: var(--ee-masthead-height);
    height: var(--ee-masthead-height);
    overflow: visible;
    isolation: isolate;
    background-color: #0b0b0b;
    background-image:
      linear-gradient(90deg, rgba(5,5,5,.78) 0%, rgba(5,5,5,.16) 13%, rgba(5,5,5,.06) 50%, rgba(5,5,5,.16) 87%, rgba(5,5,5,.78) 100%),
      linear-gradient(180deg, rgba(5,5,5,.18) 0%, rgba(5,5,5,.04) 46%, rgba(5,5,5,.66) 100%),
      url(https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEibPxoLayjUc1fz4srbhiEK7pHdxEDu7kC9tdXPbUZ99FA8eW-mUJ6dhi9vfNTRuu2BY2HKENP5ghLKuR0SX7DBTQ5uaWPJs8qKff1GSUI1kzqQ-MWnNMPNuL5EMVCGjEUlyGNAiH1WasgwBlp9QvcCpzBhK4bHVTDZiKAQDgrmbwE0g2rk8TW5Wjwq92I/s16000/ElecEyeNewLog.1.jpeg);
    background-repeat: no-repeat;
    background-position: center, center, center;
    background-size: 100% 100%, 100% 100%, cover;
    transition: height .42s cubic-bezier(.2,.7,.2,1), min-height .42s cubic-bezier(.2,.7,.2,1), opacity .3s ease;
  }

  .topbar-wrap::before{
    content: "";
    position: absolute;
    inset: 0;
    z-index: 0;
    height: auto;
    background:
      radial-gradient(ellipse at center, transparent 26%, rgba(0,0,0,.12) 60%, rgba(0,0,0,.48) 100%),
      linear-gradient(180deg, transparent 72%, rgba(0,0,0,.48) 100%);
    pointer-events: none;
  }

  .topbar-wrap::after{
    content: "";
    position: absolute;
    left: 0;
    right: 0;
    bottom: 0;
    width: auto;
    height: 1px;
    transform: none;
    background: rgba(255,255,255,.15);
    opacity: 1;
    pointer-events: none;
  }

  .topbar-wrap > .container,
.topbar-items{
    width: 100%;
    max-width: none;
    min-height: 100%;
    height: 100%;
  }

  .topbar-wrap > .container{ padding: 0; }

  .topbar-items{
    position: relative;
    display: flex;
    align-items: flex-end;
    justify-content: center;
    overflow: visible;
  }

  .topbar-items > .flex-left,
.topbar-items > .flex-right{ display: none !important; }

  .topbar-items > .flex-center{
    position: absolute;
    z-index: 4;
    left: 50%;
    bottom: -43px;
    width: 116px;
    height: 116px;
    transform: translateX(-50%);
    display: flex;
    align-items: center;
    justify-content: center;
    transition: transform .38s cubic-bezier(.2,.7,.2,1), opacity .25s ease;
  }

  .topbar-items .main-logo,
.topbar-items .main-logo .widget,
.topbar-items .main-logo .logo-img{
    width: 116px;
    height: 116px;
    padding: 0;
    margin: 0;
    overflow: visible;
  }

  .topbar-wrap .main-logo img{
    display: block;
    width: 116px;
    height: 116px;
    max-width: none;
    max-height: none;
    margin: 0;
    object-fit: contain;
    border-radius: 50%;
    background: rgba(255,255,255,.96);
    border: 3px solid rgba(255,255,255,.86);
    box-shadow: 0 0 0 8px rgba(0,0,0,.34), 0 18px 46px rgba(0,0,0,.55);
    transition: transform .25s ease, box-shadow .25s ease;
  }

  .topbar-wrap .main-logo a:hover img,
.topbar-wrap .main-logo a:focus-visible img{
    transform: scale(1.045);
    box-shadow: 0 0 0 8px rgba(216,35,35,.25), 0 20px 50px rgba(0,0,0,.6);
  }

  .main-header{
    position: sticky;
    top: 0;
    z-index: 120;
    min-height: 70px;
    background: rgba(13,13,13,.97);
    border-top: 0;
    border-bottom: 1px solid rgba(255,255,255,.14);
    box-shadow: 0 8px 24px rgba(0,0,0,.14);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
  }

  .header-header, .header-inner, .header-items{ min-height: 70px; }

  #cryzen-pro-main-nav ul#cryzen-pro-main-nav-menu{
    justify-content: center;
    padding-left: 76px;
    padding-right: 76px;
  }

  #cryzen-pro-main-nav > .widget > .widget-content > ul > li > a,
#cryzen-pro-main-nav .main-nav > li > a{ min-height: 70px; }

  /* The eye occupies the centre line without blocking menu clicks. */
  .main-header::after{
    content: "";
    display: block;
    position: absolute;
    left: 50%;
    top: 0;
    width: 126px;
    height: 70px;
    transform: translateX(-50%);
    pointer-events: none;
  }

  body.ee-header-compact .topbar-wrap{
    height: var(--ee-masthead-compact-height);
    min-height: var(--ee-masthead-compact-height);
    opacity: 0;
