  /* The existing compact eye remains the mobile Home control. */
  #cryzen-mobile-logo-section{
    left: 50%;
  }

  #cryzen-mobile-logo-section img{
    width: 40px;
    height: 40px;
    max-width: 40px;
    max-height: 40px;
  }
}

@media only screen and (max-width: 480px) {
  #cryzen-mobile-logo-section img{
    width: 38px;
    height: 38px;
    max-width: 38px;
    max-height: 38px;
  }
}

/* Remove the legacy textual Home entry. The rolling eye is the sole Home link. */
#cryzen-pro-main-nav ul#cryzen-pro-main-nav-menu > li:first-child,
.cryzen-pro-mobile-menu > ul > li:first-child{
  display: none !important;
}

/* Neutralize the commercial-theme ribbon treatment on sidebar headings. */
#sidebar-wrapper .widget-title,
#sidebar-wrapper .widget-title h3,
#sidebar-wrapper .title-wrap,
#sidebar-wrapper .title-wrap h3,
#sidebar-wrapper .widget > h2,
#sidebar-wrapper .widget > h3{
  color: #171b20 !important;
  background: transparent !important;
  text-shadow: none !important;
  opacity: 1 !important;
  clip-path: none !important;
  -webkit-clip-path: none !important;
}

#sidebar-wrapper .widget-title::before,
#sidebar-wrapper .widget-title::after,
#sidebar-wrapper .title-wrap::before,
#sidebar-wrapper .title-wrap::after,
#sidebar-wrapper .widget > h2::before,
#sidebar-wrapper .widget > h2::after,
#sidebar-wrapper .widget > h3::before,
#sidebar-wrapper .widget > h3::after{
  content: none !important;
  display: none !important;
}

#sidebar-wrapper .widget-title h3,
#sidebar-wrapper .title-wrap h3{
  padding: 0 !important;
  margin: 0 !important;
  width: auto !important;
}

/* Keep article and utility cards visually consistent. */
.is-post .item-post,
.is-page:not(.ee-full-width-page) .item-post,
#sidebar-wrapper .widget{
  background-color: var(--ee-surface) !important;
}

.is-post .item-post{
  border: 1px solid var(--ee-border) !important;
  padding: clamp(26px, 3.2vw, 46px) !important;
  box-shadow: none !important;
}

.is-page:not(.ee-full-width-page) .item-post{
  border: 1px solid var(--ee-border);
  padding: clamp(26px, 3.2vw, 46px);
}

/* Prevent old post wrappers from constraining the enlarged editorial column. */
.is-post .item-post-wrap,
.is-post .item-post,
.is-post article,
.is-post .post-outer,
.is-post .post{
  width: 100%;
  max-width: none;
}

@media (min-width: 981px) {
  #content-wrapper > .container{
    grid-template-columns: minmax(0, 1fr) 250px;
    gap: 30px;
  }
}

@media (max-width: 680px) {
  .is-post .item-post,
.is-page:not(.ee-full-width-page) .item-post{
    padding: 22px 18px;
  }
}

:root{
  --ee-wide: 1680px;
  --ee-standard: 1620px;
  --ee-reading: 1180px;
  --ee-sidebar: 300px;
}

/* Give the article substantially more horizontal room without letting the
   sidebar dominate the page. */
#content-wrapper > .container{
  width: min(calc(100% - 40px), var(--ee-standard));
  grid-template-columns: minmax(0, 1fr) var(--ee-sidebar);
  gap: 24px;
}

.is-post .post-header,
.is-post .entry-header,
.is-post .post-body,
.is-post .post-footer,
.is-post .post-labels,
.is-post .post-share,
.is-post .comments,
.is-post #comments{
  max-width: var(--ee-reading);
}

/* Preserve every article image's original aspect ratio. */
.is-post .post-body img{
  width: auto;
  max-width: 100%;
  height: auto !important;
  object-fit: contain !important;
}

/* Reduce the excessive vertical and horizontal breathing room around image
   groups. This does not crop or reformat article photographs. */
.is-post .post-body .separator,
.is-post .post-body figure{
  margin-top: 0.75em !important;
  margin-bottom: 0.75em !important;
}

.is-post .post-body .separator + .separator,
.is-post .post-body figure + figure{
  margin-top: 0.45em !important;
}

.is-post .post-body table{
  margin-top: 0.8em !important;
  margin-bottom: 0.8em !important;
  border-spacing: 4px !important;
}

.is-post .post-body td,
.is-post .post-body th{
  padding: 2px !important;
}

/* Sidebar cards */
#sidebar-wrapper .widget{
  padding: 24px;
}

/* Sidebar article rows: square thumbnails and a wider text column. */
#sidebar-wrapper .default-item,
#sidebar-wrapper .featured-post{
  grid-template-columns: 78px minmax(0, 1fr);
  gap: 14px;
  align-items: start;
}

#sidebar-wrapper .default-item .entry-image-wrap,
#sidebar-wrapper .featured-post .entry-image-wrap{
  width: 78px !important;
  height: 78px !important;
  aspect-ratio: 1 / 1;
  object-fit: cover !important;
  overflow: hidden;
  flex: 0 0 78px;
}

#sidebar-wrapper .default-item .entry-thumb,
#sidebar-wrapper .featured-post .entry-thumb{
  width: 100%;
  height: 100%;
  background-size: cover !important;
  background-position: center center !important;
}

/* Sidebar titles should read as secondary editorial links rather than bold
   headlines. Limit them to four lines at most. */
#sidebar-wrapper .default-item .entry-title,
#sidebar-wrapper .featured-post .entry-title,
#sidebar-wrapper .default-item .entry-title a,
#sidebar-wrapper .featured-post .entry-title a,
#sidebar-wrapper .featured-post .entry-info .entry-title a{
  color: var(--ee-text);
  font-size: 14px !important;
  font-weight: 400 !important;
  line-height: 1.35 !important;
  letter-spacing: 0 !important;
  word-break: normal !important;
  overflow-wrap: break-word !important;
  hyphens: none !important;
}

#sidebar-wrapper .default-item .entry-title a,
#sidebar-wrapper .featured-post .entry-title a,
#sidebar-wrapper .featured-post .entry-info .entry-title a{
  display: -webkit-box;
  overflow: hidden;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 4;
  line-clamp: 4;
}

/* Social links: retain the icon colours but provide enough room for complete
   platform names. */
#sidebar-wrapper .social-icons{
  display: grid !important;
  grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
  gap: 10px !important;
}

#sidebar-wrapper .social-icons li{
  width: 100%;
  min-width: 0;
}

#sidebar-wrapper .social-icons a{
  width: 100% !important;
  min-width: 0;
  height: 42px !important;
  display: flex !important;
  align-items: center;
  justify-content: flex-start;
  padding: 0 !important;
  overflow: hidden;
}

#sidebar-wrapper .social-icons a::before{
  flex: 0 0 42px;
  width: 42px;
  padding: 0 !important;
  text-align: center;
}

#sidebar-wrapper .social-icons span,
#sidebar-wrapper .social-icons .text{
  display: block !important;
  min-width: 0;
  padding: 0 9px !important;
  border-left: 1px solid rgba(255,255,255,.22);
  color: #fff !important;
  font-size: 12px !important;
  font-weight: 500;
  line-height: 1.15 !important;
  white-space: normal !important;
  word-break: normal !important;
  overflow-wrap: normal !important;
}

/* Keep the layout balanced on smaller desktop screens. */
@media (max-width: 1320px) {
  :root{
    --ee-reading: 1040px;
    --ee-sidebar: 280px;
  }

  #content-wrapper > .container{
    width: min(calc(100% - 36px), 1380px);
    gap: 22px;
  }
}

@media (max-width: 1100px) {
  :root{
    --ee-reading: 100%;
  }

  #content-wrapper > .container{
    grid-template-columns: minmax(0, 1fr);
  }

  #sidebar-wrapper{
    display: none !important;
  }
}

/* ---------- Article spacing ---------- */

/* Reduce the broad default spacing between article blocks. */
.is-post .post-body > p,
.is-post .post-body > div,
.is-post .post-body > section,
.is-post .post-body > figure,
.is-post .post-body > table,
.is-post .post-body > ul,
.is-post .post-body > ol,
.is-post .post-body > blockquote{
  margin-top: 0.65em !important;
  margin-bottom: 0.65em !important;
}

/* Consecutive blocks should sit closer together. */
.is-post .post-body > p + p,
.is-post .post-body > div + div,
.is-post .post-body > p + div,
.is-post .post-body > div + p,
.is-post .post-body > figure + figure,
.is-post .post-body > table + table,
.is-post .post-body > ul + ul,
.is-post .post-body > ol + ol{
  margin-top: 0.35em !important;
}

/* Compact hand-built lists of related links and similar archive sections. */
.is-post .post-body ul,
.is-post .post-body ol{
  padding-left: 1.25em !important;
}

.is-post .post-body li{
  margin: 0.18em 0 !important;
  line-height: 1.42 !important;
}

.is-post .post-body li + li{
  margin-top: 0.18em !important;
}

/* Many older posts use centered DIVs or paragraphs for link lists. */
.is-post .post-body div[style*="text-align: center"],
.is-post .post-body p[style*="text-align: center"],
.is-post .post-body center{
  line-height: 1.4 !important;
}

.is-post .post-body div[style*="text-align: center"] > a,
.is-post .post-body p[style*="text-align: center"] > a,
.is-post .post-body center > a{
  display: inline-block;
  margin: 0.12em 0 !important;
}

/* Remove oversized spacing caused by repeated line breaks in archive lists. */
.is-post .post-body br + br{
  display: none;
}

/* Keep image rows tight without changing image proportions. */
.is-post .post-body .separator{
  margin: 0.45em 0 !important;
}

.is-post .post-body table{
  border-spacing: 2px !important;
}

.is-post .post-body td,
.is-post .post-body th{
  padding: 1px !important;
}

/* Tighter section headings inside articles. */
.is-post .post-body h2,
.is-post .post-body h3,
.is-post .post-body h4{
  margin-top: 1.05em !important;
  margin-bottom: 0.45em !important;
}

/* ---------- Sidebar heading cleanup ---------- */

/* Remove the old decorative triangle completely. */
#sidebar-wrapper .widget-title::before,
#sidebar-wrapper .widget-title::after,
#sidebar-wrapper .widget-title h3::before,
#sidebar-wrapper .widget-title h3::after{
  display: none !important;
  content: none !important;
}

#sidebar-wrapper .widget-title{
  padding-right: 0 !important;
}

/* ---------- Sidebar article cards ---------- */

/* Convert sidebar article lists into 3:2 image cards with text overlays. */
#sidebar-wrapper .default-items,
#sidebar-wrapper .featured-posts{
  display: grid;
  grid-template-columns: 1fr;
  gap: 12px;
}

#sidebar-wrapper .default-item,
#sidebar-wrapper .featured-post{
  position: relative;
  display: block !important;
  min-height: 0;
  aspect-ratio: 3 / 2;
  overflow: hidden;
  padding: 0 !important;
  margin: 0 !important;
  background: #111;
  border: 0 !important;
}

#sidebar-wrapper .default-item .entry-image-wrap,
#sidebar-wrapper .featured-post .entry-image-wrap{
  position: absolute !important;
  inset: 0;
  width: 100% !important;
  height: 100% !important;
  aspect-ratio: 3 / 2 !important;
  margin: 0 !important;
  object-fit: cover !important;
  overflow: hidden;
  transition: filter 0.28s ease, transform 0.28s ease;
}

#sidebar-wrapper .default-item .entry-thumb,
#sidebar-wrapper .featured-post .entry-thumb{
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  background-size: cover !important;
  background-position: center center !important;
  transition: filter 0.28s ease, transform 0.28s ease;
}

/* Dark gradient guarantees readability without hiding the image. */
#sidebar-wrapper .default-item::after,
#sidebar-wrapper .featured-post::after{
  content: "";
  position: absolute;
  inset: 0;
  z-index: 2;
  pointer-events: none;
  background:
    linear-gradient(
      to top,
      rgba(0, 0, 0, 0.88) 0%,
      rgba(0, 0, 0, 0.58) 43%,
      rgba(0, 0, 0, 0.08) 76%
    );
  transition: background 0.28s ease;
}

/* Put all text over the lower part of the photograph. */
#sidebar-wrapper .default-item .entry-header,
#sidebar-wrapper .default-item .entry-title,
#sidebar-wrapper .featured-post .entry-header,
#sidebar-wrapper .featured-post .entry-info,
#sidebar-wrapper .featured-post .entry-title{
  position: absolute !important;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 4;
  width: 100%;
  padding: 14px !important;
  margin: 0 !important;
  background: transparent !important;
}

/* Sidebar card titles */
#sidebar-wrapper .default-item .entry-title,
#sidebar-wrapper .default-item .entry-title a,
#sidebar-wrapper .featured-post .entry-title,
#sidebar-wrapper .featured-post .entry-title a,
#sidebar-wrapper .featured-post .entry-info .entry-title a{
  color: #fff !important;
  font-size: 15px !important;
  font-weight: 500 !important;
  line-height: 1.28 !important;
  text-shadow: 0 1px 8px rgba(0,0,0,.9);
  display: -webkit-box !important;
  overflow: hidden !important;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 4;
  line-clamp: 4;
}

/* Keep dates/meta compact and readable over the image. */
#sidebar-wrapper .default-item .entry-meta,
#sidebar-wrapper .featured-post .entry-meta{
  color: rgba(255,255,255,.78) !important;
  font-size: 11px !important;
  margin-top: 5px !important;
}

/* Hover: monochrome image, red title, slightly darker overlay. */
#sidebar-wrapper .default-item:hover .entry-thumb,
#sidebar-wrapper .featured-post:hover .entry-thumb{
  filter: grayscale(1) brightness(.72);
  transform: scale(1.025);
}

#sidebar-wrapper .default-item:hover::after,
#sidebar-wrapper .featured-post:hover::after{
  background:
    linear-gradient(
      to top,
      rgba(0,0,0,.94) 0%,
      rgba(0,0,0,.70) 48%,
      rgba(0,0,0,.20) 100%
    );
}

#sidebar-wrapper .default-item:hover .entry-title,
#sidebar-wrapper .default-item:hover .entry-title a,
#sidebar-wrapper .featured-post:hover .entry-title,
#sidebar-wrapper .featured-post:hover .entry-title a,
#sidebar-wrapper .featured-post:hover .entry-info .entry-title a{
  color: #d82323 !important;
}

/* Remove separator lines that no longer suit image cards. */
#sidebar-wrapper .default-item,
#sidebar-wrapper .featured-post{
  border-bottom: 0 !important;
}

/* Prevent obsolete row-layout rules from constraining overlay cards. */
#sidebar-wrapper .default-item .entry-image,
#sidebar-wrapper .featured-post .entry-image,
#sidebar-wrapper .default-item .entry-header,
#sidebar-wrapper .featured-post .entry-header{
  width: auto !important;
  max-width: none !important;
}

/* Mobile/tablet fallback if the sidebar is ever displayed there. */
@media (max-width: 1100px) {
  #sidebar-wrapper .default-item,
#sidebar-wrapper .featured-post{
    aspect-ratio: 16 / 9;
  }
}

/* Center the complete sidebar title block over each image. */
#sidebar-wrapper .default-item .entry-header,
#sidebar-wrapper .default-item .entry-title,
#sidebar-wrapper .featured-post .entry-header,
#sidebar-wrapper .featured-post .entry-info,
#sidebar-wrapper .featured-post .entry-title{
  position: absolute !important;
  left: 50% !important;
  right: auto !important;
  top: 50% !important;
  bottom: auto !important;
  transform: translate(-50%, -50%) !important;
  width: 88% !important;
  max-width: 88% !important;
  padding: 0 !important;
  margin: 0 !important;
  text-align: center !important;
  background: transparent !important;
  z-index: 4;
}

/* Center both the title and any accompanying metadata. */
#sidebar-wrapper .default-item .entry-title,
#sidebar-wrapper .default-item .entry-title a,
#sidebar-wrapper .featured-post .entry-title,
#sidebar-wrapper .featured-post .entry-title a,
#sidebar-wrapper .featured-post .entry-info .entry-title a{
  color: #fff !important;
  font-size: 15px !important;
  font-weight: 500 !important;
  line-height: 1.28 !important;
  letter-spacing: 0 !important;
  text-align: center !important;
  text-shadow: 0 2px 10px rgba(0,0,0,.92);
  word-break: normal !important;
  overflow-wrap: break-word !important;
  hyphens: none !important;
  display: -webkit-box !important;
  overflow: hidden !important;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 4;
  line-clamp: 4;
}

#sidebar-wrapper .default-item .entry-meta,
#sidebar-wrapper .featured-post .entry-meta{
  justify-content: center !important;
  text-align: center !important;
}

/* Font-size classes are assigned according to actual title length. */
#sidebar-wrapper .ee-sidebar-title-short,
#sidebar-wrapper .ee-sidebar-title-short a{
  font-size: 16px !important;
  line-height: 1.27 !important;
}

#sidebar-wrapper .ee-sidebar-title-medium,
#sidebar-wrapper .ee-sidebar-title-medium a{
  font-size: 15px !important;
  line-height: 1.27 !important;
}

#sidebar-wrapper .ee-sidebar-title-long,
#sidebar-wrapper .ee-sidebar-title-long a{
  font-size: 14px !important;
  line-height: 1.25 !important;
}

#sidebar-wrapper .ee-sidebar-title-xlong,
#sidebar-wrapper .ee-sidebar-title-xlong a{
  font-size: 13px !important;
  line-height: 1.23 !important;
}

/* Keep centered titles readable on narrower desktop layouts. */
@media (max-width: 1320px) {
  #sidebar-wrapper .ee-sidebar-title-short,
#sidebar-wrapper .ee-sidebar-title-short a{
    font-size: 15px !important;
  }

  #sidebar-wrapper .ee-sidebar-title-medium,
#sidebar-wrapper .ee-sidebar-title-medium a{
    font-size: 14px !important;
  }

  #sidebar-wrapper .ee-sidebar-title-long,
#sidebar-wrapper .ee-sidebar-title-long a,
#sidebar-wrapper .ee-sidebar-title-xlong,
#sidebar-wrapper .ee-sidebar-title-xlong a{
    font-size: 13px !important;
  }
}

/* Preserve the established hover treatment. */
#sidebar-wrapper .default-item:hover .entry-title,
#sidebar-wrapper .default-item:hover .entry-title a,
#sidebar-wrapper .featured-post:hover .entry-title,
#sidebar-wrapper .featured-post:hover .entry-title a,
#sidebar-wrapper .featured-post:hover .entry-info .entry-title a{
  color: #d82323 !important;
}

/*
 * Position only the containing text panel. Keep the title itself in normal
 * flow inside that panel. This fixes the first Popular Posts card, whose
 * Blogger markup differs from the remaining cards.
 */
#sidebar-wrapper .default-item .entry-header,
#sidebar-wrapper .featured-post .entry-header,
#sidebar-wrapper .featured-post .entry-info{
  position: absolute !important;
  left: 50% !important;
  right: auto !important;
  top: 50% !important;
  bottom: auto !important;
  transform: translate(-50%, -50%) !important;
  width: 90% !important;
  max-width: 90% !important;
  padding: 0 !important;
  margin: 0 !important;
  z-index: 5 !important;
  background: transparent !important;
  text-align: center !important;
  visibility: visible !important;
  opacity: 1 !important;
  overflow: visible !important;
}

#sidebar-wrapper .default-item .entry-title,
#sidebar-wrapper .featured-post .entry-title,
#sidebar-wrapper .default-item .entry-title a,
#sidebar-wrapper .featured-post .entry-title a{
  position: static !important;
  left: auto !important;
  right: auto !important;
  top: auto !important;
  bottom: auto !important;
  transform: none !important;
  display: -webkit-box !important;
  width: 100% !important;
  max-width: 100% !important;
  padding: 0 !important;
  margin: 0 !important;
  color: #fff !important;
  font-size: 14px !important;
  font-weight: 500 !important;
  line-height: 1.24 !important;
  text-align: center !important;
  text-shadow: 0 2px 10px rgba(0,0,0,.95);
  visibility: visible !important;
  opacity: 1 !important;
  overflow: hidden !important;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 5;
  line-clamp: 5;
}

/* Keep metadata from displacing or masking the title on compact cards. */
#sidebar-wrapper .default-item .entry-meta,
#sidebar-wrapper .featured-post .entry-meta{
  display: none !important;
}

/* Slightly reduce very long titles without altering normal title sizing. */
#sidebar-wrapper .ee-sidebar-title-long,
#sidebar-wrapper .ee-sidebar-title-long a{
  font-size: 13px !important;
}

#sidebar-wrapper .ee-sidebar-title-xlong,
#sidebar-wrapper .ee-sidebar-title-xlong a{
  font-size: 12px !important;
  line-height: 1.2 !important;
}

/* Preserve hover treatment after normalising the markup. */
#sidebar-wrapper .default-item:hover .entry-title,
#sidebar-wrapper .default-item:hover .entry-title a,
#sidebar-wrapper .featured-post:hover .entry-title,
#sidebar-wrapper .featured-post:hover .entry-title a{
  color: #d82323 !important;
}

/* ---------- Mobile header and menu ---------- */

/* Restore the hamburger control on mobile. */
@media only screen and (max-width: 1100px) {
  .mobile-menu-toggle{
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    visibility: visible !important;
    opacity: 1 !important;
    pointer-events: auto !important;
  }

  #slide-menu,
.overlay{
    display: block !important;
  }

  .cryzen-pro-mobile-menu{
    display: block !important;
  }
}

/* ---------- Sidebar modules when stacked below the article ---------- */

@media only screen and (max-width: 1100px) {
  /*
   * The sidebar becomes a compact after-article section rather than a second
   * full-size desktop column.
   */
  #sidebar-wrapper{
    display: block !important;
    position: static !important;
    width: 100% !important;
    max-width: 100% !important;
    margin: 24px 0 0 !important;
  }

  #sidebar-wrapper .sidebar{
    display: grid !important;
    grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
    gap: 16px !important;
  }

  #sidebar-wrapper .widget{
    padding: 16px !important;
    margin: 0 !important;
  }

  #sidebar-wrapper .widget-title,
#sidebar-wrapper .widget-title h2,
#sidebar-wrapper .widget-title h3{
    margin-bottom: 12px !important;
    font-size: 17px !important;
    line-height: 1.2 !important;
  }

  #sidebar-wrapper .default-items,
#sidebar-wrapper .featured-posts{
    gap: 10px !important;
  }

  #sidebar-wrapper .default-item,
#sidebar-wrapper .featured-post{
    aspect-ratio: 3 / 2 !important;
  }

  /* Keep sidebar-title typography consistent with desktop. */
  #sidebar-wrapper .entry-title,
#sidebar-wrapper .entry-title a,
#sidebar-wrapper .ee-sidebar-title-short,
#sidebar-wrapper .ee-sidebar-title-short a,
#sidebar-wrapper .ee-sidebar-title-medium,
#sidebar-wrapper .ee-sidebar-title-medium a{
    font-size: 14px !important;
    line-height: 1.24 !important;
  }

  #sidebar-wrapper .ee-sidebar-title-long,
#sidebar-wrapper .ee-sidebar-title-long a{
    font-size: 13px !important;
  }

  #sidebar-wrapper .ee-sidebar-title-xlong,
#sidebar-wrapper .ee-sidebar-title-xlong a{
    font-size: 12px !important;
  }

  #sidebar-wrapper .social-icons,
#sidebar-wrapper .social-counter{
    grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
  }
}

@media only screen and (max-width: 680px) {
  #sidebar-wrapper{
    margin-top: 18px !important;
  }

  #sidebar-wrapper .sidebar{
    grid-template-columns: 1fr !important;
    gap: 12px !important;
  }

  #sidebar-wrapper .widget{
    padding: 14px !important;
  }

  #sidebar-wrapper .social-icons,
#sidebar-wrapper .social-counter{
    grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
  }
}

/* ---------- Article vertical rhythm ---------- */

/*
 * Neutralise the old Blogger habit of using empty DIVs, separators and BR tags
 * as layout spacers. Preserve actual content while removing artificial gaps.
 */
.is-post .post-body > *{
  margin-top: 0 !important;
  margin-bottom: 0.62em !important;
}

.is-post .post-body > * + *{
  margin-top: 0 !important;
}

.is-post .post-body p{
  margin: 0 0 0.62em !important;
  line-height: 1.62 !important;
}

.is-post .post-body p:empty,
.is-post .post-body div:empty,
.is-post .post-body span:empty{
  display: none !important;
  margin: 0 !important;
  padding: 0 !important;
  min-height: 0 !important;
}

.is-post .post-body br{
  line-height: 0.35 !important;
}

.is-post .post-body br + br{
  display: none !important;
}

.is-post .post-body .separator{
  margin: 0 0 0.4em !important;
  padding: 0 !important;
}

.is-post .post-body .separator + .separator{
  margin-top: 0 !important;
}

.is-post .post-body figure{
  margin: 0 0 0.45em !important;
  padding: 0 !important;
}

.is-post .post-body table{
  margin: 0 0 0.45em !important;
  border-spacing: 2px !important;
  border-collapse: separate !important;
}

.is-post .post-body td,
.is-post .post-body th{
  padding: 1px !important;
  vertical-align: top !important;
}

.is-post .post-body ul,
.is-post .post-body ol{
  margin: 0 0 0.62em !important;
  padding-left: 1.25em !important;
}

.is-post .post-body li{
  margin: 0 !important;
  line-height: 1.45 !important;
}

.is-post .post-body li + li{
  margin-top: 0.16em !important;
}

.is-post .post-body h2,
.is-post .post-body h3,
.is-post .post-body h4{
  margin: 0.9em 0 0.38em !important;
}

/* Compact centred archive/link blocks commonly used in older posts. */
.is-post .post-body [style*="text-align: center"]{
  margin-top: 0 !important;
  margin-bottom: 0.45em !important;
  line-height: 1.38 !important;
}

.is-post .post-body [style*="text-align: center"] a{
  margin: 0 !important;
  line-height: inherit !important;
}

/* Embedded players, banners and iframes should not create blank bands. */
.is-post .post-body iframe,
.is-post .post-body video,
.is-post .post-body audio,
.is-post .post-body .AppleMusicEmbed,
.is-post .post-body [class*="embed"]{
  margin-top: 0 !important;
  margin-bottom: 0.5em !important;
}

/* ---------- Sidebar section headings ---------- */

#sidebar-wrapper .widget-title,
#sidebar-wrapper .widget-title h2,
#sidebar-wrapper .widget-title h3,
#sidebar-wrapper .widget-title .title{
  text-align: center !important;
}

#sidebar-wrapper .widget-title h2,
#sidebar-wrapper .widget-title h3,
#sidebar-wrapper .widget-title .title{
  width: 100% !important;
  margin-left: auto !important;
  margin-right: auto !important;
  text-decoration: none !important;
}

/* ---------- Similar Articles / Related Posts ---------- */

#related-wrap{
  float: none !important;
  width: 100% !important;
  margin: 24px 0 0 !important;
  padding: 0 !important;
  background: #fff !important;
  box-shadow: none !important;
  border: 1px solid rgba(23, 23, 23, 0.10) !important;
}

/* Match the section heading to the rest of the site. */
#related-wrap .title-wrap,
#related-wrap .related-title{
  display: block !important;
  width: 100% !important;
  padding: 18px 20px 0 !important;
  margin: 0 !important;
  border: 0 !important;
  background: transparent !important;
  text-align: center !important;
}

#related-wrap .title-wrap .title,
#related-wrap .related-title .title,
#related-wrap .title-wrap h3,
#related-wrap .related-title h3{
  display: block !important;
  width: 100% !important;
  margin: 0 !important;
  padding: 0 !important;
  color: #171717 !important;
  font-family: var(--title-font) !important;
  font-size: 20px !important;
  font-weight: 700 !important;
  line-height: 1.2 !important;
  text-align: center !important;
  text-decoration: none !important;
}

#related-wrap .title-wrap::before,
#related-wrap .title-wrap::after,
#related-wrap .related-title::before,
#related-wrap .related-title::after,
#related-wrap .title-wrap .title::before,
#related-wrap .title-wrap .title::after,
#related-wrap .related-title .title::before,
#related-wrap .related-title .title::after{
  display: none !important;
  content: none !important;
}

/* Compact card grid. */
.cryzen-pro-related-content{
  float: none !important;
  width: 100% !important;
  padding: 16px 20px 20px !important;
  margin: 0 !important;
}

.related-posts{
  display: grid !important;
  grid-template-columns: repeat(3, minmax(0, 1fr)) !important;
  gap: 16px !important;
  margin: 0 !important;
}

.related-posts .related-item{
  display: block !important;
  min-width: 0 !important;
  margin: 0 !important;
}

/* Consistent 3:2 thumbnails, using crop only. */
.related-posts .entry-image-wrap{
  width: 100% !important;
  height: auto !important;
  aspect-ratio: 3 / 2 !important;
  margin: 0 0 9px !important;
  overflow: hidden !important;
  background: #111 !important;
}

.related-posts .entry-thumb{
  width: 100% !important;
  height: 100% !important;
  background-size: cover !important;
  background-position: center center !important;
}

/* Related titles match sidebar/card typography rather than article headlines. */
.related-posts .entry-header{
  margin: 0 !important;
  padding: 0 !important;
}

.related-posts .entry-title,
.related-posts .entry-title a{
  display: -webkit-box !important;
  margin: 0 !important;
  padding: 0 !important;
  color: #171717 !important;
  font-family: var(--title-font) !important;
  font-size: 14px !important;
  font-weight: 500 !important;
  line-height: 1.32 !important;
  letter-spacing: 0 !important;
  text-align: left !important;
  text-decoration: none !important;
  overflow: hidden !important;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
  line-clamp: 3;
}

.related-posts .entry-title a:hover,
.related-posts .entry-title a:focus-visible{
  color: #d82323 !important;
  text-decoration: none !important;
}

/* Hide related-post metadata to keep this module compact. */
.related-posts .entry-meta,
.related-posts .entry-category,
.related-posts .entry-excerpt{
  display: none !important;
}

/* Tablet */
@media only screen and (max-width: 900px) {
  #related-wrap .title-wrap,
#related-wrap .related-title{
    padding: 16px 16px 0 !important;
  }

  .cryzen-pro-related-content{
    padding: 14px 16px 16px !important;
  }

  .related-posts{
    grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
    gap: 14px !important;
  }

  .related-posts .entry-title,
.related-posts .entry-title a{
    font-size: 14px !important;
  }
}

/* Mobile */
@media only screen and (max-width: 560px) {
  #related-wrap{
    margin-top: 18px !important;
  }

  #related-wrap .title-wrap .title,
#related-wrap .related-title .title,
#related-wrap .title-wrap h3,
#related-wrap .related-title h3{
    font-size: 18px !important;
  }

  .related-posts{
    grid-template-columns: 1fr !important;
    gap: 12px !important;
  }

  .related-posts .related-item{
    display: grid !important;
    grid-template-columns: 118px minmax(0, 1fr) !important;
    gap: 11px !important;
    align-items: center !important;
  }

  .related-posts .entry-image-wrap{
    width: 118px !important;
    margin: 0 !important;
  }

  .related-posts .entry-title,
.related-posts .entry-title a{
    font-size: 14px !important;
    line-height: 1.3 !important;
    -webkit-line-clamp: 4;
    line-clamp: 4;
  }
}

@media (min-width: 1101px) {
  #content-wrapper > .container{
    display: grid !important;
    grid-template-columns: minmax(0, 1fr) 300px !important;
    gap: 18px !important;
    align-items: start !important;
  }

  #main-wrapper{
    width: auto !important;
    min-width: 0 !important;
  }

  #sidebar-wrapper{
    width: 300px !important;
    max-width: 300px !important;
    min-width: 0 !important;
    box-sizing: border-box !important;
  }
}

/* One-third less white space around sidebar images and lists. */
#sidebar-wrapper .widget{
  padding: 16px !important;
  box-sizing: border-box !important;
}

#sidebar-wrapper .widget-title{
  margin-bottom: 12px !important;
}

#sidebar-wrapper .default-items,
#sidebar-wrapper .featured-posts{
  gap: 10px !important;
}

#sidebar-wrapper .default-item,
#sidebar-wrapper .featured-post{
  margin-bottom: 10px !important;
}

#sidebar-wrapper .entry-image-wrap{
  margin-left: 0 !important;
  margin-right: 0 !important;
}

#sidebar-wrapper .entry-info{
  padding: 10px !important;
}

@media (max-width: 1100px) {
  #sidebar-wrapper .widget{
    padding: 14px !important;
  }
}

@media (min-width:1101px){
  #content-wrapper>.container{
    grid-template-columns:minmax(0,1fr) 285px !important;
    gap:16px !important;
  }
  #sidebar-wrapper{
    width:285px !important;
    max-width:285px !important;
  }
}

/* Center sidebar category/widget headings and remove decoration */
#sidebar-wrapper .widget-title,
#sidebar-wrapper .widget-title h2,
#sidebar-wrapper .widget-title h3,
#sidebar-wrapper .widget-title .title{
    text-align:center !important;
    text-decoration:none !important;
    border:none !important;
}
#sidebar-wrapper .widget-title:before,
#sidebar-wrapper .widget-title:after,
#sidebar-wrapper .widget-title h2:before,
#sidebar-wrapper .widget-title h2:after,
#sidebar-wrapper .widget-title h3:before,
#sidebar-wrapper .widget-title h3:after,
#sidebar-wrapper .widget-title .title:before,
#sidebar-wrapper .widget-title .title:after{
    display:none !important;
    content:none !important;
    border:none !important;
    background:none !important;
}

/*
 * Article photographs retain the alignment and sizing defined inside each
 * individual Blogger post. No global image alignment is imposed here.
 */

/* Restore a readable Apple Music playlist player height. */
.is-post .post-body iframe[src*="embed.music.apple.com"],
.is-post .post-body iframe[src*="music.apple.com"][src*="/embed"]{
  display: block !important;
  width: 100% !important;
  max-width: 660px !important;
  height: 450px !important;
  min-height: 450px !important;
  margin: 24px auto 18px !important;
  border: 0 !important;
  border-radius: 12px !important;
  overflow: hidden !important;
}

@media (max-width: 680px) {
  .is-post .post-body iframe[src*="embed.music.apple.com"],
.is-post .post-body iframe[src*="music.apple.com"][src*="/embed"]{
    height: 450px !important;
    min-height: 450px !important;
  }
}

/* Center every sidebar section heading and remove all decorative underlines. */
#sidebar-wrapper .widget-title,
#sidebar-wrapper .widget-title h2,
#sidebar-wrapper .widget-title h3,
#sidebar-wrapper .widget-title .title,
#sidebar-wrapper .title-wrap,
#sidebar-wrapper .title-wrap .title{
  display: block !important;
  width: 100% !important;
  margin-left: auto !important;
  margin-right: auto !important;
  padding-left: 0 !important;
  padding-right: 0 !important;
  border: 0 !important;
  border-bottom: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
  text-align: center !important;
  text-decoration: none !important;
}

#sidebar-wrapper .widget-title::before,
#sidebar-wrapper .widget-title::after,
#sidebar-wrapper .widget-title h2::before,
#sidebar-wrapper .widget-title h2::after,
#sidebar-wrapper .widget-title h3::before,
#sidebar-wrapper .widget-title h3::after,
#sidebar-wrapper .widget-title .title::before,
#sidebar-wrapper .widget-title .title::after,
#sidebar-wrapper .title-wrap::before,
#sidebar-wrapper .title-wrap::after,
#sidebar-wrapper .title-wrap .title::before,
#sidebar-wrapper .title-wrap .title::after{
  display: none !important;
  content: none !important;
  width: 0 !important;
  height: 0 !important;
  border: 0 !important;
  background: none !important;
  box-shadow: none !important;
}

/* The Welcome page has no sidebar and must not reserve a sidebar column. */
.ee-welcome-page #content-wrapper > .container{
  display: block !important;
  grid-template-columns: none !important;
  width: min(calc(100% - 40px), var(--ee-wide)) !important;
  max-width: var(--ee-wide) !important;
}

.ee-welcome-page #main-wrapper{
  display: block !important;
  width: 100% !important;
  max-width: none !important;
  margin: 0 !important;
}

.ee-welcome-page #sidebar-wrapper{
  display: none !important;
  width: 0 !important;
  min-width: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
}

/* Replace the theme's manual pager with an automatic scroll trigger. */
html.ee-year-archive #cryzen-pro-load-more-link,
html.ee-year-archive #blog-pager .loading,
html.ee-year-archive #blog-pager .no-more{
  display: none !important;
}

html.ee-year-archive #blog-pager{
  min-height: 48px;
}

html.ee-year-archive.ee-archive-loading #blog-pager::after{
  content: "Loading more articles...";
  display: block;
  padding: 16px 0;
  text-align: center;
  font-family: var(--title-font);
  font-size: 13px;
  font-weight: 500;
  letter-spacing: .04em;
  text-transform: uppercase;
  opacity: .65;
}

html.ee-year-archive.ee-archive-finished #blog-pager::after{
  content: "No more articles";
  display: block;
  padding: 16px 0;
  text-align: center;
  font-family: var(--title-font);
  font-size: 13px;
  font-weight: 500;
  letter-spacing: .04em;
  text-transform: uppercase;
  opacity: .65;
}


/* ==========================================================================
   ELECTRIC EYE GALLERY ENGINE — FINAL: STRUCTURE AND PRESENTATION
   Responsive grid and shared full-screen viewer styles.
   ========================================================================== */

:root{
  --ee-gallery-bg: #0a0a0a;
  --ee-gallery-panel: #151515;
  --ee-gallery-text: #f7f7f7;
  --ee-gallery-muted: #aaa;
  --ee-gallery-accent: #d82323;
  --ee-gallery-border: rgba(255,255,255,.14);
  --ee-gallery-control-bg: rgba(0,0,0,.58);
  --ee-gallery-control-hover: rgba(216,35,35,.92);
  --ee-gallery-radius: 4px;
  --ee-gallery-gap: 8px;
}

/* Album-review eye ratings are interface graphics, not photographs.
   v3.7 generates the ten-eye scale automatically from the manual Rating: N/10
   text. Legacy rows retain these classes as a safe gallery exclusion fallback. */
.is-post .post-body .ee-rating-row{
  display:flex!important;
  width:100%!important;
  max-width:100%!important;
  align-items:center!important;
  justify-content:center!important;
  flex-wrap:nowrap!important;
  gap:clamp(1px,.35vw,4px)!important;
  margin:.7em auto 1.2em!important;
  padding:0 6px!important;
  box-sizing:border-box!important;
  overflow:visible!important;
}

.is-post .post-body .ee-rating-eye-link,
.is-post .post-body .ee-rating-eye-slot{
  display:inline-flex!important;
  flex:0 1 42px!important;
  width:clamp(26px,7.5vw,42px)!important;
  max-width:42px!important;
  margin:0!important;
  padding:0!important;
  line-height:0!important;
  text-decoration:none!important;
}

.is-post .post-body img.ee-rating-eye{
  display:block!important;
  width:100%!important;
  max-width:42px!important;
  height:auto!important;
  margin:0!important;
  object-fit:contain!important;
}

.is-post .post-body img.ee-rating-eye--inactive{
  filter:grayscale(1) saturate(0)!important;
  opacity:.26!important;
}

@media (max-width:480px){
  .is-post .post-body .ee-rating-row{
    gap:1px!important;
    padding:0 2px!important;
  }

  .is-post .post-body .ee-rating-eye-link,
  .is-post .post-body .ee-rating-eye-slot{
    flex-basis:34px!important;
    width:clamp(24px,8.4vw,34px)!important;
    max-width:34px!important;
  }
}

/* Any future decorative image can be kept out of the automatic gallery by
   adding class="ee-no-gallery" or data-ee-no-gallery to it or its wrapper. */

/* Dormant until the JavaScript engine marks a sequence as ready. */
.ee-gallery{
  display: none;
  width: 100%;
  margin: 28px 0;
}

.ee-gallery.ee-gallery-ready{
  display: block;
}

.ee-gallery-grid{
  display: block;
  width: 100%;
}

.ee-photo-group{
  display: flex;
  align-items: flex-start;
  gap: var(--ee-gallery-gap);
  width: 100%;
  margin: 0 0 var(--ee-gallery-gap);
}

.ee-photo-group[hidden]{
  display: none !important;
}

.ee-gallery-item{
  position: relative;
  display: block;
  min-width: 0;
  overflow: hidden;
  background: #111;
  border: 0;
  border-radius: var(--ee-gallery-radius);
  cursor: zoom-in;
  line-height: 0;
  flex-grow: var(--ratio, 1.5);
  flex-shrink: 1;
  flex-basis: 0;
}

.ee-photo-group.ee-single .ee-gallery-item{
  flex: 1 1 100%;
}

.ee-gallery-item img{
  display: block !important;
  width: 100% !important;
  height: auto !important;
  max-width: none !important;
  margin: 0 !important;
  border: 0 !important;
  transition: transform .22s ease, filter .22s ease;
}

.ee-gallery-item:hover img,
.ee-gallery-item:focus-visible img{
  transform: scale(1.018);
  filter: brightness(.92);
}

.ee-gallery-item:focus-visible,
.ee-gallery-control:focus-visible,
.ee-gallery-thumb:focus-visible{
  outline: 2px solid var(--ee-gallery-accent);
  outline-offset: 2px;
}

.ee-gallery-more{
  display: flex;
  justify-content: center;
  margin: 16px 0 0;
}

.ee-gallery-more-button{
  min-height: 42px;
  padding: 0 18px;
  border: 1px solid var(--ee-gallery-border);
  border-radius: var(--ee-gallery-radius);
  background: #151515;
  color: var(--ee-gallery-text);
  font: 600 14px/1 var(--body-font);
  cursor: pointer;
}

.ee-gallery-more-button:hover,
.ee-gallery-more-button:focus-visible{
  border-color: var(--ee-gallery-accent);
  background: var(--ee-gallery-accent);
}


.ee-gallery-item[hidden],
.ee-gallery-more[hidden]{
  display: none !important;
}

html.ee-gallery-open,
html.ee-gallery-open body{
  overflow: hidden !important;
}

.ee-gallery-thumb-active{
  border-color: var(--ee-gallery-accent) !important;
  opacity: 1 !important;
}

/* Full-screen viewer shell. */
.ee-gallery-viewer[hidden]{
  display: none !important;
}

.ee-gallery-viewer{
  position: fixed;
  inset: 0;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  width: 100%;
  height: 100%;
  height: 100dvh;
  overflow: hidden;
  background: rgba(5,5,5,.985);
  color: var(--ee-gallery-text);
  z-index: 1000000;
  isolation: isolate;
}

.ee-gallery-viewer-topbar{
  position: relative;
  z-index: 3;
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 58px;
  padding: 8px 12px;
  border-bottom: 1px solid var(--ee-gallery-border);
  background: rgba(10,10,10,.94);
}

.ee-gallery-counter{
  min-width: 72px;
  color: var(--ee-gallery-text);
  font: 600 14px/1 var(--body-font);
  text-align: left;
}

.ee-gallery-toolbar{
  display: flex;
  align-items: center;
  gap: 6px;
}

.ee-gallery-control{
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 42px;
  height: 42px;
  padding: 0;
  border: 1px solid var(--ee-gallery-border);
  border-radius: 50%;
  background: var(--ee-gallery-control-bg);
  color: var(--ee-gallery-text);
  font: 700 23px/1 Arial, sans-serif;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

.ee-gallery-control:hover{
  border-color: transparent;
  background: var(--ee-gallery-control-hover);
}

.ee-gallery-stage{
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  padding: 14px 72px;
  touch-action: pan-y pinch-zoom;
  user-select: none;
}

.ee-gallery-image-wrap{
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  min-width: 0;
  min-height: 0;
}

.ee-gallery-image{
  display: block;
  width: auto;
  height: auto;
  max-width: 100%;
  max-height: 100%;
  object-fit: contain;
  margin: 0 !important;
  box-shadow: 0 8px 38px rgba(0,0,0,.38);
}

.ee-gallery-prev,
.ee-gallery-next{
  position: absolute;
  top: 50%;
  z-index: 2;
  transform: translateY(-50%);
}

.ee-gallery-prev{ left: 14px; }
.ee-gallery-next{ right: 14px; }

.ee-gallery-caption{
  position: absolute;
  left: 50%;
  bottom: 14px;
  max-width: min(760px, calc(100% - 150px));
  transform: translateX(-50%);
  padding: 8px 12px;
  border-radius: var(--ee-gallery-radius);
  background: rgba(0,0,0,.58);
  color: var(--ee-gallery-text);
  font: 400 14px/1.45 var(--body-font);
  text-align: center;
}

.ee-gallery-caption:empty{
  display: none;
}

.ee-gallery-filmstrip{
  position: relative;
  z-index: 3;
  display: flex;
  gap: 8px;
  min-height: 86px;
  overflow-x: auto;
  overflow-y: hidden;
  padding: 9px 12px 11px;
  border-top: 1px solid var(--ee-gallery-border);
  background: rgba(10,10,10,.96);
  scrollbar-width: thin;
  overscroll-behavior-inline: contain;
}

.ee-gallery-thumb{
  flex: 0 0 92px;
  height: 64px;
  padding: 0;
  overflow: hidden;
  border: 2px solid transparent;
  border-radius: 3px;
  background: var(--ee-gallery-panel);
  opacity: .62;
  cursor: pointer;
}

.ee-gallery-thumb:hover,
.ee-gallery-thumb[aria-current='true']{
  border-color: var(--ee-gallery-accent);
  opacity: 1;
}

.ee-gallery-thumb img{
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  margin: 0 !important;
}

html.ee-gallery-open,
html.ee-gallery-open body{
  overflow: hidden !important;
  overscroll-behavior: none;
}

@media (max-width: 800px) {

  .ee-gallery-stage{
    padding: 10px 48px;
  }

  .ee-gallery-prev{ left: 6px; }
  .ee-gallery-next{ right: 6px; }

  .ee-gallery-caption{
    max-width: calc(100% - 104px);
    bottom: 8px;
    font-size: 13px;
  }
}

@media (max-width: 520px) {

  .ee-gallery{
    margin: 22px 0;
  }

  .ee-photo-group{
    gap: 5px;
    margin-bottom: 5px;
    flex-wrap: wrap;
  }

  .ee-photo-group:not(.ee-single) .ee-gallery-item{
    flex-basis: calc(50% - 3px);
    flex-grow: 1;
  }

  .ee-photo-group.ee-triple .ee-gallery-item:last-child{
    flex-basis: 100%;
  }

  .ee-gallery-item{
    border-radius: 2px;
  }

  .ee-gallery-viewer-topbar{
    min-height: 52px;
    padding: 5px 8px;
  }

  .ee-gallery-control{
    width: 38px;
    height: 38px;
    font-size: 21px;
  }

  .ee-gallery-stage{
    padding: 6px 4px 8px;
  }

  .ee-gallery-prev,
.ee-gallery-next{
    top: auto;
    bottom: 14px;
    transform: none;
  }

  .ee-gallery-prev{ left: 10px; }
  .ee-gallery-next{ right: 10px; }

  .ee-gallery-caption{
    bottom: 16px;
    max-width: calc(100% - 112px);
    padding: 6px 8px;
  }

  .ee-gallery-filmstrip{
    min-height: 76px;
    padding: 7px 8px 9px;
  }

  .ee-gallery-thumb{
    flex-basis: 78px;
    height: 56px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .ee-gallery-item img{
    transition: none;
  }
}

/* ========================================================================== 
   ELECTRIC EYE THEME 2.1 — MOBILE NAVIGATION + SITEWIDE MOBILE FOUNDATION
   ========================================================================== */

/* The dedicated burger exists only for mobile/tablet. */
.ee-mobile-menu-button{
  display: none;
}

@media only screen and (max-width: 980px) {
  html,
body{
    max-width: 100%;
    overflow-x: hidden;
  }

  .main-header,
.header-header,
.header-inner,
.header-items{
    min-height: 62px;
  }

  .header-items > .flex-left{
    position: relative;
    display: flex !important;
    align-items: center;
    justify-content: flex-start;
    width: 100%;
    min-width: 0;
    padding: 0 max(12px, env(safe-area-inset-left)) 0 max(12px, env(safe-area-inset-left));
    gap: 10px;
  }

  /* Separate menu control: never overlays or captures the eye link. */
  .mobile-menu-toggle.ee-mobile-menu-button{
    position: relative !important;
    inset: auto !important;
    z-index: 8;
    flex: 0 0 44px;
    display: inline-flex !important;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    width: 44px !important;
    height: 44px !important;
    margin: 0;
    padding: 0;
    gap: 5px;
    border: 1px solid rgba(255,255,255,.24);
    border-radius: 8px;
    background: rgba(0,0,0,.32);
    color: #fff;
    cursor: pointer;
    -webkit-tap-highlight-color: transparent;
  }

  .mobile-menu-toggle.ee-mobile-menu-button::before,
.mobile-menu-toggle.ee-mobile-menu-button::after{
    content: none !important;
    display: none !important;
  }

  .ee-burger-line{
    display: block;
    width: 22px;
    height: 2px;
    border-radius: 2px;
    background: currentColor;
    transition: transform .2s ease, opacity .2s ease;
  }

  body.nav-active .ee-mobile-menu-button .ee-burger-line:nth-child(1){
    transform: translateY(7px) rotate(45deg);
  }
  body.nav-active .ee-mobile-menu-button .ee-burger-line:nth-child(2){
    opacity: 0;
  }
  body.nav-active .ee-mobile-menu-button .ee-burger-line:nth-child(3){
    transform: translateY(-7px) rotate(-45deg);
  }

  /* The animated eye is an independent Home link beside the burger. */
  #cryzen-mobile-logo-section{
    position: relative !important;
    inset: auto !important;
    left: auto !important;
    top: auto !important;
    z-index: 7;
    flex: 0 0 44px;
    width: 44px !important;
    height: 44px !important;
    margin: 0 !important;
    transform: none !important;
  }

  #cryzen-mobile-logo-section .widget,
#cryzen-mobile-logo-section .widget-content,
#cryzen-mobile-logo-section a{
    width: 44px;
    height: 44px;
  }

  #cryzen-mobile-logo-section a{
    position: relative;
    z-index: 2;
    display: flex !important;
    align-items: center;
    justify-content: center;
    pointer-events: auto !important;
    -webkit-tap-highlight-color: transparent;
  }

  #cryzen-mobile-logo-section img{
    width: 40px !important;
    height: 40px !important;
    max-width: 40px !important;
    max-height: 40px !important;
    pointer-events: none;
  }

  /* Prevent the old hidden/absolute toggle geometry from covering the logo. */
  #cryzen-mobile-logo-section .mobile-menu-toggle{
    display: none !important;
    pointer-events: none !important;
  }

  .ee-mobile-menu-button:focus-visible,
#cryzen-mobile-logo-section a:focus-visible{
    outline: 2px solid var(--ee-accent);
    outline-offset: 3px;
  }

  /* Safer touch targets in the slide-out navigation. */
  .cryzen-pro-mobile-menu ul li a,
.cryzen-pro-mobile-menu ul li .submenu-toggle,
.hide-cryzen-pro-mobile-menu{
    min-height: 44px;
  }

  /* Sitewide responsive media. */
  .post-body img,
.entry-content img,
.post-body video,
.entry-content video,
.post-body iframe,
.entry-content iframe,
.post-body embed,
.entry-content embed,
.post-body object,
.entry-content object{
    max-width: 100% !important;
  }

  .post-body iframe,
.entry-content iframe{
    width: 100% !important;
  }

  .responsive-video-wrap,
.video-responsive,
.post-video,
.separator{
    max-width: 100%;
  }

  /* Wide tables remain usable rather than forcing the whole page wider. */
  .post-body table,
.entry-content table{
    display: block;
    width: 100% !important;
    max-width: 100%;
    overflow-x: auto;
    overscroll-behavior-inline: contain;
    -webkit-overflow-scrolling: touch;
  }

  .post-body pre,
.entry-content pre,
.post-body code,
.entry-content code{
    max-width: 100%;
    overflow-wrap: anywhere;
  }

  /* Archive page: touch-first controls and a single compact card column. */
  #ee-archive-app,
#ee-archive-app *{
    box-sizing: border-box;
  }

  #ee-archive-app{
    width: 100%;
    max-width: 100%;
    overflow-x: clip;
  }

  #ee-archive-app .ee-a-shell{
    width: 100%;
    max-width: 100%;
    padding-left: 14px;
    padding-right: 14px;
  }

  #ee-archive-app .ee-a-tools{
    display: grid !important;
    grid-template-columns: 1fr 1fr;
    gap: 10px;
  }

  #ee-archive-app .ee-a-search-wrap{
    grid-column: 1 / -1;
    width: 100%;
  }

  #ee-archive-app .ee-a-input,
#ee-archive-app .ee-a-select,
#ee-archive-app .ee-a-reset,
#ee-archive-app .ee-a-more{
    min-height: 44px;
    font-size: 16px;
  }

  #ee-archive-app .ee-a-year-nav{
    display: flex;
    flex-wrap: nowrap;
    gap: 8px;
    width: 100%;
    overflow-x: auto;
    padding: 2px 0 8px;
    scroll-snap-type: x proximity;
    scrollbar-width: thin;
    -webkit-overflow-scrolling: touch;
  }

  #ee-archive-app .ee-a-year-nav > *{
    flex: 0 0 auto;
    min-height: 40px;
    scroll-snap-align: start;
  }

  #ee-archive-app .ee-a-latest,
#ee-archive-app .ee-a-grid{
    grid-template-columns: minmax(0, 1fr) !important;
  }

  #ee-archive-app .ee-a-grid{
    grid-auto-rows: auto !important;
  }

  #ee-archive-app .ee-a-card{
    min-width: 0;
    height: auto !important;
    min-height: 88px;
  }

  #ee-archive-app .ee-a-card-media{
    flex: 0 0 132px;
    width: 132px !important;
    height: 88px !important;
    aspect-ratio: 3 / 2;
  }

  #ee-archive-app .ee-a-card-copy{
    min-width: 0;
    padding: 10px 11px;
  }

  #ee-archive-app .ee-a-card-copy h3,
#ee-archive-app .ee-a-card-copy .ee-a-card-title{
    display: -webkit-box;
    overflow: hidden;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 3;
  }

  #ee-archive-app .ee-a-hero{
    min-height: min(76vh, 620px);
  }

  #ee-archive-app .ee-a-hero-content{
    padding-top: 34px;
    padding-bottom: 24px;
  }

  #ee-archive-app .ee-a-title{
    font-size: clamp(30px, 9vw, 48px);
    line-height: .98;
    overflow-wrap: anywhere;
  }

  #ee-archive-app .ee-a-hero-footer{
    display: flex;
    flex-direction: column;
    align-items: stretch;
    gap: 14px;
  }

  #ee-archive-app .ee-a-hero-controls{
    align-self: flex-end;
  }
}

@media only screen and (max-width: 480px) {
  .header-items > .flex-left{
    gap: 8px;
    padding-left: max(10px, env(safe-area-inset-left));
  }

  .mobile-menu-toggle.ee-mobile-menu-button,
#cryzen-mobile-logo-section,
#cryzen-mobile-logo-section .widget,
#cryzen-mobile-logo-section .widget-content,
#cryzen-mobile-logo-section a{
    width: 42px !important;
    height: 42px !important;
    flex-basis: 42px;
  }

  #cryzen-mobile-logo-section img{
    width: 38px !important;
    height: 38px !important;
  }

  #ee-archive-app .ee-a-tools{
    grid-template-columns: 1fr;
  }

  #ee-archive-app .ee-a-search-wrap{
    grid-column: auto;
  }

  #ee-archive-app .ee-a-card-media{
    flex-basis: 120px;
    width: 120px !important;
    height: 80px !important;
  }

  #ee-archive-app .ee-a-card{
    min-height: 80px;
  }

  #ee-archive-app .ee-a-card-copy{
    padding: 8px 9px;
  }
}

/* ========================================================================== 
   ELECTRIC EYE THEME 2.2 — TWO-ROW MOBILE HEADER
   Mobile only: controls occupy the top row; the full wordmark has its own row.
   Desktop (981px and above) is deliberately untouched.
   ========================================================================== */
@media only screen and (max-width: 980px) {
  .main-header,
.header-inner,
.header-header,
.header-items{
    min-height: 116px !important;
  }

  .header-header{
    position: relative;
    overflow: hidden;
    background: #151515 !important;
  }

  /* Dedicated, unobstructed wordmark row. */
  .header-header::before{
    content: "" !important;
    position: absolute !important;
    z-index: 1;
    left: max(14px, env(safe-area-inset-left)) !important;
    right: max(14px, env(safe-area-inset-right)) !important;
    top: auto !important;
    bottom: 8px !important;
    width: auto !important;
    height: 48px !important;
    transform: none !important;
    display: block !important;
    background-image: url(https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEibPxoLayjUc1fz4srbhiEK7pHdxEDu7kC9tdXPbUZ99FA8eW-mUJ6dhi9vfNTRuu2BY2HKENP5ghLKuR0SX7DBTQ5uaWPJs8qKff1GSUI1kzqQ-MWnNMPNuL5EMVCGjEUlyGNAiH1WasgwBlp9QvcCpzBhK4bHVTDZiKAQDgrmbwE0g2rk8TW5Wjwq92I/s16000/ElecEyeNewLog.1.jpeg) !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    background-size: contain !important;
    opacity: .94 !important;
    filter: none !important;
    pointer-events: none;
  }

  .header-items{
    position: relative;
    display: block !important;
    width: 100%;
  }

  /* Top control row: burger + home eye on the left. */
  .header-items > .flex-left{
    position: absolute !important;
    z-index: 4;
    left: max(10px, env(safe-area-inset-left));
    top: 7px;
    width: auto !important;
    min-height: 44px;
    padding: 0 !important;
    gap: 8px;
  }

  /* Search stays at the right edge of the same control row. */
  .header-items > .flex-right{
    position: absolute !important;
    z-index: 5;
    top: 7px;
    right: max(10px, env(safe-area-inset-right));
    display: flex !important;
    align-items: center;
    width: 44px !important;
    height: 44px !important;
    margin: 0 !important;
  }

  .header-items > .flex-right .main-toggle-wrap,
.header-items > .flex-right .show-search{
    width: 44px !important;
    height: 44px !important;
    min-width: 44px !important;
    min-height: 44px !important;
  }

  /* Ensure neither navigation control can drift over the wordmark row. */
  .mobile-menu-toggle.ee-mobile-menu-button,
#cryzen-mobile-logo-section,
#cryzen-mobile-logo-section .widget,
#cryzen-mobile-logo-section .widget-content,
#cryzen-mobile-logo-section a{
    position: relative !important;
    inset: auto !important;
    top: auto !important;
    left: auto !important;
    right: auto !important;
    bottom: auto !important;
    transform: none !important;
  }

  #main-search-wrap{
    z-index: 140;
  }
}

@media only screen and (max-width: 480px) {
  .main-header,
.header-inner,
.header-header,
.header-items{
    min-height: 108px !important;
  }

  .header-header::before{
    left: max(10px, env(safe-area-inset-left)) !important;
    right: max(10px, env(safe-area-inset-right)) !important;
    bottom: 7px !important;
    height: 43px !important;
  }

  .header-items > .flex-left,
.header-items > .flex-right{
    top: 6px;
  }
}


/* ========================================================================== 
   ELECTRIC EYE THEME 2.3 — FULL-WIDTH MOBILE WORDMARK
   Overrides the contained logo treatment in 2.2. Desktop remains untouched.
   ========================================================================== */
@media only screen and (max-width: 980px) {
  .header-header::before{
    left: 0 !important;
    right: 0 !important;
    bottom: 5px !important;
    width: 100% !important;
    height: 52px !important;
    background-position: center center !important;
    background-size: cover !important;
  }
}

@media only screen and (max-width: 480px) {
  .header-header::before{
    left: 0 !important;
    right: 0 !important;
    bottom: 4px !important;
    width: 100% !important;
    height: 48px !important;
    background-size: cover !important;
  }
}

/* =======================================================================
   ELECTRIC EYE – Fix YouTube embeds
   ======================================================================= */

.responsive-video-wrap{
    position:relative !important;
    display:block !important;
    width:100% !important;
    aspect-ratio:16/9 !important;
    overflow:hidden !important;
    margin:1.5em 0 !important;
    background:#000;
}

.responsive-video-wrap iframe{
    position:absolute !important;
    inset:0 !important;
    width:100% !important;
    height:100% !important;
    border:0 !important;
    display:block !important;
}

@media (max-width: 520px) {
}


.social-icons li{
  overflow: visible !important;
}

/* =========================================================
   ELECTRIC EYE — READ MORE RECOMMENDATION ENGINE
   ========================================================= */
#ee-read-more{
  position:relative;
  width:100%;
  margin:48px 0 0;
  padding:0;
}
#ee-read-more[hidden]{display:none!important}
#ee-read-more .ee-rm-heading{
  display:flex;
  align-items:center;
  gap:14px;
  margin:0 0 20px;
}
#ee-read-more .ee-rm-heading h2{
  flex:0 0 auto;
  font-family:var(--title-font);
  font-size:24px;
  line-height:1.15;
  color:var(--title-color);
  font-weight:700;
  margin:0;
}
#ee-read-more .ee-rm-heading:after{
  content:'';
  flex:1 1 auto;
  height:3px;
  background:var(--main-color);
}
#ee-read-more .ee-rm-grid{
  display:grid;
  grid-template-columns:repeat(3,minmax(0,1fr));
  gap:24px 20px;
}
#ee-read-more .ee-rm-card{
  min-width:0;
}
#ee-read-more .ee-rm-image{
  display:block;
  position:relative;
  width:100%;
  aspect-ratio:3/2;
  overflow:hidden;
  background:rgba(155,155,155,.08);
  margin:0 0 12px;
}
#ee-read-more .ee-rm-image img{
  display:block;
  width:100%;
  height:100%;
  object-fit:cover;
  object-position:center;
  transition:transform .25s ease,filter .25s ease;
}
#ee-read-more .ee-rm-card:hover .ee-rm-image img{
  transform:scale(1.015);
  filter:brightness(1.03);
}
#ee-read-more .ee-rm-category{
  display:block;
  width:fit-content;
  font-family:var(--body-font);
  font-size:11px;
  line-height:1;
  color:var(--main-color);
  font-weight:700;
  text-transform:uppercase;
  letter-spacing:.055em;
  margin:0 0 7px;
}
#ee-read-more .ee-rm-title{
  font-family:var(--title-font);
  font-size:17px;
  line-height:1.28;
  font-weight:700;
  margin:0;
}
#ee-read-more .ee-rm-title a{
  color:var(--post-title-color);
}
#ee-read-more .ee-rm-title a:hover{
  color:var(--post-title-hover-color);
}
#ee-read-more .ee-rm-date{
  display:block;
  font-family:var(--meta-font);
  font-size:12px;
  line-height:1.3;
  color:var(--meta-color);
  margin:7px 0 0;
}
@media screen and (max-width:900px){
  #ee-read-more .ee-rm-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
}
@media screen and (max-width:540px){
  #ee-read-more{margin-top:38px}
  #ee-read-more .ee-rm-heading h2{font-size:22px}
  #ee-read-more .ee-rm-grid{grid-template-columns:1fr;gap:26px}
  #ee-read-more .ee-rm-title{font-size:18px}
}


/* =========================================================
   ELECTRIC EYE — STATIC-PAGE MOBILE HERO TEXT SAFEGUARD
   Keeps every custom static-page hero inside the phone viewport.
   Desktop layouts remain unchanged.
   ========================================================= */
@media (max-width: 680px) {
  body.static_page .post-body [class*="hero"],
body.static_page .post-body [class*="Hero"]{
    max-width: 100% !important;
  }

  body.static_page .post-body [class*="hero"] [class*="content"],
body.static_page .post-body [class*="hero"] [class*="copy"],
body.static_page .post-body [class*="hero"] [class*="inner"],
body.static_page .post-body [class*="Hero"] [class*="content"],
body.static_page .post-body [class*="Hero"] [class*="copy"],
body.static_page .post-body [class*="Hero"] [class*="inner"]{
    width: 100% !important;
    min-width: 0 !important;
    max-width: 100% !important;
  }

  body.static_page .post-body [class*="hero"] h1,
body.static_page .post-body [class*="Hero"] h1,
body.static_page .post-body [class*="hero"] [class*="hero-title"],
body.static_page .post-body [class*="hero"] [class*="hero__title"],
body.static_page .post-body [class*="Hero"] [class*="title"]{
    display: block !important;
    width: 100% !important;
    min-width: 0 !important;
    max-width: 100% !important;
    height: auto !important;
    max-height: none !important;
    overflow: visible !important;
    white-space: normal !important;
    word-break: normal !important;
    overflow-wrap: break-word !important;
    hyphens: none !important;
    -webkit-hyphens: none !important;
    text-wrap: balance;
    font-size: clamp(2rem, 10.5vw, 3.55rem) !important;
    line-height: 1.04 !important;
    letter-spacing: -0.035em !important;
    padding-top: 0.04em !important;
    padding-bottom: 0.12em !important;
  }
}

@media (max-width: 380px) {
  body.static_page .post-body [class*="hero"] h1,
body.static_page .post-body [class*="Hero"] h1,
body.static_page .post-body [class*="hero"] [class*="hero-title"],
body.static_page .post-body [class*="hero"] [class*="hero__title"],
body.static_page .post-body [class*="Hero"] [class*="title"]{
    font-size: clamp(1.85rem, 10vw, 3rem) !important;
    line-height: 1.06 !important;
  }
}

