b:if.script:
//
(function () {
  "use strict";

  function norm(s) {
    return (s || "")
      .replace(/\s+/g, " ")
      .replace(/^\s+|\s+$/g, "");
  }

  function uniq(arr) {
    var out = [];
    var seen = {};
    for (var i = 0; i < arr.length; i++) {
      var k = norm(arr[i]);
      if (!k) continue;
      var key = k.toLowerCase();
      if (seen[key]) continue;
      seen[key] = true;
      out.push(k);
    }
    return out;
  }

  function getPostTitle() {
    var t = document.querySelector("h1.post-title, h3.post-title, .post-title, header h1, article h1");
    if (t && norm(t.textContent)) return norm(t.textContent);

    var dt = document.title || "";
    var parts = dt.split("|");
    if (parts.length && norm(parts[0])) return norm(parts[0]);
    return norm(dt);
  }

  function getLabelTexts() {
    var nodes = document.querySelectorAll(
      "a[rel='tag'], a[rel='category tag'], .post-labels a, .post-footer a[rel='tag'], a[dir][href*='/search/label/']"
    );

    var labels = [];
    for (var i = 0; i < nodes.length; i++) {
      labels.push(norm(nodes[i].textContent));
    }
    return uniq(labels);
  }

  function detectType(title) {
    var t = title.toLowerCase();

    if (t.indexOf("album review:") === 0) return "AlbumReview";
    if (t.indexOf("a conversation with") === 0) return "Interview";
    if (t.indexOf("catching up with") === 0) return "Interview";

    // Concert review pattern often contains "@"
    if (title.indexOf("@") > -1) return "ConcertReview";

    return "News";
  }

  function parseConcertBits(title, labels) {
    // Best effort extraction
    var out = {
      artist: "",
      venue: "",
      city: "",
      dateText: ""
    };

    // If title contains "@", parse "Artist @ Venue, City - Date" style
    if (title.indexOf("@") > -1) {
      var parts = title.split("@");
      out.artist = norm(parts[0]);

      var right = norm(parts.slice(1).join("@"));
      // Try split by " - " first, then comma patterns
      var dashParts = right.split(" - ");
      var leftSide = norm(dashParts[0]);
      out.dateText = dashParts.length > 1 ? norm(dashParts.slice(1).join(" - ")) : "";

      // "Venue, City"
      var commaParts = leftSide.split(",");
      out.venue = norm(commaParts[0]);
      out.city = commaParts.length > 1 ? norm(commaParts.slice(1).join(",")) : "";
    }

    // Use labels to improve city and venue if missing or ambiguous
    // City list can grow without code changes by adding new city labels
    var cityCandidates = [];
    for (var i = 0; i < labels.length; i++) {
      var l = labels[i];
      // Heuristic: if a label is a known city label, it should be used as city
      // Add cities by simply using them as labels on posts.
      if (l && l.length <= 40) cityCandidates.push(l);
    }

    // If a city label exists, prefer it over parsing
    // We pick the first label that matches one of your known city names
    var knownCities = [
      "Paris","London","Birmingham","Marseille",
      "New York","Los Angeles","San Francisco","San Diego","San Luis Obispo",
      "Uncasville"
    ];

    function inKnownCities(x) {
      var xl = (x || "").toLowerCase();
      for (var j = 0; j < knownCities.length; j++) {
        if (xl === knownCities[j].toLowerCase()) return true;
      }
      return false;
    }

    for (var c = 0; c < labels.length; c++) {
      if (inKnownCities(labels[c])) {
        out.city = labels[c];
        break;
      }
    }

    // Venue: pick a non city label that looks like a venue
    // If you label venues consistently, this becomes very accurate.
    if (!out.venue) {
      for (var v = 0; v < labels.length; v++) {
        if (!inKnownCities(labels[v])) {
          // Ignore generic labels you might use as categories
          var ll = labels[v].toLowerCase();
          if (ll === "review" || ll === "album review" || ll === "interview" || ll === "news") continue;
          out.venue = labels[v];
          break;
        }
      }
    }

    // Casino de Paris is not a problem:
    // city is taken from the city label, venue can contain city text safely.

    return out;
  }

  function ensureMeta(name, content) {
    content = norm(content);
    if (!content) return;

    var m = document.querySelector("meta[name='" + name + "']");
    if (!m) {
      m = document.createElement("meta");
      m.setAttribute("name", name);
      document.head.appendChild(m);
    }
    m.setAttribute("content", content);
  }

  function addArticleTags(labels) {
    // Adds <meta property="article:tag" content="Label">
    // Multiple tags are allowed.
    for (var i = 0; i < labels.length; i++) {
      var l = norm(labels[i]);
      if (!l) continue;

      var existing = document.querySelector("meta[property='article:tag'][content='" + l.replace(/"/g, "&quot;") + "']");
      if (existing) continue;

      var m = document.createElement("meta");
      m.setAttribute("property", "article:tag");
      m.setAttribute("content", l);
      document.head.appendChild(m);
    }
  }

  function injectJsonLdArticle(payload) {
    // Remove previous injected version if any
    var old = document.getElementById("ee-jsonld-article");
    if (old && old.parentNode) old.parentNode.removeChild(old);

    var s = document.createElement("script");
    s.type = "application/ld+json";
    s.id = "ee-jsonld-article";
    s.textContent = JSON.stringify(payload);
    document.head.appendChild(s);
  }

  function setImageAlts(title, type, bits) {
    // Only touches images inside the post body, not your whole theme.
    var root = document.querySelector(".post-body, .post-content, article, .post");
    if (!root) return;

    var imgs = root.querySelectorAll("img");
    if (!imgs || !imgs.length) return;

    var base = title;
    if (type === "ConcertReview") {
      var extra = [];
      if (bits.artist) extra.push(bits.artist);
      if (bits.venue) extra.push(bits.venue);
      if (bits.city) extra.push(bits.city);
      base = uniq(extra).join(", ") || title;
    }

    for (var i = 0; i < imgs.length; i++) {
      var img = imgs[i];

      // Skip tiny UI icons and tracking like 1x1
      var w = parseInt(img.getAttribute("width") || "0", 10);
      var h = parseInt(img.getAttribute("height") || "0", 10);
      if ((w && w <= 40) || (h && h <= 40)) continue;

      var alt = norm(img.getAttribute("alt"));
      var ttl = norm(img.getAttribute("title"));

      if (!alt) img.setAttribute("alt", base);
      if (!ttl) img.setAttribute("title", base);
    }
  }

  function run() {
    var title = getPostTitle();
    var labels = getLabelTexts();
    var type = detectType(title);

    var bits = parseConcertBits(title, labels);

    // Build keywords
    var keywords = [];
    keywords.push(title);

    for (var i = 0; i < labels.length; i++) keywords.push(labels[i]);

    if (type === "ConcertReview") {
      if (bits.artist) keywords.push(bits.artist);
      if (bits.venue) keywords.push(bits.venue);
      if (bits.city) keywords.push(bits.city);
      if (bits.dateText) keywords.push(bits.dateText);
    }

    keywords = uniq(keywords);

    ensureMeta("keywords", keywords.join(", "));
    addArticleTags(labels);

    // JSON-LD Article
    var url = location.href;
    var payload = {
      "@context": "https://schema.org",
      "@type": "Article",
      "mainEntityOfPage": { "@type": "WebPage", "@id": url },
      "headline": title,
      "keywords": keywords.join(", "),
      "about": labels.slice(0, 25),
      "url": url
    };

    // If your theme exposes a post image as og:image, reuse it
    var ogImg = document.querySelector("meta[property='og:image']");
    if (ogImg && norm(ogImg.getAttribute("content"))) {
      payload.image = [ norm(ogImg.getAttribute("content")) ];
    }

    // injectJsonLdArticle(payload);

    // Image alt/title enrichment, contextual per post
    setImageAlts(title, type, bits);
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", run);
  } else {
    run();
  }
})();
//

