b:if.script:
//
(function(){
  "use strict";

  function normalizeLegacyProse(){
    var root = document.querySelector(".is-post .post-body");
    if(!root) return;

    var protectedSelector = [
      ".ee-gallery","[data-ee-gallery]",".ee-safe-affiliate",".ee-affiliate-v6",
      ".ee-related-posts",".related-posts",".responsive-video-wrap",".AppleMusicEmbed",
      ".separator-ad",".ad-container","ins.adsbygoogle",
      "figure","figcaption","table","thead","tbody","tfoot","tr","td","th",
      "ul","ol","li","blockquote","pre","form","nav","aside","a","button"
    ].join(",");

    var protectedTokenPattern = /(?:^|[-_\s])(gallery|caption|credit|photo|media|embed|widget|affiliate|related|share|social|author|byline|meta|advert|ads?|setlist)(?:$|[-_\s])/i;

    function cleanText(value){
      return String(value || "").replace(/\u00a0/g," ").replace(/\s+/g," ").trim();
    }

    function hasProtectedIdentity(node){
      if(!node || node.nodeType !== 1) return false;
      var identity = [node.id || "", node.className || ""].join(" ");
      return protectedTokenPattern.test(identity);
    }

    function isInsideProtectedStructure(node){
      if(!node || node.nodeType !== 1) return true;
      if(node.matches && node.matches(protectedSelector)) return true;

      var ancestor = node.parentElement;
      var guard = 0;
      while(ancestor && ancestor !== root && guard < 12){
        guard += 1;
        if(ancestor.matches && ancestor.matches(protectedSelector)) return true;
        if(hasProtectedIdentity(ancestor)) return true;
        ancestor = ancestor.parentElement;
      }
      return false;
    }

    function effectiveAlignment(node){
      var inlineAlign = String(node.style && node.style.textAlign || "").toLowerCase();
      if(inlineAlign) return inlineAlign;
      try{
        return String(window.getComputedStyle(node).textAlign || "").toLowerCase();
      }catch(error){
        return "";
      }
    }

    function isCenterOrRight(node){
      var alignment = effectiveAlignment(node);
      return alignment === "center" || alignment === "right" || alignment === "end";
    }

    /*
     * Some older posts have a paragraph written directly into .post-body:
     *
     *   text + <b>...</b> + text + <span>...</span>
     *
     * followed by normal <p> elements. Group only contiguous runs made solely
     * of text and harmless inline formatting elements. This restores the same
     * copy width/alignment without touching stored Blogger HTML.
     */
    (function wrapOrphanInlineRuns(){
      var inlineTags = {
        A:1, ABBR:1, B:1, BDI:1, BDO:1, CITE:1, CODE:1, DEL:1, EM:1,
        FONT:1, I:1, INS:1, KBD:1, MARK:1, Q:1, S:1, SAMP:1, SMALL:1,
        SPAN:1, STRIKE:1, STRONG:1, SUB:1, SUP:1, TIME:1, U:1, VAR:1, WBR:1
      };

      function eligible(node){
        if(!node) return false;

        if(node.nodeType === 3){
          return true;
        }

        if(node.nodeType !== 1) return false;
        return !!inlineTags[node.tagName];
      }

      var nodes = Array.prototype.slice.call(root.childNodes);
      var run = [];

      function flush(){
        if(!run.length) return;

        var prose = run.map(function(node){
          return node.textContent || "";
        }).join("").replace(/\s+/g," ").trim();

        if(prose){
          var wrapper = document.createElement("div");
          wrapper.className = "ee-legacy-prose-block";
          root.insertBefore(wrapper,run[0]);

          run.forEach(function(node){
            wrapper.appendChild(node);
          });
        }

        run = [];
      }

      nodes.forEach(function(node){
        if(eligible(node)){
          run.push(node);
        }else{
          flush();
        }
      });

      flush();
    })();

    /* Direct-child legacy prose: retained from v1.3. */
    Array.prototype.forEach.call(root.children,function(block){
      if(!block || block.tagName !== "DIV") return;

      if(
        block.classList.contains("ee-safe-affiliate") ||
        block.classList.contains("responsive-video-wrap") ||
        block.classList.contains("AppleMusicEmbed") ||
        block.hasAttribute("data-ee-gallery")
      ){
        return;
      }

      if(block.classList.contains("ee-legacy-prose-block")) return;

      var className = String(block.className || "").toLowerCase();

      if(
        className.indexOf("gallery") !== -1 ||
        className.indexOf("embed") !== -1 ||
        className.indexOf("widget") !== -1 ||
        className.indexOf("affiliate") !== -1 ||
        className.indexOf("ad-") !== -1
      ){
        return;
      }

      if(block.querySelector(
        "p,div,img,picture,figure,iframe,video,audio,table,ul,ol,blockquote," +
        "pre,script,style,form,canvas,svg,hr,h1,h2,h3,h4,h5,h6"
      )){
        return;
      }

      var prose = cleanText(block.textContent);
      if(!prose) return;
      if(isCenterOrRight(block)) return;

      block.classList.add("ee-legacy-prose-block");
    });

    /*
     * v1.4: some Blogger posts wrap hero media, prose, setlist material and the
     * gallery in one large outer DIV. Do not normalize that mixed wrapper.
     * Instead, descend a short distance and normalize only leaf DIVs that are
     * structurally indistinguishable from paragraphs.
     *
     * Guardrails:
     * - maximum four DIV levels below .post-body;
     * - meaningful prose (>= 40 chars and >= 7 words);
     * - no block/media descendants;
     * - not centred/right-aligned, hidden, or ARIA-hidden;
     * - not inside known gallery/media/affiliate/ad/navigation structures;
     * - no gallery/credit/widget/etc. identity in the candidate itself.
     */
    (function normalizeNestedLeafDivProse(){
      var candidates = Array.prototype.slice.call(root.querySelectorAll("div"));

      candidates.forEach(function(block){
        if(!block || block.parentElement === root) return;
        if(block.classList.contains("ee-legacy-prose-block")) return;
        if(block.hidden || block.getAttribute("aria-hidden") === "true") return;
        if(block.closest("[contenteditable='true']")) return;
        if(hasProtectedIdentity(block) || isInsideProtectedStructure(block)) return;
        if(isCenterOrRight(block)) return;

        var depth = 0;
        var parent = block.parentElement;
        while(parent && parent !== root && depth <= 4){
          depth += 1;
          parent = parent.parentElement;
        }
        if(parent !== root || depth > 4) return;

        if(block.querySelector(
          "p,div,img,picture,figure,figcaption,iframe,video,audio,object,embed," +
          "table,ul,ol,li,blockquote,pre,script,style,form,canvas,svg,hr," +
          "h1,h2,h3,h4,h5,h6,button,input,select,textarea"
        )){
          return;
        }

        var prose = cleanText(block.textContent);
        if(prose.length < 40) return;

        var words = prose.split(/\s+/).filter(Boolean);
        if(words.length < 7) return;

        /* Utility/link rows are not prose, even when left aligned. */
        var links = Array.prototype.slice.call(block.querySelectorAll("a[href]"));
        if(links.length){
          var linkedText = cleanText(links.map(function(link){
            return link.textContent || "";
          }).join(" "));
          if(linkedText && linkedText.length >= Math.max(24,Math.floor(prose.length * 0.8))){
            return;
          }
        }

        block.classList.add("ee-legacy-prose-block");
        block.setAttribute("data-ee-legacy-prose-nested","1");
      });
    })();

    /*
     * Recognize old blank-line DIVs even when Blogger wrapped the <br> in
     * harmless inline markup, e.g.:
     *
     *   <div><span><br /></span></div>
     *
     * Hide them only when both neighboring meaningful blocks are prose.
     * Therefore spacing around images, galleries, embeds and modules remains.
     */
    function isBreakOnlySpacer(node){
      if(!node || node.nodeType !== 1 || node.tagName !== "DIV") return false;
      if(node.classList.contains("separator")) return false;
      if(cleanText(node.textContent)) return false;
      if(!node.querySelector("br")) return false;

      var allowed = {
        BR:1, SPAN:1, FONT:1, B:1, STRONG:1, I:1, EM:1, U:1,
        S:1, STRIKE:1, SMALL:1, SUB:1, SUP:1
      };

      var descendants = Array.prototype.slice.call(node.querySelectorAll("*"));
      return descendants.length > 0 && descendants.every(function(child){
        return !!allowed[child.tagName];
      });
    }

    function previousMeaningful(node){
      var prev = node.previousElementSibling;
      while(prev && isBreakOnlySpacer(prev)){
        prev = prev.previousElementSibling;
      }
      return prev;
    }

    function nextMeaningful(node){
      var next = node.nextElementSibling;
      while(next && isBreakOnlySpacer(next)){
        next = next.nextElementSibling;
      }
      return next;
    }

    function isProse(node){
      if(!node) return false;
      if(node.classList && node.classList.contains("ee-legacy-prose-block")) return true;
      if(node.tagName === "P") return true;

      if(node.tagName === "DIV" && !node.classList.contains("separator")){
        var hasMediaOrBlocks = node.querySelector(
          "img,picture,figure,iframe,video,audio,table,ul,ol,blockquote," +
          "pre,script,style,form,canvas,svg,hr,h1,h2,h3,h4,h5,h6"
        );
        var prose = cleanText(node.textContent);
        return !!prose && !hasMediaOrBlocks;
      }

      return false;
    }

    Array.prototype.forEach.call(root.children,function(block){
      if(!isBreakOnlySpacer(block)) return;

      var prev = previousMeaningful(block);
      var next = nextMeaningful(block);

      if(isProse(prev) && isProse(next)){
        block.style.display = "none";
        block.setAttribute("data-ee-legacy-spacer-hidden","1");
      }
    });
  }

  if(document.readyState === "loading"){
    document.addEventListener("DOMContentLoaded",normalizeLegacyProse,{once:true});
  }else{
    normalizeLegacyProse();
  }
})();
