(function(){
  "use strict";

  document.documentElement.classList.add("ee-custom-search");

  var CONFIG = {
    batchSize: 4,
    feedPageSize: 150,
    feedConcurrency: 6,
    cacheTtl: 30 * 60 * 1000,
    cachePrefix: "eeCustomSearchV20:",
    indexCacheKey: "eeCustomSearchIndexV20",
    indexCacheTtl: 24 * 60 * 60 * 1000,
    fallbackImage: "https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEgGiKvWgyh4R4WdEQquwfVGfhuvFwkT_JNbUi4JQ5UPBYW59DyqvjOzNJhU5YBKlN0XDKhJqpS1TcdMpgWuwZ4QxWfcVyNxLXUH5-59mMB3TBbCUUhvqyJh8tneuotGERr3QDEfxy_RLFfalF6APFop7pouUkyR5u8YJlyG9JTy6p1tOAB2g4BQfxtu6Hk/s1200/HeroReplace.jpg",
  };

  function norm(value){
    return String(value || "")
      .toLowerCase()
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g,"")
      .replace(/[’‘']/g," ")
      .replace(/&amp;/g," and ")
      .replace(/[^a-z0-9]+/g," ")
      .replace(/\s+/g," ")
      .trim();
  }

  function tokens(value){
    return norm(value).split(" ").filter(Boolean);
  }

  function unique(values){
    var seen = Object.create(null);
    var output = [];

    values.forEach(function(value){
      var key = String(value || "").trim();
      if(!key) return;

      var normalized = norm(key);
      if(!normalized || seen[normalized]) return;

      seen[normalized] = true;
      output.push(key);
    });

    return output;
  }

  function containsPhrase(haystack,needle){
    var h = norm(haystack);
    var n = norm(needle);

    if(!h || !n) return false;

    return (" " + h + " ").indexOf(" " + n + " ") !== -1;
  }

  function containsAllTerms(haystack,terms){
    var set = new Set(tokens(haystack));
    return terms.length > 0 && terms.every(function(term){
      return set.has(term);
    });
  }

  function titleCase(value){
    return String(value || "")
      .toLowerCase()
      .replace(/\b([a-z])/g,function(match){
        return match.toUpperCase();
      });
  }

  function canonical(url){
    try{
      var u = new URL(url,location.origin);
      return (u.origin + u.pathname).replace(/\/$/,"");
    }catch(error){
      return String(url || "").split(/[?#]/)[0].replace(/\/$/,"");
    }
  }

  function alternateLink(entry){
    var links = entry.link || [];

    for(var i=0;i<links.length;i++){
      if(links[i].rel === "alternate" && links[i].href){
        return links[i].href;
      }
    }

    return "";
  }

  function resizeImage(url){
    var value = String(url || "");
    if(!value) return CONFIG.fallbackImage;

    if(/blogger\.googleusercontent\.com|(?:\d+\.)?bp\.blogspot\.com/i.test(value)){
      return value
        .replace(/\/s\d+(?:-[^/]+)?\//i,"/w900-h560-p-k-no-nu/")
        .replace(/\/w\d+-h\d+(?:-[^/]+)?\//i,"/w900-h560-p-k-no-nu/")
        .replace(/=s\d+(?:-[^?&]+)?/i,"=w900-h560-p-k-no-nu")
        .replace(/=w\d+-h\d+(?:-[^?&]+)?/i,"=w900-h560-p-k-no-nu");
    }

    return value;
  }

  function entryImage(entry){
    if(entry.media$thumbnail && entry.media$thumbnail.url){
      return resizeImage(entry.media$thumbnail.url);
    }

    return CONFIG.fallbackImage;
  }

  function parseEntry(entry){
    var labels = (entry.category || []).map(function(item){
      return item.term || "";
    }).filter(Boolean);

    return {
      title: entry.title && entry.title.$t || "Untitled",
      url: canonical(alternateLink(entry)),
      published: entry.published && entry.published.$t || "",
      updated: entry.updated && entry.updated.$t || "",
      labels: labels,
      image: entryImage(entry)
    };
  }

  function entriesFromFeed(data){
    return data && data.feed && data.feed.entry || [];
  }


  function jsonp(path,params,useFields){
    return new Promise(function(resolve,reject){
      var callback =
        "eeSearchFeed_" +
        Date.now() +
        "_" +
        Math.floor(Math.random()*1000000);

      var script = document.createElement("script");
      var settled = false;

      var timer = window.setTimeout(function(){
        cleanup();
        reject(new Error("Search feed timed out"));
      },10000);

      function cleanup(){
        if(settled) return;
        settled = true;
        window.clearTimeout(timer);

        try{
          delete window[callback];
        }catch(error){
          window[callback] = undefined;
        }

        if(script.parentNode){
          script.parentNode.removeChild(script);
        }
      }

      window[callback] = function(data){
        cleanup();
        resolve(data || {});
      };

      script.onerror = function(){
        cleanup();
        reject(new Error("Search feed request failed"));
      };

      var query = [
        "alt=json-in-script",
        "callback=" + encodeURIComponent(callback)
      ];

      Object.keys(params || {}).forEach(function(key){
        if(params[key] === undefined || params[key] === null || params[key] === "") return;
        query.push(
          encodeURIComponent(key) +
          "=" +
          encodeURIComponent(String(params[key]))
        );
      });

      script.src = path + "?" + query.join("&");
      document.head.appendChild(script);
    });
  }

  /*
   * COMPLETE BLOGGER FEED WALKER
   *
   * Earlier versions tried to infer archive completeness from JSON
   * partial-response metadata. Electric Eye's own successful backup script
   * uses a simpler, proven method: request a feed page, advance start-index
   * by the number actually returned, and stop only when Blogger returns no
   * new entries.
   *
   * We use /feeds/posts/summary rather than /default so the browser does not
   * download complete article bodies while building the title/label index.
   */
  async function fetchSequentialFrom(path,baseParams,initialEntries,startIndex){
    var allEntries = [];
    var seenUrls = new Set();

    (initialEntries || []).forEach(function(raw){
      var url = canonical(alternateLink(raw));
      if(!url || seenUrls.has(url)) return;
      seenUrls.add(url);
      allEntries.push(raw);
    });

    var safety = 0;

    while(safety < 100){
      safety += 1;

      var params = Object.assign({},baseParams,{
        "max-results":500,
        "start-index":startIndex
      });

      var page = await jsonp(path,params,false);
      var batch = entriesFromFeed(page);

      if(!batch.length) break;

      var freshCount = 0;

      batch.forEach(function(raw){
        var url = canonical(alternateLink(raw));
        if(!url || seenUrls.has(url)) return;

        seenUrls.add(url);
        allEntries.push(raw);
        freshCount += 1;
      });

      if(!freshCount) break;
      startIndex += batch.length;
    }

    if(safety >= 100){
      throw new Error("Blogger feed pagination safety limit reached");
    }

    return allEntries;
  }

  async function fetchAll(path,baseParams){
    /*
     * v1.6 FAST + SAFE PAGINATION
     *
     * Do not trust Blogger's reported total result count. That was the v1.5
     * regression: an incomplete metadata set could be accepted as complete,
     * so real title matches disappeared before ranking even began.
     *
     * Instead:
     *   1. Fetch page 1.
     *   2. Probe the immediately following page.
     *   3. If more data exists, fetch later pages in parallel waves.
     *   4. Stop only after an actually empty continuation page is observed.
     */
    var first = await jsonp(
      path,
      Object.assign({},baseParams,{
        "max-results":500,
        "start-index":1
      }),
      false
    );

    var firstBatch = entriesFromFeed(first);
    if(!firstBatch.length) return [];

    var pageSize = firstBatch.length;
    var collected = firstBatch.slice();
    var seenUrls = new Set();

    firstBatch.forEach(function(raw){
      var url = canonical(alternateLink(raw));
      if(url) seenUrls.add(url);
    });

    var secondStart = 1 + pageSize;
    var second = await jsonp(
      path,
      Object.assign({},baseParams,{
        "max-results":500,
        "start-index":secondStart
      }),
      false
    );

    var secondBatch = entriesFromFeed(second);

    if(!secondBatch.length){
      return collected;
    }

    if(secondBatch.length !== pageSize){
      return fetchSequentialFrom(path,baseParams,[],1);
    }

    secondBatch.forEach(function(raw){
      var url = canonical(alternateLink(raw));
      if(!url || seenUrls.has(url)) return;
      seenUrls.add(url);
      collected.push(raw);
    });

    var nextStart = secondStart + pageSize;
    var waves = 0;

    while(waves < 100){
      waves += 1;

      var starts = [];
      for(var i=0;i<CONFIG.feedConcurrency;i++){
        starts.push(nextStart + (i * pageSize));
      }

      var pages = await Promise.all(
        starts.map(function(startIndex){
          return jsonp(
            path,
            Object.assign({},baseParams,{
              "max-results":500,
              "start-index":startIndex
            }),
            false
          ).then(function(page){
            return {
              start:startIndex,
              batch:entriesFromFeed(page)
            };
          });
        })
      );

      pages.sort(function(a,b){
        return a.start - b.start;
      });

      var reachedEnd = false;

      for(var p=0;p<pages.length;p++){
        var batch = pages[p].batch;

        if(!batch.length){
          reachedEnd = true;
          break;
        }

        if(batch.length !== pageSize){
          return fetchSequentialFrom(path,baseParams,[],1);
        }

        batch.forEach(function(raw){
          var url = canonical(alternateLink(raw));
          if(!url || seenUrls.has(url)) return;
          seenUrls.add(url);
          collected.push(raw);
        });
      }

      if(reachedEnd){
        return collected;
      }

      nextStart += CONFIG.feedConcurrency * pageSize;
    }

    throw new Error("Blogger feed parallel pagination safety limit reached");
  }

  function compactItem(item){
    return {
      t:item.title,
      u:item.url,
      p:item.published,
      d:item.updated,
      l:item.labels,
      i:item.image
    };
  }

  function reviveItem(raw){
    return {
      title:raw.t || "",
      url:canonical(raw.u || ""),
      published:raw.p || "",
      updated:raw.d || "",
      labels:Array.isArray(raw.l) ? raw.l : [],
      image:raw.i || CONFIG.fallbackImage
    };
  }

  function latestIndexItem(items){
    if(!items || !items.length) return null;

    return items.reduce(function(latest,item){
      if(!latest) return item;
      return (Date.parse(item.updated) || 0) > (Date.parse(latest.updated) || 0)
        ? item
        : latest;
    },null);
  }

  function readIndexCache(){
    var stores = [localStorage,sessionStorage];

    for(var s=0;s<stores.length;s++){
      try{
        var hit = JSON.parse(
          stores[s].getItem(CONFIG.indexCacheKey) || "null"
        );

        if(
          hit &&
          Date.now() - hit.time < CONFIG.indexCacheTtl &&
          Array.isArray(hit.items)
        ){
          return {
            time:hit.time,
            latestUrl:hit.latestUrl || "",
            latestUpdated:hit.latestUpdated || "",
            items:hit.items.map(reviveItem)
          };
        }
      }catch(error){}
    }

    return null;
  }

  function writeIndexCache(items){
    var latest = latestIndexItem(items);

    var payload = JSON.stringify({
      time:Date.now(),
      latestUrl:latest ? latest.url : "",
      latestUpdated:latest ? latest.updated : "",
      items:items.map(compactItem)
    });

    try{
      localStorage.setItem(CONFIG.indexCacheKey,payload);
      return;
    }catch(error){}

    try{
      sessionStorage.setItem(CONFIG.indexCacheKey,payload);
    }catch(error){}
  }

  async function newestFeedItem(){
    var page = await jsonp(
      "/feeds/posts/summary",
      {
        "max-results":1,
        "start-index":1,
        "orderby":"updated"
      },
      false
    );

    var entries = entriesFromFeed(page);
    return entries.length ? parseEntry(entries[0]) : null;
  }

  async function loadCompleteIndex(){
    var cached = readIndexCache();

    if(cached){
      try{
        /*
         * localStorage persists across tabs and browser sessions. Validate it
         * with a one-entry feed request so a newly published Electric Eye post
         * appears immediately instead of waiting for the 24-hour cache TTL.
         */
        var newest = await newestFeedItem();

        if(
          newest &&
          newest.url === cached.latestUrl &&
          newest.updated === cached.latestUpdated
        ){
          return cached.items;
        }
      }catch(error){
        /*
         * If the tiny freshness check fails, prefer the cached complete index
         * to forcing the visitor through a full rebuild.
         */
        return cached.items;
      }
    }

    var rawEntries = await fetchAll(
      "/feeds/posts/summary",
      {}
    );

    var byUrl = new Map();

    rawEntries.forEach(function(raw){
      var item = parseEntry(raw);
      if(!item.url) return;
      if(!byUrl.has(item.url)) byUrl.set(item.url,item);
    });

    var items = Array.from(byUrl.values());

    if(!items.length){
      throw new Error("Electric Eye search index is empty");
    }

    writeIndexCache(items);
    return items;
  }

  function titleMatches(item,query){
    var queryTerms = tokens(query);

    return (
      containsPhrase(item.title,query) ||
      containsAllTerms(item.title,queryTerms)
    );
  }

  function labelMatches(item,query){
    var queryTerms = tokens(query);

    return item.labels.some(function(label){
      return (
        containsPhrase(label,query) ||
        containsAllTerms(label,queryTerms)
      );
    });
  }


  function cacheKey(query){
    return CONFIG.cachePrefix + norm(query);
  }

  function readCache(query){
    try{
      var hit = JSON.parse(sessionStorage.getItem(cacheKey(query)) || "null");

      if(
        hit &&
        Date.now() - hit.time < CONFIG.cacheTtl &&
        Array.isArray(hit.items)
      ){
        return hit.items;
      }
    }catch(error){}

    return null;
  }

  function writeCache(query,items){
    try{
      sessionStorage.setItem(
        cacheKey(query),
        JSON.stringify({
          time:Date.now(),
          items:items
        })
      );
    }catch(error){}
  }

  function mergeIndexItems(baseItems,extraEntries){
    var byUrl = new Map();

    baseItems.forEach(function(item){
      if(item.url) byUrl.set(item.url,item);
    });

    (extraEntries || []).forEach(function(raw){
      var item = parseEntry(raw);
      if(item.url && !byUrl.has(item.url)){
        byUrl.set(item.url,item);
      }
    });

    return Array.from(byUrl.values());
  }

  async function directLabelEntries(query){
    var variants = unique([
      String(query || "").trim(),
      titleCase(query)
    ]);

    var groups = await Promise.all(
      variants.map(function(label){
        if(!label) return Promise.resolve([]);

        return fetchAll(
          "/feeds/posts/summary/-/" + encodeURIComponent(label),
          {}
        ).catch(function(){
          return [];
        });
      })
    );

    var byUrl = new Map();

    groups.forEach(function(entries){
      entries.forEach(function(raw){
        var item = parseEntry(raw);
        if(item.url && !byUrl.has(item.url)){
          byUrl.set(item.url,raw);
        }
      });
    });

    return Array.from(byUrl.values());
  }

  async function search(query){
    var cached = readCache(query);
    if(cached) return cached;

    /*
     * TARGETED-FIRST MODE:
     * Ask Blogger for this query before touching the complete ~archive index.
     * For ordinary searches this avoids downloading/validating the entire
     * search index and should return a much smaller candidate set.
     */
    var targetedEntries = await fetchAll(
      "/feeds/posts/summary",
      {q:query}
    ).catch(function(){
      return [];
    });

    var targetedItems = [];
    var targetedByUrl = new Map();

    targetedEntries.forEach(function(raw){
      var item = parseEntry(raw);
      if(!item.url || targetedByUrl.has(item.url)) return;

      if(titleMatches(item,query)){
        item.tier = 30;
        item.reason = "Title match";
      }else if(labelMatches(item,query)){
        item.tier = 20;
        item.reason = "Label match";
      }else{
        /*
         * Blogger returned this entry for q=, so if it is not a title/label
         * match it is treated as the lowest-priority article-text match.
         */
        item.tier = 10;
        item.reason = "Article text match";
      }

      item.time = Date.parse(item.published) || 0;
      targetedByUrl.set(item.url,item);
      targetedItems.push(item);
    });

    targetedItems.sort(function(a,b){
      return b.tier - a.tier || b.time - a.time;
    });

    if(targetedItems.length){
      if(window.console && console.info){
        console.info(
          "Electric Eye search v2.0:",
          {
            query:query,
            mode:"targeted-q",
            matches:targetedItems.length,
            titleMatches:targetedItems.filter(function(item){ return item.tier === 30; }).length,
            labelMatches:targetedItems.filter(function(item){ return item.tier === 20; }).length,
            bodyMatches:targetedItems.filter(function(item){ return item.tier === 10; }).length
          }
        );
      }

      writeCache(query,targetedItems);
      return targetedItems;
    }

    /*
     * Blogger q= can miss label-only searches. Try the narrow direct-label
     * feeds next; these are still much cheaper than rebuilding the full index.
     */
    var labelEntries = await directLabelEntries(query);
    var labelItems = [];
    var labelByUrl = new Map();

    labelEntries.forEach(function(raw){
      var item = parseEntry(raw);
      if(!item.url || labelByUrl.has(item.url)) return;
      item.tier = titleMatches(item,query) ? 30 : 20;
      item.reason = item.tier === 30 ? "Title match" : "Label match";
      item.time = Date.parse(item.published) || 0;
      labelByUrl.set(item.url,item);
      labelItems.push(item);
    });

    labelItems.sort(function(a,b){
      return b.tier - a.tier || b.time - a.time;
    });

    if(labelItems.length){
      if(window.console && console.info){
        console.info(
          "Electric Eye search v2.0:",
          {
            query:query,
            mode:"direct-label",
            matches:labelItems.length
          }
        );
      }

      writeCache(query,labelItems);
      return labelItems;
    }

    /*
     * Last resort only: load the complete title/label index. This preserves
     * the broad historical fallback without making every search pay its cost.
     */
    var indexItems = await loadCompleteIndex();

    var ranked = indexItems
      .map(function(item){
        if(titleMatches(item,query)){
          item.tier = 30;
          item.reason = "Title match";
        }else if(labelMatches(item,query)){
          item.tier = 20;
          item.reason = "Label match";
        }else{
          item.tier = 0;
          item.reason = "";
        }

        item.time = Date.parse(item.published) || 0;
        return item;
      })
      .filter(function(item){
        return item.tier > 0;
      })
      .sort(function(a,b){
        return b.tier - a.tier || b.time - a.time;
      });

    if(window.console && console.info){
      console.info(
        "Electric Eye search v2.0:",
        {
          query:query,
          mode:"complete-index-fallback",
          indexedPosts:indexItems.length,
          matches:ranked.length
        }
      );
    }

    writeCache(query,ranked);
    return ranked;
  }

  function escapeHtml(value){
    return String(value || "").replace(/[&<>"']/g,function(ch){
      return {
        "&":"&amp;",
        "<":"&lt;",
        ">":"&gt;",
        '"':"&quot;",
        "'":"&#39;"
      }[ch];
    });
  }

  function formattedDate(value){
    var date = new Date(value);
    if(!isFinite(date.getTime())) return "";

    try{
      return new Intl.DateTimeFormat(
        "en-US",
        {month:"long",day:"numeric",year:"numeric"}
      ).format(date);
    }catch(error){
      return "";
    }
  }

  function cardHtml(item,index){
    var date = formattedDate(item.published);

    return (
      '<article class="blog-post hentry index-post ee-search-result post-' + index + '">' +
        '<a class="entry-image-wrap is-image" href="' + escapeHtml(item.url) + '" title="' + escapeHtml(item.title) + '">' +
          '<span class="entry-thumb lazy-ify" style="background-image:url(&quot;' + escapeHtml(item.image) + '&quot;)"></span>' +
        '</a>' +
        '<div class="entry-header">' +
          '<span class="entry-category ee-search-match">' + escapeHtml(item.reason) + '</span>' +
          '<h2 class="entry-title">' +
            '<a href="' + escapeHtml(item.url) + '" title="' + escapeHtml(item.title) + '">' + escapeHtml(item.title) + '</a>' +
          '</h2>' +
          (date ? '<div class="entry-meta"><time class="ee-search-date" datetime="' + escapeHtml(item.published) + '">' + escapeHtml(date) + '</time></div>' : '') +
        '</div>' +
      '</article>'
    );
  }

  function setupShell(){
    var wrap = document.querySelector(".blog-posts-wrap");
    if(!wrap) throw new Error("Search result wrapper not found");

    /*
     * Blogger may mark the native result page as "no-posts" even when our
     * broader label/title search finds valid matches. Remove only those native
     * empty-state markers before rendering custom results.
     */
    wrap.classList.remove("no-posts");

    var blogWidget = wrap.closest(".Blog");
    if(blogWidget) blogWidget.classList.remove("no-posts");

    Array.prototype.forEach.call(
      wrap.querySelectorAll(":scope > .queryEmpty"),
      function(node){ node.remove(); }
    );

    var message = wrap.querySelector(":scope > .queryMessage");
    var posts = wrap.querySelector(":scope > .blog-posts");
    var pager = wrap.querySelector(":scope > #blog-pager");

    if(!posts) throw new Error("Search posts container not found");

    if(!message){
      message = document.createElement("div");
      message.className = "queryMessage";
      wrap.insertBefore(message,posts);
    }

    if(!pager){
      pager = document.createElement("div");
      pager.className = "blog-pager";
      pager.id = "blog-pager";
      wrap.appendChild(pager);
    }

    return {
      wrap:wrap,
      message:message,
      posts:posts,
      pager:pager
    };
  }

  function render(results,query,shell){
    var shown = 0;

    shell.posts.innerHTML = "";
    shell.pager.innerHTML = "";

    var count = results.length;
    var noun = count === 1 ? "result" : "results";

    shell.message.innerHTML =
      '<span class="query-info query-success">' +
      count + ' ' + noun + ' for &ldquo;' + escapeHtml(query) + '&rdquo;' +
      '</span>';

    if(!count){
      shell.posts.innerHTML =
        '<div class="ee-search-empty">No matching articles were found.</div>';

      document.documentElement.classList.add("ee-search-ready");
      return;
    }

    var button = document.createElement("a");
    button.className = "load-more btn";
    button.id = "ee-search-load-more";
    button.href = "javascript:;";
    button.textContent = "Load More";

    function updateButton(){
      if(shown >= results.length){
        shell.pager.innerHTML = "";
        return;
      }

      if(!button.parentNode){
        shell.pager.appendChild(button);
      }

      var remaining = results.length - shown;
      button.textContent =
        remaining > CONFIG.batchSize
          ? "Load More"
          : "Load " + remaining + " More";
    }

    function revealNext(){
      var next = results.slice(
        shown,
        shown + CONFIG.batchSize
      );

      shell.posts.insertAdjacentHTML(
        "beforeend",
        next.map(function(item,index){
          return cardHtml(item,shown + index);
        }).join("")
      );

      shown += next.length;
      updateButton();
    }

    button.addEventListener("click",function(event){
      event.preventDefault();
      revealNext();
    });

    revealNext();
    document.documentElement.classList.add("ee-search-ready");
  }

  function queryFromUrl(){
    try{
      return (
        new URLSearchParams(location.search).get("q") || ""
      ).trim();
    }catch(error){
      return "";
    }
  }

  function failSafe(error){
    if(window.console && console.warn){
      console.warn("Electric Eye custom search:",error);
    }

    /*
     * Nothing has been deleted yet if the feed fails before render(),
     * so removing the class restores Blogger's native results.
     */
    document.documentElement.classList.remove(
      "ee-custom-search",
      "ee-search-ready"
    );
  }

  function initialise(){
    var query = queryFromUrl();
    if(!query){
      failSafe(new Error("Search query is empty"));
      return;
    }

    search(query)
      .then(function(results){
        var shell = setupShell();
        render(results,query,shell);
      })
      .catch(failSafe);
  }

  if(document.readyState === "loading"){
    document.addEventListener("DOMContentLoaded",initialise);
  }else{
    initialise();
  }
})();
