    return Array.prototype.slice.call((root||document).querySelectorAll(
      "iframe[src*='embed.music.apple.com'],iframe[src*='music.apple.com'][src*='/embed']"
    ));
  }

  function prepareIframe(iframe){
    iframe.setAttribute("allow","autoplay *; encrypted-media *; fullscreen *; clipboard-write");
    iframe.setAttribute(
      "sandbox",
      "allow-forms allow-popups allow-same-origin allow-scripts allow-storage-access-by-user-activation allow-top-navigation-by-user-activation"
    );

    try{
      var url=new URL(iframe.src,document.baseURI);
      if(!url.searchParams.has("at")){
        url.searchParams.set("at",TOKEN);
        iframe.src=url.toString();
      }
    }catch(error){}
  }

  function ensureStyles(){
    if(document.getElementById("apple-music-banner-styles")) return;
    var style=document.createElement("style");
    style.id="apple-music-banner-styles";
    style.textContent=
      ".apple-music-banner{display:block;text-align:center;margin:0;padding:0;line-height:0}"+
      ".apple-music-banner a{display:inline-block;text-decoration:none;line-height:0}"+
      ".apple-music-banner img{display:block;height:auto;border:0;outline:0}"+
      ".apple-music-banner .am-note{display:block;margin-top:6px;line-height:1.3;text-align:center;font-family:Instrument Sans,Arial,Helvetica,sans-serif;font-size:12px}";
    document.head.appendChild(style);
  }

  function createBanner(rowKey){
    var wrapper=document.createElement("div");
    wrapper.className="apple-music-banner";
    wrapper.setAttribute("data-am-row",rowKey);

    var link=document.createElement("a");
    link.href=SUBSCRIBE_URL;
    link.target="_blank";
    link.rel="nofollow noopener noreferrer sponsored";
    link.setAttribute("aria-label","Try Apple Music");

    var image=document.createElement("img");
    image.src=BADGE_IMG;
    image.alt="Try Apple Music";
    image.loading="lazy";
    image.decoding="async";
    link.appendChild(image);
    wrapper.appendChild(link);

    var note=document.createElement("span");
    note.className="am-note";
    note.innerHTML='<a href="'+SUBSCRIBE_URL+'" target="_blank" rel="nofollow noopener noreferrer sponsored">Click HERE or on the Apple Music banner to subscribe and get 1 month of streaming for free!</a>';
    wrapper.appendChild(note);
    return wrapper;
  }

  function groupByRow(iframes){
    var list=iframes.filter(function(el){
      try{return !!el.getBoundingClientRect();}catch(error){return false;}
    });

    list.sort(function(a,b){
      var ra=a.getBoundingClientRect(),rb=b.getBoundingClientRect();
      return (ra.top-rb.top)||(ra.left-rb.left);
    });

    var rows=[];
    var tolerance=5;
    list.forEach(function(el){
      var rect=el.getBoundingClientRect();
      var top=rect.top+(window.scrollY||0);
      var row=null;
      for(var i=0;i<rows.length;i+=1){
        if(Math.abs(rows[i].top-top)<=tolerance){row=rows[i];break;}
      }
      if(row){
        row.items.push(el);
        row.top=Math.min(row.top,top);
      }else{
        rows.push({top:top,items:[el]});
      }
    });

    rows.forEach(function(row){
      row.items.sort(function(a,b){
        var ra=a.getBoundingClientRect(),rb=b.getBoundingClientRect();
        return (rb.right-ra.right)||(rb.bottom-ra.bottom);
      });
      row.anchor=row.items[0];
    });
    return rows;
  }

  function sizeBannerForRow(banner,row){
    var rects=row.items.map(function(el){return el.getBoundingClientRect();});
    var minLeft=Math.min.apply(null,rects.map(function(rect){return rect.left;}));
    var maxRight=Math.max.apply(null,rects.map(function(rect){return rect.right;}));
    var width=Math.max(0,maxRight-minLeft);
    if(width<10) width=Math.max(width,row.anchor.getBoundingClientRect().width);

    var link=banner.querySelector("a");
    var image=banner.querySelector("img");
    if(link&&image){
      link.style.width=width+"px";
      image.style.width="100%";
      image.style.height="auto";
    }
  }

  function bannerAfter(node){
    var next=node.nextSibling;
    while(next&&next.nodeType===3&&!(/\S/.test(next.nodeValue))) next=next.nextSibling;
    return next&&next.nodeType===1&&next.classList&&next.classList.contains("apple-music-banner") ? next : null;
  }

  function render(){
    var iframes=getIframes(document);
    if(!iframes.length) return false;

    ensureStyles();
    iframes.forEach(prepareIframe);

    groupByRow(iframes).forEach(function(row){
      var rowKey=String(Math.round(row.top));
      var banner=rowBanners.get(rowKey);

      if(!banner||!banner.isConnected){
        banner=bannerAfter(row.anchor);
        if(!banner&&row.anchor.parentNode){
          banner=createBanner(rowKey);
          row.anchor.parentNode.insertBefore(banner,row.anchor.nextSibling);
        }
        if(banner) rowBanners.set(rowKey,banner);
      }

      if(banner) sizeBannerForRow(banner,row);
    });
    return true;
  }

  function start(){
    if(!render()) return;

    window.addEventListener("load",render,{once:true});
    window.addEventListener("resize",function(){
      if(resizeTimer) cancelAnimationFrame(resizeTimer);
      resizeTimer=requestAnimationFrame(render);
    },{passive:true});
  }

  if(document.readyState==="loading") document.addEventListener("DOMContentLoaded",start,{once:true});
  else start();
}());
