(function () {
  function prepareCascadingMenu() {
    var nav = document.getElementById('cryzen-pro-main-nav-menu');
    if (!nav) return;

    var parents = nav.querySelectorAll('li.has-sub');
    parents.forEach(function (item) {
      var panel = null;
      for (var i = 0; i < item.children.length; i++) {
        var child = item.children[i];
        if (child.tagName === 'UL' || child.classList.contains('ul')) {
          panel = child;
          break;
        }
      }
      if (!panel) return;

      function chooseDirection() {
        item.classList.remove('ee-open-left');
        if (item.parentElement === nav) return;

        var itemRect = item.getBoundingClientRect();
        var panelWidth = Math.max(panel.offsetWidth || 300, 300);
        if (itemRect.right + panelWidth > window.innerWidth - 12) {
          item.classList.add('ee-open-left');
        }
      }

      item.addEventListener('mouseenter', chooseDirection);
      item.addEventListener('focusin', chooseDirection);
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', prepareCascadingMenu);
  } else {
    prepareCascadingMenu();
  }
}());
