(function () {
  var ticking = false;
  var threshold = 150;

  function updateElectricEyeHeader() {
    document.body.classList.toggle('ee-header-compact', window.scrollY > threshold);
    ticking = false;
  }

  function requestHeaderUpdate() {
    if (!ticking) {
      window.requestAnimationFrame(updateElectricEyeHeader);
      ticking = true;
    }
  }

  window.addEventListener('scroll', requestHeaderUpdate, {passive:true});
  window.addEventListener('resize', requestHeaderUpdate, {passive:true});
  updateElectricEyeHeader();
}());
