(function () {
  'use strict';

  if (!/^\/\d{4}\/?$/.test(window.location.pathname)) {
    return;
  }

  var BATCH_SIZE = 20;
  var nextUrl = null;
  var loading = false;
  var finished = false;
  var observer = null;

  function root() {
    return document.documentElement;
  }

  function postsContainer() {
    return document.querySelector('.blog-posts');
  }

  function pager() {
    return document.getElementById('blog-pager');
  }

  function currentPostCount() {
    return document.querySelectorAll('.blog-posts .index-post').length;
  }

  function setLoading(value) {
    loading = value;
    root().classList.toggle('ee-archive-loading', value);
  }

  function setFinished() {
    finished = true;
    setLoading(false);
    root().classList.add('ee-archive-finished');
  }

  function normaliseUrl(url) {
    if (!url) {
      return null;
    }

    try {
      return new URL(url, window.location.origin).toString();
    } catch (error) {
      return null;
    }
  }

  function extractNextUrl(doc) {
    var button = doc.getElementById('cryzen-pro-load-more-link');
    return button ? normaliseUrl(button.getAttribute('data-load')) : null;
  }

  function initialiseExistingNextUrl() {
    var button = document.getElementById('cryzen-pro-load-more-link');
    nextUrl = button ? normaliseUrl(button.getAttribute('data-load')) : null;

    if (!nextUrl) {
      setFinished();
    }
  }

  function refreshLoadedCards() {
    if (!window.jQuery) {
      return;
    }

    try {
      window.jQuery('.index-post .entry-image-wrap .entry-thumb').lazyify();
    } catch (error) {
      /* The cards remain usable if the optional lazy-load helper is absent. */
    }

    try {
      if (typeof window.fixedSidebarIfy === 'function') {
        window.fixedSidebarIfy('#main-wrapper');
      }
    } catch (error) {
      /* Sidebar recalculation is optional. */
    }
  }

  async function fetchOneArchivePage() {
    if (!nextUrl || finished) {
      setFinished();
      return false;
    }

    var response = await fetch(nextUrl, {
      credentials: 'same-origin'
    });

    if (!response.ok) {
      throw new Error('Archive request failed with status ' + response.status);
    }

    var html = await response.text();
    var doc = new DOMParser().parseFromString(html, 'text/html');
    var incomingPosts = doc.querySelector('.blog-posts');
    var target = postsContainer();

    if (!incomingPosts || !target) {
      throw new Error('Archive post container was not found.');
    }

    var incomingHtml = incomingPosts.innerHTML.trim();

    if (!incomingHtml) {
      nextUrl = null;
      setFinished();
      return false;
    }

    target.insertAdjacentHTML('beforeend', incomingHtml);
    nextUrl = extractNextUrl(doc);
    refreshLoadedCards();

    if (!nextUrl) {
      setFinished();
    }

    return true;
  }

  async function loadBatch(amount) {
    if (loading || finished || !nextUrl) {
      return;
    }

    setLoading(true);

    var targetCount = currentPostCount() + amount;

    try {
      while (!finished && nextUrl && currentPostCount() < targetCount) {
        var added = await fetchOneArchivePage();

        if (!added) {
          break;
        }
      }
    } catch (error) {
      console.error('Electric Eye archive loader:', error);
    } finally {
      if (!finished) {
        setLoading(false);
      }
    }
  }

  function initialise() {
    var target = postsContainer();
    var pagerElement = pager();

    if (!target || !pagerElement) {
      window.setTimeout(initialise, 200);
      return;
    }

    initialiseExistingNextUrl();

    if (finished) {
      return;
    }

    /* The archive initially contains one Blogger post: fill it to 20. */
    var initialNeeded = Math.max(0, BATCH_SIZE - currentPostCount());

    if (initialNeeded) {
      loadBatch(initialNeeded);
    }

    observer = new IntersectionObserver(function (entries) {
      entries.forEach(function (entry) {
        if (entry.isIntersecting && !loading && !finished) {
          loadBatch(BATCH_SIZE);
        }
      });
    }, {
      root: null,
      rootMargin: '800px 0px',
      threshold: 0
    });

    observer.observe(pagerElement);
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initialise);
  } else {
    initialise();
  }
})();
