(function () {
  "use strict";

  /*
   * Prevent this global version from initialising twice.
   */

  if (window.eeGlobalArticlePreviewInitialised) {
    return;
  }

  window.eeGlobalArticlePreviewInitialised = true;

  function initialiseGlobalArticlePreviews() {
    var HOVER_DELAY = 280;
    var LONG_PRESS_DELAY = 550;

    var CURSOR_GAP = 18;
    var VIEWPORT_MARGIN = 12;

    /*
     * Standard Blogger article URL:
     * /2026/07/article-title.html
     */

    var BLOGGER_ARTICLE_PATH =
      /^\/\d{4}\/\d{1,2}\/[^?#]+\.html\/?$/i;

    /*
     * The global version scans the entire page.
     */

    var previewZone = document.body;

    if (!previewZone) {
      return;
    }

    function isEligibleArticleLink(link) {
      if (!link || !link.href) {
        return false;
      }

      /*
       * Exclude any link or section carrying this class.
       */

      if (link.closest(".no-article-preview")) {
        return false;
      }

      if (link.hasAttribute("download")) {
        return false;
      }

      var rawHref = link.getAttribute("href");

      if (!rawHref) {
        return false;
      }

      var lowerHref = rawHref.toLowerCase();

      if (
        rawHref.charAt(0) === "#" ||
        lowerHref.indexOf("mailto:") === 0 ||
        lowerHref.indexOf("tel:") === 0 ||
        lowerHref.indexOf("javascript:") === 0
      ) {
        return false;
      }

      try {
        var linkUrl = new URL(
          link.href,
          window.location.href
        );

        var currentUrl = new URL(
          window.location.href
        );

        /*
         * Internal links only.
         */

        if (linkUrl.origin !== currentUrl.origin) {
          return false;
        }

        /*
         * Do not preview the page currently being viewed.
         */

        if (
          linkUrl.pathname === currentUrl.pathname &&
          linkUrl.search === currentUrl.search
        ) {
          return false;
        }

        /*
         * Only dated Blogger article URLs.
         * Static pages under /p/ are excluded.
         */

        return BLOGGER_ARTICLE_PATH.test(
          linkUrl.pathname
        );
      } catch (error) {
        return false;
      }
    }

    var previewLinks = Array.prototype.slice
      .call(
        previewZone.querySelectorAll("a[href]")
      )
      .filter(isEligibleArticleLink);

    if (!previewLinks.length) {
      return;
    }

    /*
     * Remove an old copy of this particular preview card.
     */

    var existingPreview = document.getElementById(
      "ee-global-article-preview"
    );

    if (existingPreview) {
      existingPreview.remove();
    }

    var previewCard = document.createElement("div");

    previewCard.id = "ee-global-article-preview";
    previewCard.setAttribute("role", "tooltip");
    previewCard.setAttribute(
      "aria-hidden",
      "true"
    );

    previewCard.innerHTML =
      '<div class="ee-preview-image-area">' +
        '<img class="ee-preview-image" alt="" decoding="async"/>' +
        '<div class="ee-preview-loader" aria-hidden="true">' +
          '<span class="ee-preview-spinner"></span>' +
        "</div>" +
      "</div>" +
      '<div class="ee-preview-content">' +
        '<p class="ee-preview-title"></p>' +
        '<div class="ee-preview-domain"></div>' +
      "</div>";

    document.body.appendChild(previewCard);

    var imageArea = previewCard.querySelector(
      ".ee-preview-image-area"
    );

    var previewImage = previewCard.querySelector(
      ".ee-preview-image"
    );

    var previewTitle = previewCard.querySelector(
      ".ee-preview-title"
    );

    var previewDomain = previewCard.querySelector(
      ".ee-preview-domain"
    );

    var metadataCache = new Map();
    var pendingRequests = new Map();

    var activeLink = null;

    var hoverTimer = null;
    var longPressTimer = null;

    var pointerX = window.innerWidth / 2;
    var pointerY = window.innerHeight / 2;

    var requestNumber = 0;
    var suppressNextClick = false;

    function normaliseUrl(url) {
      try {
        var parsedUrl = new URL(
          url,
          window.location.href
        );

        parsedUrl.hash = "";

        return parsedUrl.href;
      } catch (error) {
        return url;
      }
    }

    function getDomain(url) {
      try {
        return new URL(
          url,
          window.location.href
        )
          .hostname
          .replace(/^www\./i, "");
      } catch (error) {
        return window.location.hostname
          .replace(/^www\./i, "");
      }
    }

    function getFallbackTitle(link) {
      return (
        link.getAttribute("data-preview-title") ||
        link.getAttribute("aria-label") ||
        link.textContent.trim() ||
        "Article"
      );
    }

    function getMetaContent(page, selector) {
      var element = page.querySelector(selector);

      if (!element) {
        return "";
      }

      return element.getAttribute("content") || "";
    }

    function makeAbsoluteUrl(url, pageUrl) {
      if (!url) {
        return "";
      }

      try {
        return new URL(url, pageUrl).href;
      } catch (error) {
        return url;
      }
    }

    function cleanYouTubeId(videoId) {
      if (!videoId) {
        return "";
      }

      videoId = String(videoId)
        .trim()
        .split("?")[0]
        .split("&")[0]
        .split("#")[0]
        .split("/")[0];

      if (!/^[A-Za-z0-9_-]{6,20}$/.test(videoId)) {
        return "";
      }

      return videoId;
    }

    function getYouTubeId(url) {
      if (!url) {
        return "";
      }

      try {
        var parsedUrl = new URL(
          url,
          window.location.href
        );

        var hostname = parsedUrl.hostname
          .replace(/^www\./i, "")
          .toLowerCase();

        if (
          hostname === "youtube.com" ||
          hostname === "m.youtube.com" ||
          hostname === "music.youtube.com"
        ) {
          if (parsedUrl.pathname === "/watch") {
            return cleanYouTubeId(
              parsedUrl.searchParams.get("v")
            );
          }

          var pathMatch = parsedUrl.pathname.match(
            /^\/(?:embed|shorts|live|v)\/([^/?#]+)/
          );

          if (pathMatch) {
            return cleanYouTubeId(pathMatch[1]);
          }
        }

        if (hostname === "youtu.be") {
          return cleanYouTubeId(
            parsedUrl.pathname.replace(/^\/+/, "")
          );
        }

        if (hostname === "youtube-nocookie.com") {
          var noCookieMatch =
            parsedUrl.pathname.match(
              /^\/embed\/([^/?#]+)/
            );

          if (noCookieMatch) {
            return cleanYouTubeId(
              noCookieMatch[1]
            );
          }
        }
      } catch (error) {
        return "";
      }

      return "";
    }

    function buildYouTubeThumbnail(videoId) {
      videoId = cleanYouTubeId(videoId);

      if (!videoId) {
        return "";
      }

      return (
        "https://i.ytimg.com/vi/" +
        videoId +
        "/hqdefault.jpg"
      );
    }

    function getYouTubeThumbnail(
      page,
      html,
      pageUrl
    ) {
      /*
       * Blogger often stores a video thumbnail directly in
       * data-thumbnail-src.
       */

      var thumbnailElements =
        page.querySelectorAll(
          "[data-thumbnail-src]"
        );

      for (
        var thumbnailIndex = 0;
        thumbnailIndex < thumbnailElements.length;
        thumbnailIndex++
      ) {
        var directThumbnail =
          thumbnailElements[
            thumbnailIndex
          ].getAttribute(
            "data-thumbnail-src"
          );

        if (
          directThumbnail &&
          (
            directThumbnail.indexOf("ytimg.com") !== -1 ||
            directThumbnail.indexOf("youtube.com") !== -1 ||
            directThumbnail.indexOf(
              "googleusercontent.com"
            ) !== -1
          )
        ) {
          return makeAbsoluteUrl(
            directThumbnail,
            pageUrl
          );
        }
      }

      /*
       * Inspect all iframe attributes.
       */

      var iframes = page.querySelectorAll("iframe");

      for (
        var iframeIndex = 0;
        iframeIndex < iframes.length;
        iframeIndex++
      ) {
        var iframe = iframes[iframeIndex];

        var iframeThumbnail =
          iframe.getAttribute(
            "data-thumbnail-src"
          ) ||
          iframe.getAttribute(
            "data-thumbnail"
          ) ||
          "";

        if (iframeThumbnail) {
          return makeAbsoluteUrl(
            iframeThumbnail,
            pageUrl
          );
        }

        var iframeUrls = [
          iframe.getAttribute("src"),
          iframe.getAttribute("data-src"),
          iframe.getAttribute("data-lazy-src"),
          iframe.getAttribute("data-video-url"),
          iframe.getAttribute("data-url")
        ];

        for (
          var iframeUrlIndex = 0;
          iframeUrlIndex < iframeUrls.length;
          iframeUrlIndex++
        ) {
          var iframeVideoId = getYouTubeId(
            iframeUrls[iframeUrlIndex]
          );

          if (iframeVideoId) {
            return buildYouTubeThumbnail(
              iframeVideoId
            );
          }
        }
      }

      /*
       * Check video IDs and URLs stored in data attributes.
       */

      var videoElements =
        page.querySelectorAll(
          "[data-video-id]," +
          "[data-youtube-id]," +
          "[data-video-url]," +
          "[data-video]"
        );

      for (
        var videoIndex = 0;
        videoIndex < videoElements.length;
        videoIndex++
      ) {
        var videoElement =
          videoElements[videoIndex];

        var directVideoId =
          videoElement.getAttribute(
            "data-video-id"
          ) ||
          videoElement.getAttribute(
            "data-youtube-id"
          ) ||
          "";

        directVideoId =
          cleanYouTubeId(directVideoId);

        if (directVideoId) {
          return buildYouTubeThumbnail(
            directVideoId
          );
        }

        var videoUrl =
          videoElement.getAttribute(
            "data-video-url"
          ) ||
          videoElement.getAttribute(
            "data-video"
          ) ||
          "";

        var attributeVideoId =
          getYouTubeId(videoUrl);

        if (attributeVideoId) {
          return buildYouTubeThumbnail(
            attributeVideoId
          );
        }
      }

      /*
       * Check ordinary YouTube links.
       */

      var youtubeLinks = page.querySelectorAll(
        'a[href*="youtube.com/"],' +
        'a[href*="youtu.be/"],' +
        'a[href*="youtube-nocookie.com/"]'
      );

      for (
        var linkIndex = 0;
        linkIndex < youtubeLinks.length;
        linkIndex++
      ) {
        var linkedVideoId = getYouTubeId(
          youtubeLinks[
            linkIndex
          ].getAttribute("href")
        );

        if (linkedVideoId) {
          return buildYouTubeThumbnail(
            linkedVideoId
          );
        }
      }

      /*
       * Inspect raw and escaped page HTML.
       */

      var cleanedHtml = html
        .replace(/\\u002F/gi, "/")
        .replace(/\\\//g, "/")
        .replace(/&quot;/gi, '"')
        .replace(/&#39;/gi, "'")
        .replace(/&amp;/gi, "&");

      var rawVideoPatterns = [
        /youtube(?:-nocookie)?\.com\/embed\/([A-Za-z0-9_-]{6,20})/i,
        /youtube\.com\/watch\?[^"'<>]*v=([A-Za-z0-9_-]{6,20})/i,
        /youtu\.be\/([A-Za-z0-9_-]{6,20})/i,
        /youtube\.com\/shorts\/([A-Za-z0-9_-]{6,20})/i,
        /youtube\.com\/live\/([A-Za-z0-9_-]{6,20})/i,
        /data-video-id=["']([A-Za-z0-9_-]{6,20})["']/i,
        /data-youtube-id=["']([A-Za-z0-9_-]{6,20})["']/i
      ];

      for (
        var patternIndex = 0;
        patternIndex < rawVideoPatterns.length;
        patternIndex++
      ) {
        var rawVideoMatch = cleanedHtml.match(
          rawVideoPatterns[patternIndex]
        );

        if (rawVideoMatch) {
          return buildYouTubeThumbnail(
            rawVideoMatch[1]
          );
        }
      }

      var rawThumbnailMatch =
        cleanedHtml.match(
          /https?:\/\/(?:i\.ytimg\.com|img\.youtube\.com)\/vi(?:_webp)?\/([A-Za-z0-9_-]{6,20})\/[^"'&<>\s\\]+/i
        );

      if (rawThumbnailMatch) {
        return buildYouTubeThumbnail(
          rawThumbnailMatch[1]
        );
      }

      return "";
    }

    function extractMetadata(
      html,
      pageUrl,
      fallbackTitle
    ) {
      var parser = new DOMParser();

      var page = parser.parseFromString(
