  function setViewerItem(index, focusThumb) {
    if (!activeItems.length) return;
    activeIndex = (index + activeItems.length) % activeItems.length;
    var item = activeItems[activeIndex];

    viewerImage.src = item.full;
    viewerImage.alt = item.alt;
    viewerCaption.textContent = item.caption;
    viewerCounter.textContent = String(activeIndex + 1) + " / " + String(activeItems.length);

    var thumbs = filmstrip.querySelectorAll(".ee-gallery-thumb");
    for (var i = 0; i < thumbs.length; i += 1) {
