      thumbs[i].classList.toggle("ee-gallery-thumb-active", selected);
      thumbs[i].setAttribute("aria-selected", selected ? "true" : "false");
      thumbs[i].tabIndex = selected ? 0 : -1;
    }
    if (thumbs[activeIndex]) {
