    var seen=new Set();

    return labels
      .filter(function(label){ return groups.entities.has(norm(label)); })
      .filter(function(label){
        var n=norm(label);
        if (!n || seen.has(n)) return false;
        seen.add(n);
        return true;
      })
      .sort(function(a,b){
        var at=containsPhrase(title,a) ? 1 : 0;
        var bt=containsPhrase(title,b) ? 1 : 0;
        if (at !== bt) return bt-at;
        var aw=words(a).length;
        var bw=words(b).length;
        if (aw !== bw) return bw-aw;
        return b.length-a.length;
      });
  }

  function prioritizedStyleLabels(labels,groups){
    var seen=new Set();

    return labels
      .filter(function(label){ return groups.styles.has(norm(label)); })
      .filter(function(label){
        var n=norm(label);
        if (!n || seen.has(n)) return false;
        seen.add(n);
        return true;
      })
      .sort(function(a,b){
        var as=styleSpecificity(a);
        var bs=styleSpecificity(b);
        if (as !== bs) return bs-as;
        return b.length-a.length;
      });
  }

  function detectType(title, labels){
    var hay = norm(title + ' ' + labels.join(' '));

    if (/\binterview\b/.test(hay)) return 'Interview';
    if (/\b(album review|record review)\b/.test(hay)) return 'Album Review';
    if (/\b(friday|monday).*\bplaylist\b|\bplaylist\b/.test(hay)) return 'Playlist';

    /*
     * A festival name by itself is not a Concert Review. Explicit review/live
     * structure wins; otherwise news language can classify festival news.
     */
    if (/\b(concert review|live review|festival review)\b/.test(hay) || /\s@\s/.test(title)) {
      return 'Concert Review';
    }

    if (/\bnews\b|announc|release|new album|new single|tour|premiere/.test(hay)) {
      return 'News';
    }

    return labels[0] || 'Article';
  }

  function extractArtist(title){
    var raw = String(title || '').trim();
    var m;

    if ((m = raw.match(/^(.+?)\s+@\s+/))) return norm(m[1]);

    if ((m = raw.match(/^(?:interview(?:\s+with)?|in conversation with)\s*[:–—-]\s*(.+?)(?:\s+[–—-]\s+|$)/i))) {
      return norm(m[1]);
    }

    if ((m = raw.match(/^(.+?)\s+[–—-]\s+(?:album review|interview|new album|new single|official video)/i))) {
      return norm(m[1]);
    }

    if ((m = raw.match(/^(.+?)\s+(?:announce|announces|release|releases|return|returns|share|shares|unveil|unveils)\b/i))) {
      return norm(m[1]);
    }

    return '';
  }

  function extractPlace(title){
    var raw = String(title || '');
    var m = raw.match(/@\s*([^,–—-]+),\s*([^–—-]+?)(?:\s*[–—-]\s*|$)/);

    return m ? {
      venue: norm(m[1]),
      city: norm(
        m[2].replace(
          /\b(january|february|march|april|may|june|july|august|september|october|november|december)\b.*$/i,
          ''
        )
      )
    } : {venue:'',city:''};
  }

  function extractFestival(title, labels){
    var hay = [title].concat(labels).join(' ');
    var m = hay.match(/\b(hellfest(?:\s+\d{4})?|download festival(?:\s+\d{4})?|rock en seine(?:\s+\d{4})?|motocultor(?:\s+\d{4})?|festival[^,–—-]*)/i);
    return m ? norm(m[1].replace(/\s+\d{4}$/,'')) : '';
  }

  function metadata(title, labels){
    var place = extractPlace(title);

    return {
      artist: extractArtist(title),
      venue: place.venue,
      city: place.city,
      festival: extractFestival(title, labels),
      type: detectType(title, labels),
      tokens: titleTokens(title, place)
    };
  }

  function normalizedLabelSet(labels){
    return new Set(
      labels.map(norm).filter(Boolean)
    );
  }

  function usefulLabelSets(labels, meta){
    var styles = new Set();
    var entities = new Set();
    var topics = new Set();

    labels.map(norm).filter(Boolean).forEach(function(label){
      if (EDITORIAL_LABELS.has(label)) return;
      if (meta.venue && label === meta.venue) return;
      if (meta.city && label === meta.city) return;
      if (meta.festival && label === meta.festival) return;

      if (STYLE_RX.test(label)) {
        styles.add(label);
      } else if (isGenericTopicLabel(label)) {
        topics.add(label);
      } else {
        entities.add(label);
      }
    });

    return {
      styles:styles,
      entities:entities,
      topics:topics
    };
  }

  function readCurrent(){
    var labels = Array.prototype.map.call(root.querySelectorAll('.ee-rm-current-label'), function(el){
      return el.textContent.trim();
    }).filter(Boolean);

    var title = root.getAttribute('data-current-title') || document.title;
    var meta = metadata(title, labels);
    var groups = usefulLabelSets(labels, meta);
    var entityLabels = prioritizedEntityLabels(labels, groups, title);
    var styleLabels = prioritizedStyleLabels(labels, groups);

    var primaryEntity = meta.artist || norm(entityLabels[0] || '');
    var primaryQuery = '';

    if (primaryEntity) {
      for (var i=0;i<entityLabels.length;i++) {
        if (norm(entityLabels[i]) === primaryEntity) {
          primaryQuery = entityLabels[i];
          break;
        }
      }
    }

    if (!primaryQuery) {
      primaryQuery = entityLabels[0] || meta.artist || '';
    }

    return {
      title: title,
      url: canonical(root.getAttribute('data-current-url') || location.href),
      labels: labels,
      labelSet: normalizedLabelSet(labels),
      labelGroups: groups,
      entityLabels: entityLabels,
      styleLabels: styleLabels,
      primaryEntity: primaryEntity,
      primaryQuery: primaryQuery,
      meta: meta
    };
  }

  function entryLink(entry){
    var links = entry.link || [];
    for (var i=0;i<links.length;i++) {
      if (links[i].rel === 'alternate') return links[i].href;
    }
    return '';
  }

  function imageFromEntry(entry){
    var src = '';
    var html = entry.content && entry.content.$t ? entry.content.$t : '';

    if (html) {
      var m = html.match(/<img[^>]+(?:data-original-src|data-src|src)=["']([^"']+)["']/i);
      if (m && m[1]) src = m[1];
    }

    if (!src && entry.media$thumbnail && entry.media$thumbnail.url) {
      src = entry.media$thumbnail.url;
    }

    if (!src) return CONFIG.fallbackImage;

    src = String(src).replace(/&amp;/g, '&');

    return src
      .replace(/\/s\d+(?:-c)?\//i, '/w1200-h800-p-k-no-nu/')
      .replace(/\/w\d+-h\d+(?:-[^/]+)?\//i, '/w1200-h800-p-k-no-nu/')
      .replace(/=s\d+(?:-c)?/i, '=w1200-h800-p-k-no-nu')
      .replace(/=w\d+-h\d+(?:-[^?&]+)?/i, '=w1200-h800-p-k-no-nu');
  }

  function parseEntry(entry){
    var title = entry.title && entry.title.$t || '';
    var labels = (entry.category || []).map(function(c){ return c.term; }).filter(Boolean);
    var url = canonical(entryLink(entry));
    var meta = metadata(title, labels);

    return {
      title: title,
      url: url,
      labels: labels,
      labelSet: normalizedLabelSet(labels),
      labelGroups: usefulLabelSets(labels, meta),
      published: new Date(entry.published && entry.published.$t || 0),
      image: imageFromEntry(entry),
      meta: meta
    };
  }

  function sameArtist(candidate,current){
    var ca = candidate.meta.artist;
    var pa = current.meta.artist;

    if (pa && ca && pa === ca) return true;

    /*
     * Cross-format support: an artist can be explicit in one title and carried
     * as an exact Blogger label in another format.
     */
    if (pa && candidate.labelSet.has(pa)) return true;
    if (ca && current.labelSet.has(ca)) return true;

    return false;
  }

  function score(candidate,current){
    var s = 0;
    var tier = 0;
    var reasons = [];
    var c = candidate.meta;
    var p = current.meta;

    var artistMatch = sameArtist(candidate,current);

    if (artistMatch) {
      s += 220;
      tier = Math.max(tier,5);
      reasons.push('artist');
    }

    /*
     * Exact shared non-editorial/non-style labels are treated as entities.
     * An entity appearing in either headline is especially strong evidence.
     */
    var sharedEntities = intersectionValues(
      current.labelGroups.entities,
      candidate.labelGroups.entities
    );

    if (sharedEntities.length) {
      var entityBonus = 0;
      var entityTitleBacked = false;

      sharedEntities.forEach(function(entity){
        var backed =
          containsPhrase(current.title,entity) ||
          containsPhrase(candidate.title,entity);

        entityTitleBacked = entityTitleBacked || backed;
        entityBonus += backed ? 100 : 55;
      });

      s += Math.min(180,entityBonus);
      tier = Math.max(tier,entityTitleBacked ? 4 : 3);
      reasons.push('entity');
    }

    /*
     * Exact shared genres/styles are weighted by specificity. "Rock" remains a
     * useful clue but cannot compete with "Southern Rock" or "Death Metal".
     */
    var sharedStyles = intersectionValues(
      current.labelGroups.styles,
      candidate.labelGroups.styles
    );

    if (sharedStyles.length) {
      var styleBonus = 0;
      var bestStyleSpecificity = 0;

      sharedStyles.forEach(function(style){
        var specificity = styleSpecificity(style);
        bestStyleSpecificity = Math.max(bestStyleSpecificity,specificity);

        if (specificity === 3) styleBonus += 26;
        else if (specificity === 2) styleBonus += 15;
        else styleBonus += 5;
      });

      s += Math.min(52,styleBonus);
      tier = Math.max(tier,bestStyleSpecificity === 3 ? 3 : (bestStyleSpecificity === 2 ? 2 : 1));
      reasons.push('style');
    }

    var sharedTopics = intersectionSize(
      current.labelGroups.topics,
      candidate.labelGroups.topics
    );

    if (sharedTopics) {
      s += Math.min(10,sharedTopics * 5);
      tier = Math.max(tier,1);
      reasons.push('topics');
    }

    /*
     * Festival and venue are deliberately the SAME weak contextual signal.
     * Matching both still earns this bonus only once.
     */
    var sameFestival =
      p.festival && c.festival && p.festival === c.festival;

    var sameVenue =
      p.venue && c.venue && p.venue === c.venue;

    var eventContext = !!(sameFestival || sameVenue);

    if (eventContext) {
      s += 8;
      tier = Math.max(tier,1);
      reasons.push('event-context');
    }

    if (p.type === c.type) {
      s += 3;
      reasons.push('type');
    }

    if (p.city && c.city && p.city === c.city) {
      s += 1;
      reasons.push('city');
    }

    /*
     * Venue/city words are excluded from titleTokens(), preventing location
     * similarity from receiving a second hidden relevance bonus.
     */
    var commonTokens = intersectionSize(p.tokens,c.tokens);

    if (commonTokens >= 2) {
      s += Math.min(18,commonTokens * 6);
      tier = Math.max(tier,2);
      reasons.push('title');
    } else if (commonTokens === 1) {
      s += 2;
      reasons.push('title');
    }

    /*
     * Recency is only a tie-breaking influence, never a major relevance signal.
     */
    var ageDays = Math.max(
      0,
      (Date.now() - candidate.published.getTime()) / 86400000
    );

    if (ageDays <= 365) s += 2;
    else if (ageDays <= 1095) s += 1;

    candidate.score = s;
    candidate.tier = tier;
    candidate.reasons = reasons;

    candidate.eventOnly =
      eventContext &&
      !artistMatch &&
      sharedEntities.length === 0 &&
      sharedStyles.length === 0 &&
      sharedTopics === 0 &&
      commonTokens < 2;

    return candidate;
  }

  function choose(scored){
    scored.sort(function(a,b){
      return b.tier - a.tier ||
        b.score - a.score ||
        b.published - a.published;
    });

    var chosen = [];
    var normalizedTitles = new Set();
    var eventOnlyCount = 0;

    scored.forEach(function(item){
      if (chosen.length >= CONFIG.limit) return;
      if (!item.url || item.score <= 0) return;

      var key = norm(item.title).replace(/\b\d{4}\b/g,'').trim();
      if (!key || normalizedTitles.has(key)) return;

      /*
       * Same venue/festival-only recommendations are weak fallback material.
       * Allow at most one in the six-card set.
       */
      if (item.eventOnly && eventOnlyCount >= CONFIG.eventContextLimit) return;

      chosen.push(item);
      normalizedTitles.add(key);

      if (item.eventOnly) eventOnlyCount++;
    });

    return chosen.slice(0,CONFIG.limit);
  }

  function escapeHtml(value){
    return String(value || '').replace(/[&<>"']/g,function(ch){
      return {
        '&':'&amp;',
        '<':'&lt;',
        '>':'&gt;',
        '"':'&quot;',
        "'":'&#39;'
      }[ch];
    });
  }

  function formatDate(date){
    try {
      return new Intl.DateTimeFormat(
        'en-GB',
        {day:'numeric',month:'long',year:'numeric'}
      ).format(date);
    } catch(e) {
      return '';
    }
  }

  function render(items){
    if (!items.length) return;

    var grid = root.querySelector('.ee-rm-grid');

    grid.innerHTML = items.map(function(item){
      return '<article class="ee-rm-card">' +
        '<a class="ee-rm-image" href="' + escapeHtml(item.url) + '" aria-label="' + escapeHtml(item.title) + '">' +
          '<img alt="" loading="lazy" decoding="async" src="' + escapeHtml(item.image) + '"/>' +
        '</a>' +
        '<span class="ee-rm-category">' + escapeHtml(item.meta.type) + '</span>' +
        '<h3 class="ee-rm-title"><a href="' + escapeHtml(item.url) + '">' + escapeHtml(item.title) + '</a></h3>' +
        '<time class="ee-rm-date" datetime="' + escapeHtml(item.published.toISOString()) + '">' + escapeHtml(formatDate(item.published)) + '</time>' +
      '</article>';
    }).join('');

    root.hidden = false;
  }

  function isStyleLabel(label,meta){
    var n = norm(label);
    if (!n || EDITORIAL_LABELS.has(n)) return false;
    if (meta.venue && n === meta.venue) return false;
    if (meta.city && n === meta.city) return false;
    if (meta.festival && n === meta.festival) return false;
    return STYLE_RX.test(n);
  }

  function poolSignature(current){
    var parts = ['v42'];

    if (current.primaryEntity) {
      parts.push('primary:' + current.primaryEntity);
    }

    current.entityLabels
      .slice(0,CONFIG.maxEntityFeeds)
      .map(norm)
      .sort()
      .forEach(function(label){
        parts.push('entity:' + label);
      });

    current.styleLabels
      .slice(0,CONFIG.maxStyleFeeds)
      .map(norm)
      .sort()
      .forEach(function(label){
        parts.push('style:' + label);
      });

    return parts.join('|');
  }

  function cacheKey(current){
    return CONFIG.cacheKeyPrefix + poolSignature(current);
  }

  function compactCandidate(item){
    return {
      title:item.title,
      url:item.url,
      labels:item.labels,
      published:item.published.toISOString(),
      image:item.image
    };
  }

  function reviveCandidate(raw){
    var labels = raw.labels || [];
    var meta = metadata(raw.title || '',labels);

    return {
      title:raw.title || '',
      url:canonical(raw.url || ''),
      labels:labels,
      labelSet:normalizedLabelSet(labels),
      labelGroups:usefulLabelSets(labels,meta),
      published:new Date(raw.published || 0),
      image:raw.image || CONFIG.fallbackImage,
      meta:meta
    };
  }

  function cachedPool(current){
    try {
      var hit = JSON.parse(sessionStorage.getItem(cacheKey(current)) || 'null');

      if (
        hit &&
        Date.now() - hit.time < CONFIG.cacheTtl &&
        Array.isArray(hit.items)
      ) {
        return hit.items.map(reviveCandidate);
      }
    } catch(e){}

    return null;
  }

  function savePool(current,items){
    try {
      /*
       * Cache only compact recommendation metadata — never the full Blogger
       * feed/article HTML. The old engine cached hundreds of complete entries,
       * which could exceed sessionStorage quota and force a refetch.
       */
      sessionStorage.setItem(
        cacheKey(current),
        JSON.stringify({
          time:Date.now(),
          items:items.map(compactCandidate)
        })
      );
    } catch(e){}
  }

  function jsonpFeed(path,params){
    return new Promise(function(resolve,reject){
      var callback =
        'eeReadMoreFeed_' +
        Date.now() +
        '_' +
        Math.floor(Math.random()*1000000);

      var script = document.createElement('script');
      var settled = false;

      var timer = setTimeout(function(){
        cleanup();
        reject(new Error('Blogger feed timed out'));
      },10000);

      function cleanup(){
        if (settled) return;
        settled = true;
        clearTimeout(timer);

        try {
          delete window[callback];
        } catch(e) {
          window[callback] = undefined;
        }

        if (script.parentNode) {
          script.parentNode.removeChild(script);
        }
      }

      window[callback] = function(data){
        cleanup();
        resolve(data || {});
      };

      script.onerror = function(){
        cleanup();
        reject(new Error('Blogger feed request failed'));
      };

      var query = [
        'alt=json-in-script',
        'callback=' + encodeURIComponent(callback)
      ];

      Object.keys(params || {}).forEach(function(key){
        if (params[key] === undefined || params[key] === null || params[key] === '') return;
        query.push(
          encodeURIComponent(key) + '=' + encodeURIComponent(String(params[key]))
        );
      });

      script.src = path + '?' + query.join('&');
      document.head.appendChild(script);
    });
  }

  function entriesFromFeed(data){
    return data && data.feed && data.feed.entry || [];
  }

  function loadCandidatePool(current){
    var cache = cachedPool(current);
    if (cache) return Promise.resolve(cache);

    var requests = [];

    /*
     * 1. Recent posts remain fallback material only.
     */
    requests.push(
      jsonpFeed('/feeds/posts/default',{
        'max-results':CONFIG.recentLimit
      })
    );

    /*
     * 2. Search the FULL archive for the strongest resolved/current entity.
     *    This catches older articles that may not carry consistent labels.
     */
    if (current.primaryQuery) {
      requests.push(
        jsonpFeed('/feeds/posts/default',{
          q:current.primaryQuery,
          'max-results':CONFIG.targetedLimit
        })
      );
    }

    /*
     * 3. Exact non-editorial entity/topic labels are first-class retrieval
     *    signals. This is what lets artist labels rescue unusual headline forms.
     */
    current.entityLabels
      .slice(0,CONFIG.maxEntityFeeds)
      .forEach(function(label){
        requests.push(
          jsonpFeed(
            '/feeds/posts/default/-/' + encodeURIComponent(label),
            {'max-results':CONFIG.targetedLimit}
          )
        );
      });

    /*
     * 4. Query the strongest musical-style labels, preferring specific styles.
     *    At most one broad style such as "Rock" may enter the retrieval set.
     */
    var broadUsed = 0;
    var styleUsed = 0;

    current.styleLabels.forEach(function(label){
      if (styleUsed >= CONFIG.maxStyleFeeds) return;

      var specificity = styleSpecificity(label);

      if (specificity === 1) {
        if (broadUsed >= CONFIG.maxBroadStyleFeeds) return;
        broadUsed++;
      }

      styleUsed++;

      requests.push(
        jsonpFeed(
          '/feeds/posts/default/-/' + encodeURIComponent(label),
          {'max-results':CONFIG.targetedLimit}
        )
      );
    });

    /*
     * Run targeted feeds in parallel. One failed feed must not prevent the
     * widget from rendering from the feeds that succeeded.
     */
    return Promise.all(
      requests.map(function(request){
        return request.catch(function(){
          return {feed:{entry:[]}};
        });
      })
    ).then(function(results){
      var byUrl = new Map();

      results.forEach(function(data){
        entriesFromFeed(data).forEach(function(entry){
          var item = parseEntry(entry);
          if (!item.url) return;

          if (!byUrl.has(item.url)) {
            byUrl.set(item.url,item);
          }
        });
      });

      var items = Array.from(byUrl.values());
      savePool(current,items);
      return items;
    });
  }

  var current = readCurrent();

  loadCandidatePool(current).then(function(items){
    var entries = items
      .filter(function(item){
        return item.url &&
          item.url !== current.url &&
          item.published <= new Date();
      })
      .map(function(item){
        return score(item,current);
      });

    render(choose(entries));
  }).catch(function(err){
    if (window.console && console.warn) {
      console.warn('Electric Eye Read More:',err);
    }
  });
})();
