body.script:
//
(function(){
  "use strict";

  var SELECTORS=[
    "#ee-archive-app .ee-a-title",
    "#ee-news-app .ee-n-title",
    "#ee-welcome-app .ee-hero-title",
    "#ee-album-app .ee-album-feature-title",
    "#ee-playlist-app .ee-playlist-feature-title",
    "#ee-forum-app .ee-forum-title",
    ".ee-about-hero h1",
    ".ee-about-hero__intro",
    ".ee-contact-hero h1",
    ".ee-contact-hero__intro",
    "[class*='hero'] h1",
    "[class*='hero'] [class*='-title']",
    "[class*='hero'] [class*='__title']"
  ].join(",");

  var queued=false;
  var active=false;
  var observer=null;

  function longestWordWidth(el,fontSize){
    var style=window.getComputedStyle(el);
    var canvas=longestWordWidth.canvas||(longestWordWidth.canvas=document.createElement("canvas"));
    var context=canvas.getContext("2d");
    context.font=[style.fontStyle,style.fontVariant,style.fontWeight,fontSize+"px",style.fontFamily].join(" ");

    var words=(el.textContent||"").trim().split(/\s+/).filter(Boolean);
    var widest=0;
    for(var i=0;i<words.length;i+=1) widest=Math.max(widest,context.measureText(words[i]).width);
    return widest;
  }

  function fitTitle(el){
    if(!window.matchMedia("(max-width:680px)").matches){
      if(el.dataset.eeMobileOriginalSize){
        el.style.setProperty("font-size",el.dataset.eeMobileOriginalSize,"important");
        delete el.dataset.eeMobileOriginalSize;
      }
      return;
    }

    var parent=el.parentElement;
    if(!parent) return;
    var available=Math.max(0,parent.clientWidth-2);
    if(!available) return;

    var computed=window.getComputedStyle(el);
    var current=parseFloat(computed.fontSize);
    if(!current) return;

    if(!el.dataset.eeMobileOriginalSize){
      el.dataset.eeMobileOriginalSize=current+"px";
    }else{
      el.style.setProperty("font-size",el.dataset.eeMobileOriginalSize,"important");
      current=parseFloat(window.getComputedStyle(el).fontSize)||current;
    }

    var size=current;
    while(size>30&&longestWordWidth(el,size)>available) size-=1;
    if(size<current) el.style.setProperty("font-size",size+"px","important");
  }

  function fitAll(){
    var titles=document.querySelectorAll(SELECTORS);
    for(var i=0;i<titles.length;i+=1) fitTitle(titles[i]);
    return titles.length;
  }

  function queueFit(){
    if(queued) return;
    queued=true;
    window.requestAnimationFrame(function(){
      queued=false;
      fitAll();
    });
  }

  function activate(){
    if(active) return;
    if(!document.querySelector(SELECTORS)) return;
    active=true;

    queueFit();
    window.addEventListener("load",queueFit,{once:true});
    window.addEventListener("resize",queueFit,{passive:true});
    window.addEventListener("orientationchange",queueFit,{passive:true});

    if("MutationObserver" in window&&document.body){
      observer=new MutationObserver(queueFit);
      observer.observe(document.body,{subtree:true,childList:true,characterData:true});
    }
  }

  if(document.readyState==="loading") document.addEventListener("DOMContentLoaded",activate,{once:true});
  else activate();
}());
//

