(function(){
  "use strict";
  function stabilize(){
    var archive=document.getElementById("ee-archive-app");
    if(!archive) return false;
    Array.prototype.forEach.call(archive.querySelectorAll("img"),function(image){
      image.style.setProperty("content-visibility","visible","important");
      image.style.setProperty("visibility","visible","important");
      image.style.setProperty("opacity","1","important");
      if(image.currentSrc&&!image.getAttribute("src")) image.setAttribute("src",image.currentSrc);
    });
    return true;
  }
  function start(){
    if(!stabilize()) return;
    window.setTimeout(stabilize,500);
    window.setTimeout(stabilize,1600);
  }
  if(document.readyState==="loading") document.addEventListener("DOMContentLoaded",start,{once:true});
  else start();
}());
