(function(){
  "use strict";

  var postBody=document.querySelector(".post-body");
  if(!postBody) return;
  var TOKEN="1010lScn";

  function cleanText(value){
    return String(value||"").replace(/\u00a0/g," ").replace(/\s+/g," ").trim();
  }

  function isAppleUrl(value){
    try{
      var url=new URL(value,location.href);
      return /(^|\.)apple\.com$/i.test(url.hostname.replace(/^www\./,""));
    }catch(error){return false;}
  }

  function addToken(value){
    try{
      var url=new URL(value,location.href);
      if(!isAppleUrl(url.href)) return value;
      url.searchParams.set("at",TOKEN);
      if(!url.searchParams.has("itscg")) url.searchParams.set("itscg","30200");
      return url.toString();
    }catch(error){return value;}
  }

  function isExcludedArtwork(image){
    if(image.closest(".ee-no-apple-affiliate")) return true;
    var src=(image.getAttribute("src")||"").toLowerCase();
    var alt=(image.getAttribute("alt")||"").toLowerCase();
    return src.indexOf("qr-code")!==-1 ||
           src.indexOf("get-it-on-apple-books")!==-1 ||
           alt.indexOf("get it on apple books")!==-1;
  }

  var seen=Object.create(null);
  var items=[];
  var sourceRows=[];
  var appleLinks=postBody.querySelectorAll('a[href*="tv.apple.com"],a[href*="books.apple.com"]');

  Array.prototype.forEach.call(appleLinks,function(anchor){
    anchor.href=addToken(anchor.href);
    anchor.rel="nofollow sponsored noopener";

    var image=anchor.querySelector("img");
    if(!image||isExcludedArtwork(image)) return;

    anchor.classList.add("ee-safe-affiliate-source");
    anchor.hidden=true;
    anchor.setAttribute("aria-hidden","true");

    var sourceRow=anchor.closest(".separator");
    if(sourceRow&&sourceRows.indexOf(sourceRow)===-1) sourceRows.push(sourceRow);

    var key=anchor.href+"|"+(image.getAttribute("src")||"");
    if(seen[key]) return;
    seen[key]=true;
    items.push({href:anchor.href,image:image});
  });

  /*
   * The generated safe-affiliate module uses clones of the legacy Apple
   * artwork. The original image anchors are hidden above, but old Blogger
   * .separator rows and adjacent <br> spacers can otherwise remain in flow.
   * Collapse only rows whose visible content disappears after those exact
   * source anchors are removed. This is local to the already-discovered Apple
   * rows: no document-wide cleanup pass, observer or timer is introduced.
   */
  function isAppleSpacer(node){
    if(!node||node.nodeType!==1) return false;
    if(node.tagName==="BR") return true;
    return node.matches(".separator")&&
      !node.querySelector("img,iframe,video,audio,object,embed,form,table,ins.adsbygoogle")&&
      cleanText(node.textContent)==="";
  }

  function removeAdjacentAppleSpacers(row){
    ["previousSibling","nextSibling"].forEach(function(direction){
      var node=row[direction];
      while(node){
        var next=node[direction];
        if(node.nodeType===3&&cleanText(node.nodeValue)===""){node=next;continue;}
        if(node.nodeType===8){node=next;continue;}
        if(node.nodeType===1&&isAppleSpacer(node)){node.remove();node=next;continue;}
        break;
      }
    });
  }

  sourceRows.forEach(function(row){
    var clone=row.cloneNode(true);
    Array.prototype.forEach.call(clone.querySelectorAll(".ee-safe-affiliate-source"),function(source){
      source.remove();
    });

    if(
      !clone.querySelector("img,iframe,video,audio,object,embed,form,table,ins.adsbygoogle")&&
      cleanText(clone.textContent)===""
    ){
      row.hidden=true;
      row.setAttribute("aria-hidden","true");
      removeAdjacentAppleSpacers(row);
    }
  });

  if(!items.length) return;

  var module=document.createElement("section");
  module.className="ee-safe-affiliate";
  module.setAttribute("aria-label","Related titles on Apple");

  var title=document.createElement("span");
  title.className="ee-safe-affiliate__title";
  title.textContent="Related on Apple";

  var disclosure=document.createElement("span");
  disclosure.className="ee-safe-affiliate__disclosure";
  disclosure.textContent="Affiliate links";

  var grid=document.createElement("div");
  grid.className="ee-safe-affiliate__grid";

  items.forEach(function(item){
    var card=document.createElement("a");
    card.className="ee-safe-affiliate__card";
    card.href=addToken(item.href);
    card.target="_blank";
    card.rel="nofollow sponsored noopener";

    var image=item.image.cloneNode(true);
    image.removeAttribute("width");
    image.removeAttribute("height");
    image.setAttribute("loading","lazy");
    image.setAttribute("decoding","async");
    if(!image.getAttribute("alt")) image.setAttribute("alt","Related title on Apple");
    card.appendChild(image);
    grid.appendChild(card);
  });

  var actions=document.createElement("div");
  actions.className="ee-safe-affiliate__actions";
  var cta=document.createElement("a");
  cta.className="ee-safe-affiliate__cta";
  cta.href=addToken("https://tv.apple.com/channel/tvs.sbd.4000");
  cta.target="_blank";
  cta.rel="nofollow sponsored noopener";
  cta.textContent="Browse Apple TV";
  actions.appendChild(cta);

  module.appendChild(title);
  module.appendChild(disclosure);
  module.appendChild(grid);
  module.appendChild(actions);
  postBody.appendChild(module);
}());
