(function(){
  "use strict";

  var postBody=document.querySelector(".post-body");
  if(!postBody) return;

  var headingPatterns=[
    "check out these related articles",
    "check out these other related articles",
    "related articles from the electric eye archives",
    "articles from the electric eye archives",
    "more from the electric eye archives",
    "more from electric eye",
    "related on electric eye",
    "related from electric eye",
    "you may also like",
    "you might also like",
    "similar articles",
    "similar posts",
    "from the electric eye archives",
    "from electric eye archives",
    "similar articles from the electric eye archives",
    "similar articles from ee archives"
  ];

  var utilityPatterns=[
    "sponsored content",
    "sponsored items",
    "sponsored item",
    "you may also enjoy the following sponsored content",
    "you may also enjoy the following sponsored item",
    "you may also enjoy the following reading material",
    "click here to subscribe to apple tv",
    "click here or scan the qr code",
    "scan the qr code",
    "subscribe to apple tv"
  ];

  function cleanText(value){
    return String(value||"").replace(/\u00a0/g," ").replace(/\s+/g," ").trim();
  }
  function norm(value){return cleanText(value).toLowerCase();}
  function hide(node){
    if(!node||node.nodeType!==1) return;
    node.classList.add("ee-legacy-hidden");
    node.setAttribute("aria-hidden","true");
  }
  function linksIn(node){
    return node&&node.querySelectorAll ? Array.prototype.slice.call(node.querySelectorAll("a[href]")) : [];
  }
  function isInternalArticleLink(link){
    return !!(link&&link.href&&/(?:electriceyerock\.com|electriceyephoto\.blogspot\.com)\/20\d\d\//i.test(link.href));
  }
  function isAppleLink(link){
    if(!link||!link.href) return false;
    return /^(?:https?:)?\/\/(?:music|tv|books|apps|geo\.music)\.apple\.com\//i.test(link.href) ||
           /^(?:https?:)?\/\/itunes\.apple\.com\//i.test(link.href);
  }
  function srcOf(img){
    return String(
      img.getAttribute("data-ee-src")||img.getAttribute("data-src")||
      img.getAttribute("data-original")||img.currentSrc||img.getAttribute("src")||""
    ).toLowerCase();
  }
  function artworkFile(img){
    var src=srcOf(img);
    return src ? src.split("/").pop().split("?")[0].toLowerCase() : "";
  }
  function isLegacyAppleAsset(img){
    var src=srcOf(img);
    var file=artworkFile(img);
    return /^540x304(?:mw)?(?:-\d+)?\.webp$/.test(file) ||
           /^600x900bb(?:-\d+)?\.(?:png|jpe?g|webp)$/.test(file) ||
           /qr-code/i.test(src) || /get-it-on-apple-books/i.test(src);
  }
  function hasValidAppleDestination(img){
    var anchor=img.closest("a[href]");
    return !!(anchor&&isAppleLink(anchor));
  }
  function isProtected(node){
    if(!node||!node.querySelector) return false;
    return !!node.querySelector(
      ".ee-safe-affiliate,.ee-gallery,.ee-gallery-more,.ee-related-posts,.related-posts,"+
      "ins.adsbygoogle,.google-auto-placed,.separator-ad,.ad-container"
    );
  }
  function hasNonLegacyMedia(node){
    if(!node||!node.querySelectorAll) return false;
    if(node.querySelector("iframe,video,audio,object,embed,form,table")) return true;
    return Array.prototype.some.call(node.querySelectorAll("img"),function(img){return !isLegacyAppleAsset(img);});
  }
  function hasAnyMedia(node){
    return !!(node&&node.querySelector&&node.querySelector(
      "img,iframe,video,audio,object,embed,form,table,.ee-gallery,.ee-safe-affiliate,.ee-related-posts,.related-posts"
    ));
  }

  function hideOrphanAppleArtwork(){
    Array.prototype.forEach.call(postBody.querySelectorAll("img"),function(img){
      if(img.closest(".ee-safe-affiliate")) return;
      var src=srcOf(img);
      var file=artworkFile(img);
      var isBadge=/qr-code/i.test(src)||/get-it-on-apple-books/i.test(src);
      var isKnown=/^540x304(?:mw)?(?:-\d+)?\.webp$/.test(file)||
                  /^600x900bb(?:-\d+)?\.(?:png|jpe?g|webp)$/.test(file);

      if(isBadge || (isKnown&&!hasValidAppleDestination(img))){
        img.setAttribute("data-ee-no-gallery","true");
        var asset=img.closest("a")||img;
        hide(asset);

        var generated=img.closest(".ee-photo-link,.ee-gallery-item,.ee-photo-item,.ee-article-hero");
        if(generated&&!hasValidAppleDestination(img)) hide(generated);
      }
    });
  }

  function isHeading(node){
    if(!node||!node.textContent||node.closest(".ee-safe-affiliate")) return false;
    var text=norm(node.textContent);
    if(!text||text.length>260) return false;
    return headingPatterns.some(function(pattern){
      return text===pattern||text===pattern+":"||text.indexOf(pattern)!==-1;
    });
  }

  function isLegacyRecommendationBlock(node){
    if(!node||node.nodeType!==1||node.closest(".ee-safe-affiliate")) return false;
    if(isProtected(node)||hasNonLegacyMedia(node)) return false;

    var links=linksIn(node);
    var internal=links.filter(isInternalArticleLink);
    var apple=links.filter(isAppleLink);
    if(internal.length>=2) return true;

    var text=norm(node.textContent);
    if(text.length>1800) return false;
    var hasHeading=headingPatterns.some(function(pattern){return text.indexOf(pattern)!==-1;});
    var hasUtility=utilityPatterns.some(function(pattern){return text.indexOf(pattern)!==-1;});

    if(hasHeading&&internal.length>=1) return true;
    if(hasUtility&&(internal.length+apple.length)>=1) return true;
    if(apple.length>=1&&links.length===apple.length) return true;
    return false;
  }

  function isLegacyRecommendationRow(row){
    if(!row||row.nodeType!==1||row.closest(".ee-safe-affiliate")) return false;
    if(row.matches(".ee-safe-affiliate,.ee-gallery,.ee-gallery-more,iframe,video,audio,object,embed,form,table,ins.adsbygoogle,.google-auto-placed,.ad-container")) return false;
    if(row.querySelector(".ee-safe-affiliate,.ee-gallery,.ee-gallery-more,iframe,video,audio,object,embed,form,table,ins.adsbygoogle,.google-auto-placed,.ad-container")) return false;

    var images=Array.prototype.slice.call(row.querySelectorAll("img"));
    if(images.some(function(img){return !isLegacyAppleAsset(img);})) return false;

    var links=linksIn(row);
    var internal=links.filter(isInternalArticleLink);
    var apple=links.filter(isAppleLink);
    var text=cleanText(row.textContent);

    if(internal.length>=1&&internal.length===links.length) return true;
    if(apple.length>=1&&apple.length===links.length) return true;
    if(!links.length&&!images.length&&text&&text.length<=220){
      return String(row.style&&row.style.textAlign||"").toLowerCase()==="center";
    }
    return false;
  }

  function smallestLegacyAncestor(heading){
    var node=heading.parentElement;
    while(node&&node!==postBody){
      if(isLegacyRecommendationBlock(node)) return node;
      node=node.parentElement;
    }
    return null;
  }

  function hideFollowingLegacySiblings(start){
    var row=start?start.nextElementSibling:null;
    var guard=0;
    while(row&&guard<80){
      guard+=1;
      if(isLegacyRecommendationBlock(row)||isLegacyRecommendationRow(row)){
        var next=row.nextElementSibling;
        hide(row);
        row=next;
        continue;
      }
      var text=cleanText(row.textContent);
      var hasMedia=!!row.querySelector("img,iframe,video,audio,object,embed,form,table");
      if(!text&&!hasMedia){
        var nextEmpty=row.nextElementSibling;
        hide(row);
        row=nextEmpty;
        continue;
      }
      break;
    }
  }

  function hideHeadingBasedSections(){
    Array.prototype.forEach.call(
      postBody.querySelectorAll("div,p,h2,h3,h4,strong,b,u,span"),
      function(node){
        if(!isHeading(node)||node.closest(".ee-legacy-hidden")) return;
        var wrapper=smallestLegacyAncestor(node);
        if(wrapper){hide(wrapper);hideFollowingLegacySiblings(wrapper);}
        else{hide(node);hideFollowingLegacySiblings(node);}
      }
    );
  }

  function isLinkOnlyRow(node){
    if(!node||hasAnyMedia(node)) return false;
    var text=cleanText(node.textContent);
    if(!text||text.length>220) return false;
    var links=linksIn(node);
    if(!links.length||!links.every(isInternalArticleLink)) return false;

    var clone=node.cloneNode(true);
    Array.prototype.forEach.call(clone.querySelectorAll("a"),function(a){a.remove();});
    return cleanText(clone.textContent).length<12;
  }

  function isEmptySpacer(node){
    return !!(node&&node.nodeType===1&&!hasAnyMedia(node)&&cleanText(node.textContent)==="");
  }

  function hideUnlabelledRuns(){
    var children=Array.prototype.slice.call(postBody.children);
    var i=0;
    while(i<children.length){
      if(!isLinkOnlyRow(children[i])){i+=1;continue;}
      var run=[];
      var j=i;
      while(j<children.length){
        if(isLinkOnlyRow(children[j])||isEmptySpacer(children[j])){run.push(children[j]);j+=1;continue;}
        break;
      }
      if(run.filter(isLinkOnlyRow).length>=3) run.forEach(hide);
      i=Math.max(j,i+1);
    }
  }

  function hideNestedLinkContainers(){
    Array.prototype.forEach.call(postBody.querySelectorAll("div"),function(container){
      if(container.closest(".ee-legacy-hidden")||hasAnyMedia(container)) return;
      var text=cleanText(container.textContent);
      if(!text||text.length>1200) return;
      var links=linksIn(container);
      if(links.length<3||!links.every(isInternalArticleLink)) return;

      var clone=container.cloneNode(true);
      Array.prototype.forEach.call(clone.querySelectorAll("a"),function(a){a.remove();});
      var remainder=norm(clone.textContent);
      var harmless=!remainder||
        remainder==="related articles"||remainder==="related articles:"||
        remainder.indexOf("check out these related articles")!==-1||
        remainder.indexOf("electric eye archives")!==-1;
      if(harmless) hide(container);
    });
  }

  function hideUtilityRows(){
    Array.prototype.forEach.call(postBody.querySelectorAll("div,p,span"),function(node){
      if(node.closest(".ee-safe-affiliate")||hasAnyMedia(node)) return;
      var text=norm(node.textContent);
      if(!text||text.length>240) return;
      if(utilityPatterns.some(function(pattern){
        return text===pattern||text===pattern+":"||text.indexOf(pattern)===0;
      })) hide(node);
    });
  }

  function isProtectedElement(element){
    if(!element||element.nodeType!==1) return false;
    return element.matches(
      ".ee-gallery,.ee-safe-affiliate,.ee-affiliate-v6,script,style,noscript,iframe,video,audio,object,embed,form,table,ins.adsbygoogle,.separator-ad,.ad-container"
    )||Boolean(element.querySelector(
      ".ee-gallery,.ee-safe-affiliate,.ee-affiliate-v6,iframe,video,audio,object,embed,form,table,ins.adsbygoogle,.separator-ad,.ad-container"
    ));
  }

  function isDisposableElement(element){
    if(!element||element.nodeType!==1||isProtectedElement(element)) return false;
    if(element.tagName==="BR") return true;
    if(element.querySelector("img,iframe,video,audio,object,embed,form,table,ins.adsbygoogle")) return false;
    return cleanText(element.textContent)==="";
  }

  function trimTrailingDebris(container){
    if(!container||container.nodeType!==1||isProtectedElement(container)) return;
    var safety=0;
    while(container.lastChild&&safety<10000){
      safety+=1;
      var node=container.lastChild;
      if(node.nodeType===3){if(cleanText(node.nodeValue)===""){node.remove();continue;}break;}
      if(node.nodeType===8){node.remove();continue;}
      if(node.nodeType!==1||isProtectedElement(node)) break;
      trimTrailingDebris(node);
      if(isDisposableElement(node)){node.remove();continue;}
      break;
    }
  }

  function cleanBeforeGalleries(){
    Array.prototype.forEach.call(postBody.querySelectorAll(".ee-gallery"),function(gallery){
      var node=gallery.previousSibling;
      var safety=0;
      while(node&&safety<10000){
        safety+=1;
        var previous=node.previousSibling;
        if(node.nodeType===3){
          if(cleanText(node.nodeValue)===""){node.remove();node=previous;continue;}
          break;
        }
        if(node.nodeType===8){node.remove();node=previous;continue;}
        if(node.nodeType!==1||isProtectedElement(node)) break;
        trimTrailingDebris(node);
        if(isDisposableElement(node)){node.remove();node=previous;continue;}
        break;
      }
    });
  }

  function runLegacyCleanup(){
    hideOrphanAppleArtwork();
    hideUtilityRows();
    hideHeadingBasedSections();
    hideUnlabelledRuns();
    hideNestedLinkContainers();
  }

  /* Run now, before Gallery Engine detection on DOMContentLoaded. */
  runLegacyCleanup();

  document.addEventListener("ee:gallery-rendered",function(){
    runLegacyCleanup();
    cleanBeforeGalleries();
  });
}());
