(function(){
  "use strict";

  var BODY_SELECTOR = "#post-body";
  var AD_CLIENT = "ca-pub-1626857871792797";
  var AD_SLOT = "3232028532";
  var MIN_PARAGRAPH_LENGTH = 80;

  function isManualAd(node){
    return !node.closest(".google-auto-placed");
  }

  function alreadyHasManualArticleAd(body){
    var selectors = [
      "#before-ad ins.adsbygoogle",
      "#after-ad ins.adsbygoogle",
      "#post-footer-ads ins.adsbygoogle",
      "#post-body ins.adsbygoogle",
      "#post-body [data-ad-client][data-ad-slot]"
    ].join(",");

    var ads = document.querySelectorAll(selectors);
    for(var i = 0; i < ads.length; i += 1){
      if(isManualAd(ads[i])) return true;
    }
    return false;
  }

  function paragraphIsSuitable(paragraph){
    if(!paragraph || paragraph.nodeType !== 1) return false;
    if(paragraph.closest(".ee-gallery, figure, table, blockquote, .separator, .google-auto-placed, .adsbygoogle, script, style")) return false;

    var text = (paragraph.textContent || "").replace(/\s+/g," ").trim();
    return text.length >= MIN_PARAGRAPH_LENGTH;
  }

  function findInsertionPoint(body){
    var paragraphs = Array.prototype.filter.call(
      body.querySelectorAll("p"),
      paragraphIsSuitable
    );

    if(paragraphs.length >= 3) return paragraphs[2];
    if(paragraphs.length >= 1) return paragraphs[paragraphs.length - 1];

    var children = body.children;
    var meaningful = [];
    for(var i = 0; i < children.length; i += 1){
      var child = children[i];
      if(child.matches("script, style, figure, table, iframe, video, audio, .separator, .ee-gallery, .google-auto-placed, .adsbygoogle")) continue;
      var text = (child.textContent || "").replace(/\s+/g," ").trim();
      if(text.length >= MIN_PARAGRAPH_LENGTH) meaningful.push(child);
    }

    if(meaningful.length >= 2) return meaningful[1];
    if(meaningful.length === 1) return meaningful[0];
    return null;
  }

  function buildAd(){
    var wrapper = document.createElement("div");
    wrapper.className = "ee-article-opening-ad";
    wrapper.setAttribute("aria-label","Advertisement");

    var unit = document.createElement("ins");
    unit.className = "adsbygoogle";
    unit.style.display = "block";
    unit.style.textAlign = "center";
    unit.setAttribute("data-ad-layout","in-article");
    unit.setAttribute("data-ad-format","fluid");
    unit.setAttribute("data-ad-client",AD_CLIENT);
    unit.setAttribute("data-ad-slot",AD_SLOT);

    wrapper.appendChild(unit);
    return wrapper;
  }

  function install(){
    var body = document.querySelector(BODY_SELECTOR);
    if(!body || body.querySelector(".ee-article-opening-ad")) return;
    if(alreadyHasManualArticleAd(body)) return;

    var insertionPoint = findInsertionPoint(body);
    if(!insertionPoint || !insertionPoint.parentNode) return;

    var ad = buildAd();
    insertionPoint.parentNode.insertBefore(ad,insertionPoint.nextSibling);

    try{
      (window.adsbygoogle = window.adsbygoogle || []).push({});
    }catch(error){
      ad.remove();
    }
  }

  if(document.readyState === "loading"){
    document.addEventListener("DOMContentLoaded",install,{once:true});
  }else{
    install();
  }
}());
