(function(){
  "use strict";

  var TOKEN="1010lScn";
  var APPLE_SERVICE_HOST=/^(?:[a-z0-9-]+\.)*(?:music|itunes|podcasts|tv|books|apps)\.apple\.com$/i;

  function isEligible(url){
    return APPLE_SERVICE_HOST.test(url.hostname);
  }

  function mergeRel(anchor){
    var values=(anchor.getAttribute("rel")||"").split(/\s+/).filter(Boolean);
    ["nofollow","sponsored","noopener"].forEach(function(value){
      if(values.indexOf(value)===-1) values.push(value);
    });
    anchor.setAttribute("rel",values.join(" "));
  }

  function decorate(anchor){
    if(!anchor || anchor.nodeType!==1 || anchor.tagName!=="A") return;
    if(anchor.getAttribute("data-ee-apple-link-policy")==="preserve") return;
    var href=anchor.getAttribute("href");
    if(!href || href.charAt(0)==="#" || /^javascript:/i.test(href)) return;

    try{
      var url=new URL(href,document.baseURI);
      if(!isEligible(url)) return;

      /* Preserve all existing campaign/content parameters and enforce attribution. */
      url.searchParams.set("at",TOKEN);
      if(/^(?:[a-z0-9-]+\.)*music\.apple\.com$/i.test(url.hostname)){
        url.searchParams.set("app","music");
      }

      anchor.href=url.toString();
      anchor.target="_blank";
      mergeRel(anchor);
      anchor.setAttribute("data-ee-apple-affiliate","new-tab");
    }catch(error){
      /* Leave malformed or non-HTTP links untouched. */
    }
  }

  function scan(root){
    if(!root) return;
    if(root.nodeType===1 && root.matches && root.matches("a[href]")) decorate(root);
    var links=root.querySelectorAll ? root.querySelectorAll("a[href]") : [];
    Array.prototype.forEach.call(links,decorate);
  }

