(function(){
  "use strict";
  var CONFIG={enabled:true,endpoint:"https://script.google.com/macros/s/AKfycbyxbAkw_Mcl_iXwV_N-JHS2rTf_KBwZlJKsD1RVECUlXR7WNXBt0eUAEIevZOiHXJpcaA/exec",callbackTimeout:15000,hoverDelay:200,initialPerCategory:4,revealStep:4,maxPerCategory:24};
  var CATEGORY_LABEL={LISTEN:"Listen",WATCH:"Watch",READ:"Read"};
  var context=document.querySelector(".ee-apple-context[data-ee-post-id]");
  var postBody=document.querySelector(".is-post .post-body");
  if(!CONFIG.enabled||!context||!postBody)return;

  function norm(value){return String(value||"").replace(/\s+/g," ").trim().toLowerCase();}
  function hasAppleLink(node){return !!(node&&node.querySelector&&node.querySelector('a[href*="apple.com"],a[href*="itunes.com"]'));}
  function hasExistingSection(){
    return !!document.querySelector(".ee-related-on-apple,[data-ee-apple-generated],[data-ee-apple-recommendations]");
  }
  function removeLegacySafeAffiliate(){
    var modules=postBody.querySelectorAll(".ee-safe-affiliate:not(.ee-apple-generated)");
    Array.prototype.forEach.call(modules,function(module){
      var title=module.querySelector(".ee-safe-affiliate__title");
      var relatedTitle=title&&norm(title.textContent)==="related on apple";
      var relatedLabel=norm(module.getAttribute("aria-label"))==="related titles on apple";
      if((relatedTitle||relatedLabel)&&module.querySelector(".ee-safe-affiliate__grid"))module.remove();
    });
  }
  if(hasExistingSection())return;

  function el(name,className,text){var node=document.createElement(name);if(className)node.className=className;if(text!=null)node.textContent=text;return node;}
  function price(item){if(!item.price)return "";if(item.price.formatted)return item.price.formatted;if(item.price.currency&&typeof item.price.value==="number")try{return new Intl.NumberFormat(undefined,{style:"currency",currency:item.price.currency}).format(item.price.value);}catch(error){}return "";}
  function validPayload(payload){return payload&&String(payload.postId)===String(context.getAttribute("data-ee-post-id"))&&Array.isArray(payload.categories);}

  function render(payload){
    if(!validPayload(payload)||hasExistingSection())return;
    var categories=payload.categories.filter(function(group){return group&&CATEGORY_LABEL[group.category]&&Array.isArray(group.items)&&group.items.length;});
    if(!categories.length)return;
    removeLegacySafeAffiliate();

    var module=el("section","ee-safe-affiliate ee-apple-generated");
    module.setAttribute("data-ee-apple-generated","v1");
    module.setAttribute("aria-labelledby","ee-apple-generated-title");

    var head=el("header","ee-apple-generated__head");
    var heading=el("div","ee-apple-generated__heading");
    var title=el("h2","ee-apple-generated__title","Related on Apple");
    title.id="ee-apple-generated-title";
    heading.appendChild(title);
    head.appendChild(heading);
    head.appendChild(el("p","ee-apple-generated__disclosure","Some links are affiliate links."));
    module.appendChild(head);

    categories.forEach(function(group){
      var section=el("section","ee-apple-section");
      var bar=el("div","ee-apple-section__bar");
      var categoryHeading=el("h3","ee-apple-section__title",CATEGORY_LABEL[group.category]);
      bar.appendChild(categoryHeading);
      section.appendChild(bar);

      var shelf=el("div","ee-apple-shelf");
      var items=group.items.slice(0,Math.min(CONFIG.maxPerCategory,24));
      var shelfId="ee-apple-shelf-"+String(group.category||"").toLowerCase();
      shelf.id=shelfId;

      items.forEach(function(item,index){
        var card=el("a","ee-apple-card");
        card.href=item.url||item.canonicalAppleUrl;
        card.target="_blank";
        card.rel="nofollow sponsored noopener";
        if(item.affiliateStatus==="TOOLBOX_REQUIRED"||item.affiliateStatus==="NOT_CLAIMED_COMMISSIONABLE"){
          card.setAttribute("data-ee-apple-link-policy","preserve");
        }
        card.dataset.eeAppleItem=JSON.stringify({
          title:item.title,
          creator:item.creator,
          mediaType:item.mediaType,
          artworkUrl:item.artworkUrl,
          description:item.description||"",
          releaseDate:item.releaseDate||"",
          director:item.director||"",
          cast:item.cast||"",
          narrator:item.narrator||"",
          publisher:item.publisher||"",
          price:price(item),
          relationshipContext:item.relationshipContext||item.relevanceReason||""
        });

        if(index>=CONFIG.initialPerCategory)card.hidden=true;
        var image=el("img","ee-apple-artwork");
        image.src=item.artworkUrl;
        image.alt="";
        image.loading="lazy";
        image.decoding="async";
        image.setAttribute("data-ee-no-gallery","true");
        card.appendChild(image);

        var copy=el("span","ee-apple-card__copy");
        copy.appendChild(el("span","ee-apple-card__title",item.title));
        if(item.creator)copy.appendChild(el("span","ee-apple-card__creator",item.creator));
        var meta=[item.mediaType,price(item)].filter(Boolean).join(" · ");
        if(meta)copy.appendChild(el("span","ee-apple-card__meta",meta));
        card.appendChild(copy);
        shelf.appendChild(card);
      });

      section.appendChild(shelf);

      if(items.length>CONFIG.initialPerCategory){
        var toggle=el("button","ee-apple-toggle","More");
        toggle.type="button";
        toggle.setAttribute("aria-expanded","false");
        toggle.setAttribute("aria-controls",shelfId);

        toggle.addEventListener("click",function(){
          var cards=shelf.querySelectorAll(".ee-apple-card");
          var visible=Array.prototype.filter.call(cards,function(card){return !card.hidden;}).length;

          if(visible>=cards.length){
            Array.prototype.forEach.call(cards,function(card,index){
              card.hidden=index>=CONFIG.initialPerCategory;
            });
            toggle.textContent="More";
            toggle.setAttribute("aria-expanded","false");
            return;
          }

          var next=Math.min(cards.length,visible+CONFIG.revealStep);
          Array.prototype.forEach.call(cards,function(card,index){
            card.hidden=index>=next;
          });
          toggle.textContent=next>=cards.length?"Show less":"More";
          toggle.setAttribute("aria-expanded",String(next>CONFIG.initialPerCategory));
        });

        bar.appendChild(toggle);
      }

      module.appendChild(section);
    });

    var readMore=document.getElementById("ee-read-more");
    if(readMore&&readMore.parentNode)readMore.parentNode.insertBefore(module,readMore);
    else postBody.insertAdjacentElement("afterend",module);
    setupPopover(module);
  }

  function setupPopover(module){
    if(!window.matchMedia("(hover:hover) and (pointer:fine)").matches)return;

    var pop=el("div","ee-apple-popover");
    pop.hidden=true;
    pop.setAttribute("role","tooltip");
    document.body.appendChild(pop);

    var timer=null,active=null;

    function close(){
      window.clearTimeout(timer);
      timer=null;
      active=null;
      pop.classList.remove("is-open");
      window.setTimeout(function(){if(!pop.classList.contains("is-open"))pop.hidden=true;},130);
    }

    function position(card){
      var r=card.getBoundingClientRect(),p=pop.getBoundingClientRect(),gap=10;
      var top=r.bottom+gap;
      if(top+p.height>window.innerHeight-10)top=Math.max(10,r.top-p.height-gap);
      var left=Math.min(window.innerWidth-p.width-10,Math.max(10,r.left+(r.width-p.width)/2));
      pop.style.top=Math.round(top)+"px";
      pop.style.left=Math.round(left)+"px";
    }

    function open(card){
      window.clearTimeout(timer);
      timer=window.setTimeout(function(){
        if(active!==card)return;
        var item;
        try{item=JSON.parse(card.dataset.eeAppleItem);}catch(error){return;}

        pop.innerHTML="";
        var image=el("img","ee-apple-popover__art");
        image.src=item.artworkUrl;
        image.alt="";
        pop.appendChild(image);

        var copy=el("div","");
        copy.appendChild(el("h4","ee-apple-popover__title",item.title));
        if(item.creator)copy.appendChild(el("p","ee-apple-popover__creator",item.creator));

        var details=[item.mediaType,item.releaseDate?String(item.releaseDate).slice(0,4):"",item.price].filter(Boolean).join(" · ");
        if(details)copy.appendChild(el("p","ee-apple-popover__type",details));

        var credits=[
          item.director&&"Director: "+item.director,
          item.cast&&"Cast: "+item.cast,
          item.narrator&&"Narrator: "+item.narrator,
          item.publisher&&"Publisher: "+item.publisher
        ].filter(Boolean).join(" · ");
        if(credits)copy.appendChild(el("p","ee-apple-popover__credits",credits));

        if(item.description)copy.appendChild(el("p","ee-apple-popover__description",item.description));

        pop.appendChild(copy);
        pop.hidden=false;
        position(card);
        requestAnimationFrame(function(){pop.classList.add("is-open");});
      },CONFIG.hoverDelay);
    }

    module.addEventListener("pointerover",function(event){
      var card=event.target.closest(".ee-apple-card");
      if(card&&module.contains(card)){active=card;open(card);}
    });
    module.addEventListener("pointerout",function(event){
      var card=event.target.closest(".ee-apple-card");
